/* Meridian Quest content pack — quests, Spanish. Mirror every change in quests.en.js. */
const FQES={npc:"fred",title:"🐾 Misión personal secreta: Los archivos de Frederick",start:"a",nodes:{
 a:{say:"Frederick deja una carpeta mordisqueada a tus pies. Adentro: recordatorios del veterinario en servilletas, un horario de comida que vive en la cabeza de tres personas, y 40 fotos majestuosas sin publicar. Este perro necesita un sistema.",
    codex:"Las operaciones personales son disciplina de PM con menos riesgo: una sola fuente de verdad, recordatorios recurrentes para todo lo cíclico (comida, veterinario, peluquería), y una lista compartida. Si se repite, lleva recordatorio — la memoria no es un sistema.",
    q:"¿Cómo organizas la vida de Frederick?",
    ch:[{t:"Una nota gigante pegada al refrigerador",out:{r:"mid",concept:"Fuente única de verdad",why:"SÍ es una sola fuente — pero nada le recuerda nada a nadie, y la cita del veterinario muere el día que alguien necesita el refrigerador. Medio crédito.",beat:"Frederick olfatea la nota. No le impresiona."}},
        {t:"Un calendario compartido con recordatorios recurrentes + una lista común",next:"b"},
        {t:"Contratar un asistente para el perro",out:{r:"bad",concept:"Fuente única de verdad",why:"Un asistente para la agenda de un perro es una línea de nómina para un problema que resuelven dos recordatorios recurrentes.",beat:"Marcus aparece de la nada. «¿Un QUÉ para el perro?»"}}]},
 b:{say:"Su público espera. Cuarenta fotos majestuosas, cero publicaciones. ¿El plan de contenido de Frederick?",
    codex:"El trabajo creativo se hace por lotes: una sesión que produce un mes de contenido le gana a publicar cuando te acuerdas. La IA redacta los pies de foto; un humano aprueba antes de publicar — Frederick no puede aprobar, es un perro.",
    q:"El plan de contenido es…",
    ch:[{t:"Publicar cuando te acuerdes",out:{r:"mid",concept:"Lotes y programación",why:"Así va todo ahora — 40 fotos, cero publicaciones. El esfuerzo esporádico pierde contra un calendario aburrido, siempre. Medio crédito por honestidad.",beat:"Los fans de Frederick actualizan la página en vano."}},
        {t:"Día de lote mensual: la IA redacta, tú apruebas, un programador publica",out:{r:"ok",concept:"Lotes y programación",why:"Una hora al mes, la IA escribe, el humano conserva el criterio, el programador se encarga de recordar. La marca de Frederick: consistente.",beat:"La primera publicación programada llega a 200 me-gusta. Frederick sigue humilde."}},
        {t:"Dejar que la IA publique como Frederick, sin supervisión",out:{r:"bad",concept:"Lotes y programación",why:"El auto-posteo sin supervisión es como mueren las marcas. Sin revisión no hay piso.",beat:"En menos de una hora, la cuenta de Frederick promociona una cripto-estafa."}}]}}};
const QES=[
 {npc:"tovar",title:"El chatbot de 500 documentos",late:"Corporativo ha reescrito el manual varias veces desde que te traje esto. La pregunta no se ha movido.",start:"a",nodes:{
  a:{say:"Los gerentes de tienda me llaman todo el día con preguntas de políticas. Quiero un chatbot sobre estos 500 documentos — y corporativo los reescribe cada mes.",
     codex:"Dos formas de darle conocimiento a un modelo: entrenarlo dentro del modelo (lento, caro, congelado al terminar) — o mantenerlo en un índice consultable que el modelo lee al responder, fresco al instante en que un documento se actualiza.",
     q:"Los documentos cambian cada mes. ¿Dónde vive el conocimiento?",
     ch:[{t:"Entrenar un modelo a medida con los documentos",out:{r:"bad",concept:"RAG vs fine-tuning",why:"Reentrenar cada mes es perseguir documentos viejos con dinero. Para cuando termina el entrenamiento, corporativo ya reescribió el manual.",beat:"Priya, en voz baja: «Así perdimos al líder anterior»."}},
         {t:"Indexar los documentos; el bot recupera las páginas correctas por pregunta",next:"b"},
         {t:"Pegar los 500 documentos en cada prompt",out:{r:"bad",concept:"RAG vs fine-tuning",why:"Pagarías por 500 documentos en cada pregunta — y los modelos pierden el foco en entradas enormes.",beat:"Marcus se materializa con una calculadora. De forma ominosa."}}]},
  b:{say:"Indexar — bien. Una cosa más: ayer un gerente preguntó por una política que no existe en ningún documento. ¿Qué debe hacer el bot?",
     codex:"Un bot anclado responde solo desde texto recuperado. Cuando la búsqueda vuelve vacía, lo honesto es admitirlo o derivar a un humano — lo peligroso es dejar que el modelo improvise.",
     q:"No existe documento que coincida. El bot debería…",
     ch:[{t:"Responder igual con conocimiento general — suele sonar bien",out:{r:"bad",concept:"Anclaje y rechazo",why:"«Suena bien» es como nace el Viernes de Churros Gratis. Una respuesta sin fuente es una alucinación esperando a un cliente.",beat:"Camila, a tres escritorios: «Ni se te ocurra»."}},
         {t:"Decir «no tengo esa política» y derivar la pregunta al equipo de operaciones",out:{r:"ok",concept:"Anclaje y rechazo",why:"Un bot que admite el hueco — y le pasa la pregunta a un humano — genera confianza y muestra qué documentos faltan.",beat:"El director asiente lento. «El bot sabe lo que no sabe. No como mi sobrino»."}},
         {t:"Que el bot pida disculpas y termine el chat",out:{r:"mid",concept:"Anclaje y rechazo",why:"Seguro, pero sin salida — sin derivación humana, la pregunta real muere en el chat. Medio crédito: nada falso, nada útil.",beat:"Entregado con incidentes. El gerente llama al director de todos modos."}}]}}},
 {npc:"camila",title:"Viernes de Churros Gratis",late:"Lo del churro ya sobrevivió a su viernes. La gente lo sigue sacando, y yo sigo sin una solución que me convenza.",start:"a",nodes:{
  a:{say:"El bot piloto le acaba de prometer a un gerente el «Viernes de Churros Gratis — todas las sucursales». Esa política no existe. Los gerentes ya están preguntando.",
     codex:"Los modelos generan texto plausible — y cuando no saben, plausible significa inventado. Pedirlo por favor o bajar la aleatoriedad reduce variedad, no fabricación. Lo que funciona: las respuestas solo pueden venir de documentos recuperados, con cita.",
     q:"¿Cómo matas los churros imaginarios?",
     ch:[{t:"Agregar «no inventes cosas» a las instrucciones",out:{r:"mid",concept:"Control de alucinaciones",why:"Ayuda en los márgenes — y falla el día que importa. Las instrucciones empujan; no bloquean. Medio crédito por probar primero lo barato.",beat:"El bot inventa la «Amnistía del Martes de Tacos» una semana después."}},
         {t:"Poner la aleatoriedad en cero",out:{r:"bad",concept:"Control de alucinaciones",why:"Con temperatura cero el bot se equivoca con confianza, igual, todas las veces. Determinismo no es verdad.",beat:"Camila: «Ahora promete churros CONSISTENTEMENTE»."}},
         {t:"Anclar cada respuesta en texto recuperado — sin fuente, no hay respuesta",out:{r:"ok",concept:"Control de alucinaciones",why:"El anclaje ataca la causa: el bot dice solo lo que un documento real dice, lo cita, o admite que no tiene esa política.",beat:"Camila redacta el memo oficial de la Muerte del Viernes de Churros. Hay luto."}}]}}},
 {npc:"legal",title:"El contrato de 300 páginas",late:"El contrato se renovó desde que te pregunté. Las mismas trescientas páginas. La misma página doscientas.",start:"a",nodes:{
  a:{say:"Necesito preguntas y respuestas sobre el contrato de franquicia de 300 páginas. El prototipo brilla en la página 20 y se estrella en la 200.",
     codex:"Cada solicitud tiene un presupuesto de tokens — pagas cada palabra enviada, cada vez — y los modelos atienden de forma dispareja las entradas muy largas: el medio se hunde. Menos texto, mejor elegido, le gana a mandarlo todo.",
     q:"¿Cómo cubres las 300 páginas?",
     ch:[{t:"Trocear el contrato; recuperar solo las secciones relevantes por pregunta",out:{r:"ok",concept:"Ventanas de contexto",why:"La recuperación envía las tres páginas que importan en vez de cobrarle a legal las 300 cada vez — y la calidad aguanta en la página 200 igual que en la 20.",beat:"Dana cierra su laptop satisfecha, lo que en términos legales es un abrazo."}},
         {t:"Consultar un resumen único del contrato",out:{r:"mid",concept:"Ventanas de contexto",why:"Sirve para «la idea general» — falla en las preguntas de cláusula por las que existen los contratos. Medio crédito: bien de acompañante, mal de respuesta.",beat:"Dana: «El resumen dice ‘aplican términos estándar’. ¿CUÁLES términos, bot?»."}},
         {t:"Comprar una ventana de contexto gigante y mandar las 300 páginas siempre",out:{r:"bad",concept:"Ventanas de contexto",why:"El medio se hunde igual, y ahora cada pregunta de estacionamiento cuesta un contrato entero en tokens.",beat:"Aparece Marcus. Escuchó la palabra «comprar»."}}]}}},
 {npc:"marcus",title:"El reporte matutino",late:"Cuarenta minutos cada mañana, por cada mañana desde entonces. El número empeoró solito. Siéntate.",start:"a",nodes:{
  a:{say:"Alguien gasta 40 minutos cada mañana sacando las ventas de ayer, formateando el reporte y enviándolo a dirección. ¿Puede tu… robot… hacerlo?",
     codex:"Una llamada simple al modelo solo escribe texto — no puede tocar una base de datos ni enviar correos. Dale herramientas (ejecutar consulta, enviar correo) y puede decidir cuál usar y en qué orden: eso es un agente. Los pasos fijos van en código; el criterio va en el modelo.",
     q:"¿Cómo se automatiza el reporte matutino?",
     ch:[{t:"Un mega-prompt de «haz el reporte»",out:{r:"bad",concept:"Agentes y herramientas",why:"Un reporte hermoso lleno de números imaginarios — sin herramientas no hay datos: pura ficción disfrazada de hoja de cálculo.",beat:"Dirección felicita el formato. Luego lee los números."}},
         {t:"Un agente con herramientas: consultar → formatear → enviar",out:{r:"ok",concept:"Agentes y herramientas",why:"Datos reales por herramientas reales, orquestado por el modelo. Cuarenta minutos se vuelven cero.",beat:"Marcus: «Si el robot se rompe, sale de tu presupuesto». Sonríe. Probablemente."}},
         {t:"Decirle a Marcus que los robots no están listos",out:{r:"bad",concept:"Agentes y herramientas",why:"Llevan tiempo listos. El CFO que te pide automatización no es la persona a la que conviene quedarle mal.",beat:"Marcus anota algo en una libretita. No te gusta la libretita."}}]}}},
 {npc:"marcus",title:"La factura",late:"La factura siguió llegando. Ya trae amigas.",start:"a",nodes:{
  a:{say:"Esta factura. Diez mil tickets de soporte al mes, todos respondidos por el modelo más caro del mercado. La mayoría pregunta dónde está su pedido.",
     codex:"Hay modelos de varios tamaños y precios; los pequeños hacen el trabajo simple por centavos. Los sistemas pueden marcar sus propias respuestas de baja confianza — lo fácil va al modelo barato y solo lo difícil escala al premium.",
     q:"¿Cómo bajas la factura sin bajar la calidad?",
     ch:[{t:"Todo al modelo más barato, aceptar la caída",out:{r:"mid",concept:"Enrutamiento y costos",why:"La factura colapsa — y la calidad también, justo en los tickets difíciles que deciden si el cliente se queda. Medio crédito: buen instinto, sin salida de emergencia.",beat:"Las disputas de reembolso ahora las responde un modelo que cree que un churro es un zapato."}},
         {t:"Modelo barato primero; escalar lo difícil o dudoso al premium",out:{r:"ok",concept:"Enrutamiento y costos",why:"El barato se gana el pan con «¿dónde está mi pedido?»; el premium justifica su precio solo en el 10% espinoso. Misma calidad donde importa, fracción del gasto.",beat:"Marcus firma la factura. Viniendo de Marcus, son fuegos artificiales."}},
         {t:"Pedirle un descuento al proveedor",out:{r:"bad",concept:"Enrutamiento y costos",why:"Un descuento sobre la arquitectura equivocada sigue siendo la arquitectura equivocada, ahora con contrato más largo.",beat:"El proveedor manda una canasta de frutas. Marcus la devuelve."}}]}}},
 {npc:"priya",title:"El bot del 98%",late:"El bot de cotizaciones sigue en 98%. Finanzas sigue con la carpeta. Nada de esto se arregló solo mientras no lo veíamos.",start:"a",nodes:{
  a:{say:"El bot de cotizaciones acierta el 98% y envía todo solo. Aquí está el otro 2% — clientes reales, precios que pierden dinero real. A ventas le encanta. Finanzas encontró el 2%.",
     codex:"El nivel de automatización debe seguir el costo del error: automático donde equivocarse es barato, revisión humana donde es caro. Los puntajes de confianza separan cuál es cuál — solo lo dudoso espera a una persona.",
     q:"¿Lo lanzas, lo controlas o lo matas?",
     ch:[{t:"Lanzarlo — 98% es un diez",out:{r:"bad",concept:"Humano en el circuito",why:"98% es un diez en un examen. En precios auto-enviados son 200 cotizaciones malas al mes, en dinero real.",beat:"Finanzas abre una hoja de cálculo titulada «El 2%». Lleva tu nombre."}},
         {t:"Enviar las cotizaciones dudosas a revisión humana",next:"b"},
         {t:"Matarlo hasta que sea perfecto",out:{r:"bad",concept:"Humano en el circuito",why:"Perfecto nunca llega, y acabas de tirar el 98% que ahorraba horas todos los días.",beat:"Ventas hace una pequeña vigilia."}}]},
  b:{say:"De acuerdo — cola de revisión. Ahora la pregunta del árbol: ¿QUÉ cotizaciones esperan a un humano?",
     codex:"Revisarlo todo recrea el trabajo manual que automatizaste. No revisar nada es donde empezaste. La palanca es el umbral de confianza — más el costo del tipo de error: un precio demasiado bajo duele más que una cotización lenta.",
     q:"¿Qué va a la cola de revisión?",
     ch:[{t:"Todas — humanos revisan todo de nuevo",out:{r:"mid",concept:"Umbrales de confianza",why:"Seguro pero contraproducente: reconstruiste el trabajo de 40 horas con pasos extra. Medio crédito — sin pérdidas, sin palanca.",beat:"El revisor ahora revisa cotizaciones sobre revisar."}},
         {t:"Solo las de baja confianza y cualquiera sobre un tope de precio",out:{r:"ok",concept:"Umbrales de confianza",why:"La confianza captura la duda del modelo; el tope de precio captura los errores caros de los que está confiadamente equivocado. Dos redes, mínima fricción.",beat:"Ventas conserva su velocidad, finanzas su sueño, y Priya casi sonríe."}},
         {t:"Una muestra aleatoria del 10%",out:{r:"mid",concept:"Umbrales de confianza",why:"Muestrear mide la tasa de error — no detiene errores. Bien para monitorear, mal como única barrera. Medio crédito.",beat:"El 2% te saluda desde el 90% sin muestrear."}}]}}},
 {npc:"cto",title:"Las notas de Bayview",late:"Bayview volvió a llamar. Mientras tanto las notas se apilaron — lo único en que el papeleo es confiable.",start:"a",nodes:{
  a:{say:"Nuestros médicos se ahogan en papeleo. Quiero resúmenes con IA de las notas de visita — pero cada nota está llena de datos de pacientes, y necesito no salir en las noticias.",
     codex:"Los datos de salud están regulados. Dos llaves hacen posible trabajar con LLM: enmascarar identificadores antes de que el modelo vea el texto, y usar un endpoint empresarial cubierto por un acuerdo firmado (BAA) que permite datos de salud. Los endpoints de consumo nunca están cubiertos.",
     q:"¿Cómo entregas los resúmenes?",
     ch:[{t:"Mandar las notas crudas a una IA de consumo",out:{r:"bad",concept:"Gobernanza de datos",why:"Esa es la opción que termina carreras — una brecha reportable con marca de tiempo.",beat:"En algún lugar, un oficial de cumplimiento despierta sudando frío, sin saber por qué."}},
         {t:"Enmascarar identificadores + endpoint cubierto por BAA + registrar todo",out:{r:"ok",concept:"Gobernanza de datos",why:"El modelo ve solo lo necesario, en infraestructura autorizada a verlo, con rastro de auditoría. El camino estándar y defendible.",beat:"Dr. Okafor: «Por fin. Alguien que ya hizo esto en salud»."}},
         {t:"Negarse: la IA no puede tocar datos de salud",out:{r:"mid",concept:"Gobernanza de datos",why:"Cero riesgo, cero ayuda — y alguien menos cuidadoso dirá que sí. Medio crédito por cautela sin oficio.",beat:"Los médicos siguen ahogándose, pero en regla."}}]}}},
 {npc:"junior",title:"El prompt de Theo",late:"El prompt sigue en una rama con mi nombre. Ya dejé de darle fechas a mi mamá.",start:"a",nodes:{
  a:{say:"¡Cambié el prompt del bot de soporte y el demo mejoró MUCHÍSIMO! ¿Podemos lanzar hoy? ¿Porfa? Ya le dije a mi mamá.",
     codex:"Un buen demo es una anécdota. Los cambios de prompt arreglan un caso y rompen cinco en silencio. Los equipos mantienen un set de evaluación — casos reales con respuestas correctas conocidas — y puntúan cada cambio antes de lanzar. Tests unitarios, pero para IA.",
     q:"¿El prompt de Theo se lanza hoy?",
     ch:[{t:"Lanzarlo — ambos lo vieron mejorar",out:{r:"bad",concept:"Evaluaciones y regresión",why:"El demo mostró un caso. La evaluación habría mostrado los dos flujos de reembolso que rompió. Ahora los encontrarán los clientes.",beat:"La mamá de Theo está orgullosa. La cola de reembolsos no."}},
         {t:"Correr el set de evaluación; lanzar mañana si el puntaje aguanta",out:{r:"ok",concept:"Evaluaciones y regresión",why:"Una hora de evaluación atrapa lo que los demos esconden — encuentra dos casos de reembolso rotos. Theo lanza mañana, correctamente, y aprende el ritual.",beat:"Theo le compra café a Priya por una semana. Arco de crecimiento iniciado."}},
         {t:"Preguntarle a otra IA cuál prompt es mejor",out:{r:"mid",concept:"Evaluaciones y regresión",why:"IA-como-juez es una técnica real — dentro de un arnés de evaluación con criterios definidos. Como oráculo de intuiciones, es una moneda con opiniones. Medio crédito.",beat:"El modelo juez dice que ambos prompts están «¡geniales!». Lo dice de todo."}}]}}},
 {npc:"tovar",title:"El plan enmicado",late:"El plan de Theo sigue enmicado. Es la única parte que envejeció bien.",start:"a",nodes:{
  a:{say:"Una cosa más — los gerentes quieren transcripción de reuniones en la app. Theo tiene un plan de seis meses para construir voz-a-texto desde cero. Lo enmicó.",
     codex:"Algunas capacidades de IA son commodities — transcripción, traducción, OCR — vendidas como APIs excelentes por centavos. La diferenciación vive en lo que tu producto hace con el resultado, no en reconstruir el commodity.",
     q:"¿Seis meses para construirlo, o…?",
     ch:[{t:"Construir voz-a-texto desde cero",out:{r:"bad",concept:"Construir vs comprar",why:"Seis meses reconstruyendo lo que cuesta centavos por minuto, para alcanzar una calidad que la API ya supera. Nadie lo notará — excepto Marcus.",beat:"Lo enmicado era lo mejor del plan."}},
         {t:"Integrar una API probada de transcripción; construir las funciones encima",out:{r:"ok",concept:"Construir vs comprar",why:"Dos semanas para integrar, y el equipo construye lo que los gerentes pidieron — lo que va sobre la transcripción. Construye la última milla, compra el commodity.",beat:"Theo des-enmica el plan. En silencio."}},
         {t:"Contratar transcriptores humanos",out:{r:"bad",concept:"Construir vs comprar",why:"Más lento, más caro, y no escala pasada la tercera reunión. Estamos en 2026.",beat:"La vacante recibe tres postulaciones. Todas de bots."}}]}}},
 {npc:"ceo",title:"El silencio de 8 segundos",late:"Me quedé con la grabación. Todavía cuento los segundos cuando la pongo. Siguen siendo ocho.",start:"a",nodes:{
  a:{say:"Demo final. Tu agente telefónico da respuestas brillantes… ocho segundos después de que el cliente deja de hablar. Los conté. Dos veces. La gente cuelga.",
     codex:"En IA en tiempo real, la gente juzga el tiempo hasta la primera palabra, no el tiempo de la respuesta completa. Dos palancas: transmitir la respuesta en streaming para que empiece a hablar mientras se genera, y abrir con un modelo pequeño y rápido mientras lo pesado alcanza por detrás.",
     q:"Mata el silencio de ocho segundos:",
     ch:[{t:"Esperar hardware más rápido",out:{r:"bad",concept:"Ingeniería de latencia",why:"La latencia es un problema de diseño que arreglas este sprint, no un problema de hardware que otro arregla el año que viene.",beat:"El CEO mira su reloj por tercera vez. Hace eco."}},
         {t:"Streaming en la respuesta; abrir con un modelo pequeño y rápido",next:"b"},
         {t:"Poner música de espera",out:{r:"bad",concept:"Ingeniería de latencia",why:"Ahora son ocho segundos de jazz antes de la decepción.",beat:"Camila veta la licencia de smooth jazz."}}]},
  b:{say:"Priya, parchando en vivo: «El streaming quedó. Última llamada — ¿qué métrica va en el tablero de lanzamiento?»",
     codex:"Obtienes lo que mides. El tiempo total esconde el arreglo; el tiempo hasta la primera palabra es lo que la gente siente — con el tiempo total y la calidad al lado, no en su lugar.",
     q:"La métrica principal de latencia es…",
     ch:[{t:"Tiempo total promedio de respuesta",out:{r:"mid",concept:"Métricas de latencia",why:"Real, pero titular equivocado — una respuesta lenta en streaming SE SIENTE instantánea, y esta métrica no lo ve. Medio crédito; déjala como secundaria.",beat:"El tablero dice «más lento». Los clientes dicen «por fin»."}},
         {t:"Tiempo hasta la primera palabra",out:{r:"ok",concept:"Métricas de latencia",why:"Es el momento en que el silencio termina — lo que la gente juzga. Mide el tiempo total y la calidad al lado; titula con esta.",beat:"Menos de un segundo. El CEO guarda el reloj. Priya sonríe. Hay testigos."}},
         {t:"Número de personas que cuelgan",out:{r:"mid",concept:"Métricas de latencia",why:"Gran métrica de resultado — pero es una alarma tardía, no un volante. Medio crédito.",beat:"«Buenas noticias: caen los cuelgues. Malas: lo supimos una semana tarde»."}}]}}},
 {npc:"rosa",title:"El teléfono no para",late:"El teléfono nunca se cansó, mijo. Yo tantito sí.",start:"a",nodes:{
  a:{say:"Mijo, el teléfono suena todo el día — pedidos, preguntas, «¿tienen birria?». Pierdo la mitad de las llamadas mientras cocino. Dicen que un robot puede contestar. Bueno. ¿Pero puede tomar pedidos SIN arruinarlos?",
     codex:"Un agente de voz puede tomar pedidos por teléfono — el truco es la estructura. Lo hablado se convierte en un pedido estructurado (platillos, tamaños, extras, precio) contra el menú real, y se lo lee de vuelta al cliente para confirmar antes de que cuente. Adivinar con texto libre es como terminas con tres birrias sorpresa.",
     q:"¿Cómo debe tomar pedidos el agente telefónico?",
     ch:[{t:"Que converse libremente y anote lo que escuche",out:{r:"bad",concept:"Salidas estructuradas",why:"Texto libre significa que «horchata grande» se vuelve «¿la orchata grande?» se vuelve tickets misteriosos. Sin estructura no hay comanda confiable.",beat:"El ticket #4 dice «birria??? ¿3 quizás?». La cocina llora."}},
         {t:"Emparejar cada pedido con el menú real como items estructurados, y leerlo de vuelta para confirmar",next:"b"},
         {t:"Seguir perdiendo llamadas — es más auténtico",out:{r:"bad",concept:"Salidas estructuradas",why:"Llamadas perdidas son ingresos perdidos — un tercio de los pedidos de Rosa llegan por teléfono.",beat:"Al otro lado de la ciudad, el robot de la competencia dice «gracias por su orden»."}},
         {t:"Contratar a alguien solo para contestar el teléfono",out:{r:"mid",concept:"Salidas estructuradas",why:"Un humano funciona — con sueldo, descansos, y renuncias en el peor momento. Opción real, costo pesado para un problema resoluble. Medio crédito.",beat:"La nueva contratación renuncia tras un solo sábado en friega."}}]},
  b:{say:"¡Funciona, mijo! Pero anoche alguien pidió «el paquete de banquete de bodas para 200 personas» — y el robot dijo que SÍ, feliz de la vida. Nosotros no hacemos bodas.",
     codex:"Los agentes necesitan límites explícitos: qué pueden vender, topes de tamaño de pedido, y la regla de pasarle a un humano cualquier solicitud inusual. La confirmación protege al cliente; los límites protegen a Rosa.",
     q:"Arregla el entusiasmo del robot:",
     ch:[{t:"Solo menú + tope de pedido + lo inusual va al teléfono de Rosa",out:{r:"ok",concept:"Límites del agente",why:"Vender solo lo que existe, hasta límites sensatos, y escalar lo raro a un humano. De las bodas decide Rosa — no el robot.",beat:"El robot transfiere cortésmente una consulta de quinceañera. Rosa negocia como campeona."}},
         {t:"Apagar el robot de noche",out:{r:"mid",concept:"Límites del agente",why:"Esquiva el error esquivando también los ingresos. Medio crédito — seguro, pero pequeño.",beat:"Los noctámbulos piden pizza. Traidores."}},
         {t:"Que improvise — el cliente siempre tiene la razón",out:{r:"bad",concept:"Límites del agente",why:"Un agente sin límites prometerá 200 birrias y un mariachi. El costo del error no tiene techo.",beat:"En algún lugar, Marcus siente una perturbación que no puede explicar."}},
         {t:"Que el robot ofrezca extras en todo para subir ventas",out:{r:"bad",concept:"Límites del agente",why:"Un agente optimizando ingresos sin límites quema la confianza — lo que puede OFRECER también es decisión de límites.",beat:"Una abuelita que pide un café recibe oferta del paquete de fiesta. Dos veces."}}]}}},
 {npc:"chuy",title:"La prep del viernes",late:"Pasaron muchos viernes desde que te pregunté. En todos le calculé al tanteo.",start:"a",nodes:{
  a:{say:"Cada viernes adivino cuánta barbacoa preparar. Si le atino bajo — se acaba a las 8 y la gente llora. Si le atino alto — el Chuy del domingo come sobras tristes tres días. Tiene que haber una mejor manera, ¿no?",
     codex:"Pronosticar le gana al instinto: promedia los últimos viernes, ajusta por lo distinto de esta semana (quincena, clima, eventos), y registra qué tan equivocado estuviste para mejorar cada semana. Sobreproducir es dinero a la basura; quedarse sin producto es clientes a la basura.",
     q:"¿Cuánta barbacoa para el viernes?",
     ch:[{t:"Lo de siempre — al tanteo",out:{r:"mid",concept:"Pronóstico de demanda",why:"El instinto trajo a Chuy hasta aquí — a veces acierta, nunca se mide, imposible de mejorar. Medio crédito por sobrevivir al puro oficio.",beat:"Viernes, 8:15pm: «no hay». Se escuchan corazones romperse."}},
         {t:"Promediar los últimos 8 viernes, ajustar por quincena y clima, y registrar el error semanal",out:{r:"ok",concept:"Pronóstico de demanda",why:"Un pronóstico simple más registro del error se vuelve más listo cada semana. Esto es ciencia de datos con mandil.",beat:"Chuy pega el pronóstico en el refri. Se vuelve ley."}},
         {t:"Doblar todo y vender sobras el sábado",out:{r:"bad",concept:"Pronóstico de demanda",why:"El desperdicio como estrategia — el margen muere calladito en el cuarto frío.",beat:"Una torre de barbacoa dominical. Hasta Frederick, de visita, dice que no."}},
         {t:"Comprar primero una gran plataforma de pronósticos con IA",out:{r:"mid",concept:"Pronóstico de demanda",why:"Herramientas antes que disciplina de datos es al revés — el promedio simple con registro de error gana hasta que los datos ameriten plataforma. Medio crédito.",beat:"La llamada de implementación dura más que el servicio del viernes."}}]}}},
 {npc:"lupe",title:"El presupuesto",late:"Treinta fotos, y la clienta sigue queriendo el número hoy. Don Güero sigue diciendo que él lo mide en dos horas. Ninguna de las dos ha cambiado.",start:"a",nodes:{
  a:{say:"¿Tú eres el de la IA? Lupe — yo hago los presupuestos y los permisos. El señor de la camisa amarilla, allá en la escalera, es Don Güero; él manda en esta obra y me manda a mí todo lo que no quiere escribir. Ahorita eso es una cotización para remodelar un local al otro lado de la ciudad: treinta fotos, y la clienta quiere el número HOY. Él manejaría hasta allá y mediría dos horas. Yo no tengo dos horas.",
     codex:"Los modelos de visión pueden leer medidas desde fotos: áreas de muros, instalaciones, daños, materiales. El patrón confiable: la IA redacta las partidas desde las fotos — cantidades, materiales, mano de obra — y un humano verifica precios y rincones raros antes de enviarla. Rápido Y defendible.",
     q:"¿Cómo se arma la cotización?",
     ch:[{t:"Calcular a ojo desde las fotos, con experiencia",out:{r:"mid",concept:"Presupuestos con visión",why:"La experiencia es real — pero adivinar sin medir gana trabajos que pierden dinero. Medio crédito por las canas.",beat:"El bigote de Don Güero tiembla. Sabe que tienes razón."}},
         {t:"La IA redacta partidas desde las fotos; Güero verifica materiales y precios antes de enviar",next:"b"},
         {t:"Prometer ganarle a cualquier otra cotización y ya verás después",out:{r:"bad",concept:"Presupuestos con visión",why:"Ganar por precio sin conocer tus costos es como mueren las constructoras con la agenda llena.",beat:"Lupe, sin levantar la vista: «Así cayó la empresa pasada»."}},
         {t:"Mandar a un aprendiz a medir todo a mano hoy",out:{r:"mid",concept:"Presupuestos con visión",why:"Preciso — y lento. La cotización llega tarde, y las tardías pierden. Medio crédito por rigor sin velocidad.",beat:"El aprendiz mide precioso. La clienta firmó con otros al mediodía."}}]},
  b:{say:"¡Ganamos el trabajo, jefe! Pero ahora la clienta dice: «ya que están ahí, agréguenme un bañito». UN BAÑITO. ¿Qué le digo?",
     codex:"Los cambios de alcance son donde se desangran las obras. La disciplina es la orden de cambio: cada extra se escribe con su precio e impacto en el calendario, y se aprueba ANTES de trabajar. La IA la redacta en minutos desde el presupuesto original — sin pena, puro papel.",
     q:"El «bañito» se maneja con…",
     ch:[{t:"Hacerlo y ya — cliente contenta",out:{r:"bad",concept:"Órdenes de cambio",why:"Baños gratis hoy, quiebra mañana. El alcance no cobrado es el asesino silencioso de las buenas cuadrillas.",beat:"La cuadrilla lo construye precioso. Nadie lo paga."}},
         {t:"Orden de cambio escrita — precio e impacto en tiempo, redactada por IA, aprobada antes de trabajar",out:{r:"ok",concept:"Órdenes de cambio",why:"La IA convierte el presupuesto en orden de cambio en minutos; la clienta firma sabiendo exactamente qué cuesta. Todos quedan amigos Y solventes.",beat:"La clienta firma. Don Güero enmarca la orden de cambio como diploma."}},
         {t:"Negarse a todo cambio — el contrato es el contrato",out:{r:"mid",concept:"Órdenes de cambio",why:"Protege el margen, pierde la relación — y las remodelaciones SIEMPRE cambian. Medio crédito por carácter, cero por flexibilidad.",beat:"La clienta llama a otros para el siguiente trabajo. Y el siguiente."}},
         {t:"Hacerlo y colarlo calladito en la factura final",out:{r:"bad",concept:"Órdenes de cambio",why:"Los cobros sorpresa son como se pierde la confianza — y a veces se ganan citas en el juzgado. Primero papel, luego trabajo.",beat:"La factura final desata una discusión a gritos en dos idiomas."}}]}}},
 {npc:"lupe",title:"El purgatorio de permisos",late:"Los permisos esperaron. Para eso son buenos. Los que se dieron cuenta fueron mis domingos.",start:"a",nodes:{
  a:{say:"Tres proyectos están muertos porque los permisos no se han metido. Los mismos formularios, la misma ciudad, cada vez — datos del dueño, alcance, lista de planos, cuotas. Me gasto los domingos copiando los mismos datos en las mismas casillas. En algún lugar de esto debe haber dignidad.",
     codex:"El papeleo repetitivo es la cancha del automatizado de documentos: los datos del proyecto ya existen, así que la IA puede llenar los formularios estándar y seguir el estado de cada permiso. El humano revisa antes de presentar — un permiso mal hecho es peor que uno lento.",
     q:"¿Cómo se resuelven los permisos?",
     ch:[{t:"Buscar a un conocido que conoce a alguien en el municipio",out:{r:"bad",concept:"Automatización de documentos",why:"El conocido se jubila, el atajo se vuelve escándalo, y los proyectos siguen muertos. Eso no es un sistema.",beat:"El primo del conocido cotiza una «cuota de consultoría». Lupe cuelga."}},
         {t:"La IA llena los formularios desde los datos del proyecto, Lupe revisa antes de presentar, y un tablero sigue cada permiso",out:{r:"ok",concept:"Automatización de documentos",why:"Los datos existen una vez, los formularios se llenan solos, el humano firma, y nada vuelve a perderse en el purgatorio. Los domingos regresan a Lupe.",beat:"Tres permisos presentados antes del almuerzo. Lupe toma un fin de semana de verdad. El municipio está confundido."}},
         {t:"Seguir a mano — es la tradición",out:{r:"mid",concept:"Automatización de documentos",why:"Funciona, lento, y se come a la presupuestista que debería estar presupuestando. Medio crédito por confiable, al costo de los domingos.",beat:"El café de Lupe se enfría sobre el formulario B-247. Otra vez."}},
         {t:"Tercerizar todos los permisos a una consultora",out:{r:"mid",concept:"Automatización de documentos",why:"Funciona — con honorarios, para siempre, y la capacidad nunca llega a casa. Medio crédito: delegado, no resuelto.",beat:"La consultora usa la misma herramienta de IA. Lupe observa, facturada."}}]}}},
 {npc:"priya",title:"Dilo para que sea verdad",late:"El bot ha dicho muchas cosas con mucha seguridad desde que levanté esto. A marketing le sigue encantando el tono.",start:"a",nodes:{
  a:{say:"Las respuestas del bot de soporte SUENAN geniales — seguras, pulidas, equivocadas una de cada diez veces. Nadie sabe cuál. A marketing le encanta el tono. Yo odio el tono. Arregla la redacción.",
     codex:"La confianza se construye con lenguaje calibrado: instrucciones que hacen que el bot cite su fuente, marque lo incierto como incierto, y diga «no lo sé» cuando nada respalda la respuesta. «Sé preciso» es una vibra — citar, matizar y rehusar son conductas.",
     q:"¿Qué va en las instrucciones del bot?",
     ch:[{t:"Escribir «sé preciso y útil» al inicio",out:{r:"mid",concept:"Lenguaje calibrado",why:"Una vibra, no una conducta. Los modelos siguen verbos concretos; «sé preciso» no mide nada. Medio crédito — inofensivo, inútil.",beat:"El bot sigue equivocándose con confianza, pero ahora con cortesía."}},
         {t:"Citar la fuente de cada afirmación, marcar lo incierto como incierto, y decir «no lo sé» cuando nada lo respalda",next:"b"},
         {t:"Que suene MÁS seguro — a los clientes les gusta la certeza",out:{r:"bad",concept:"Lenguaje calibrado",why:"Redacción segura sobre respuestas equivocadas es como muere la confianza a escala. Eso es pulir el fracaso.",beat:"Marketing aplaude. Camila abre una hoja de cálculo nueva."}},
         {t:"Agregar un descargo legal a cada respuesta",out:{r:"mid",concept:"Lenguaje calibrado",why:"Cubrirse no es sincerarse — al tercer mensaje, los usuarios ya aprendieron a saltárselo. Medio crédito por instinto de abogado.",beat:"Los usuarios pasan el descargo a velocidad récord. Todos."}}]},
  b:{say:"Mejor. Ahora la de verdad: alguien llama y pregunta «¿cuántas sucursales aceptan la app?» — la búsqueda no encuentra nada actual. El bot tiene que decir ALGO. Redáctalo.",
     codex:"Cuando no puedes verificar, la forma confiable es: afirmar lo que SÍ puedes confirmar, nombrar lo que no, y entregar el camino a la respuesta. La precisión sobre tus propios límites es a lo que suena la exactitud.",
     q:"La mejor respuesta del bot es…",
     ch:[{t:"«¡Unas 300 sucursales!» — seguro le atina",out:{r:"bad",concept:"Afirmaciones verificables",why:"Una suposición con confianza es una mentira con buena postura. Un número equivocado desteje todos los correctos anteriores.",beat:"Eran 41. En la línea había una periodista."}},
         {t:"«No puedo verificar el número actual. Al último corte eran 38 — aquí está la lista en vivo.»",out:{r:"ok",concept:"Afirmaciones verificables",why:"Confirma lo conocido, nombra lo desconocido, entrega el camino. Esa redacción ES el producto de confianza.",beat:"Priya lo lee dos veces. «Publica esa redacción.» El mayor elogio que conoce."}},
         {t:"«No puedo responder esa pregunta.»",out:{r:"mid",concept:"Afirmaciones verificables",why:"Honesto pero flojo — rehusar todo lo no verificable tira la verdad parcial que SÍ tienes. Medio crédito.",beat:"La persona le pregunta a un humano, que le lee el mismo último corte."}},
         {t:"Responder normal y esconder «las cifras pueden variar» al final",out:{r:"mid",concept:"Afirmaciones verificables",why:"Incertidumbre en la letra chica es certeza en el titular. La ubicación también es redacción. Medio crédito.",beat:"Nadie lee la nota tres al pie. Nunca."}}]}}},
 {npc:"xochi",title:"El drop de collares",late:"El brief sigue clavado arriba de mi mesa. Le sigo agregando nombres.",start:"a",nodes:{
  a:{say:"¡Ah, la persona de IA! Mira — La Obra construye el barrio, yo lo visto. Quiero una línea de collares para las mascotas del rumbo: Frederick, Canela, todo el elenco. Sé dibujar, pero estas herramientas de imágenes con IA… ¿cómo DISEÑAMOS con ellas sin perder el oficio?",
     codex:"Los modelos de imágenes son motores de variaciones, no diseñadores. El patrón que funciona: la diseñadora define el brief, la IA genera decenas de direcciones, el humano cura y refina las ganadoras — y la elegida solo se vuelve real cuando es una especificación estructurada (un tech pack): materiales, medidas, colores. El gusto sigue siendo humano; la máquina pone el volumen.",
     q:"¿Cómo se diseña la línea de collares?",
     ch:[{t:"Un prompt, la primera imagen, directo a producción",out:{r:"bad",concept:"Diseño asistido por IA",why:"Sin curaduría, sin especificación, sin tallas — una primera salida es un mood, no un producto. Producción necesita medidas, no vibras.",beat:"La muestra llega en talla caballo. Frederick se niega a comentar."}},
         {t:"La IA genera variaciones sobre el brief de Xochi; ella cura, y la elegida se vuelve tech pack — materiales, tallas, colores",next:"b"},
         {t:"Copiar el collar de esa diseñadora famosa y que la IA lo restilice un poco",out:{r:"bad",concept:"PI y originalidad",why:"Una copia restilizada sigue siendo una copia — radiactiva en lo legal y hueca en lo creativo. La IA hace la imitación más rápida, no legal, y el barrio merece su propio estilo.",beat:"Dana aparece en la puerta del Estudio con un cese y desista. Solo para que sepas cómo se ve uno."}},
         {t:"Dibujar todo a mano como siempre, sin IA",out:{r:"mid",concept:"Diseño asistido por IA",why:"El oficio es real y el gusto es el punto — pero una diseñadora explorando cinco direcciones a mano pierde contra la misma curando cincuenta. Medio crédito por los estándares.",beat:"Semana dos: tres bocetos hermosos, noventa ideas sin explorar."}}]},
  b:{say:"El tech pack quedó precioso. Ahora el lanzamiento — son atuendos virtuales para las mascotas del pueblo. ¿Cómo sacamos la línea?",
     codex:"La curaduría es control de calidad para bienes creativos. Drops pequeños con revisión humana — ¿cada pieza le queda a cada cuerpo para el que se vende? — mantienen un catálogo que vale la pena. Auto-generar publicaciones infinitas inunda el estante de basura, y «todo gratis para siempre» solo significa que el trabajo no puede continuar.",
     q:"La estrategia del drop es…",
     ch:[{t:"Drops pequeños y curados; cada pieza probada en cada cuerpo antes de publicarse",out:{r:"ok",concept:"Curaduría como QA",why:"Cada drop es lo bastante pequeño para revisarse y lo bastante especial para desearse. La mentalidad de evals, aplicada a la moda: se prueba en cada tipo de cuerpo antes de salir.",beat:"El primer drop se agota antes del atardecer. Frederick modela el collar dorado con una dignidad insoportable."}},
         {t:"Auto-generar y auto-publicar artículos nuevos a diario",out:{r:"bad",concept:"Curaduría como QA",why:"Un catálogo infinito sin curar es un basurero con buscador. Nadie navega la basura dos veces.",beat:"El artículo #4,072 es un collar con tres hebillas y ningún agujero. Ya lo compró una paloma confundida."}},
         {t:"Todo gratis, para siempre, para todos",out:{r:"mid",concept:"Curaduría como QA",why:"Generoso — e insostenible. Lo gratis es táctica de lanzamiento, no un plan; la línea muere cuando el trabajo no se paga solo. Medio crédito por el corazón.",beat:"Mes dos: Xochi acepta un mural en silencio para financiar el collar tres."}}]}}},
 /* ---------- El Mercado Robles · el pack de product manager de IA (Semana Dos, capítulo uno) ----------
    Doña Chelo lo quiere todo al mismo tiempo. El trabajo es decidir qué se construye de verdad. */
 {npc:"chelo",title:"Todo al mismo tiempo",late:"La lista sigue en el mostrador, mijo. Le sigo agregando — es la única parte de esta lista que sí funciona.",start:"a",nodes:{
  a:{say:"Mijo, siéntate. Hice una lista. Una app para pedidos. Un robot para el teléfono. Algo que sepa cuándo se pican los tomates. Una cosa para Instagram. Una máquina que me diga qué comprar el lunes. Mi sobrino dice que necesito página web. Ah, y la impresora no sirve.",
     doc:"lista-chelo",
     codex:"Once deseos no son un plan. Lo primero que se construye es donde el dolor es frecuente, medible y de alguien que de verdad va a usar la solución — no lo que suena más impresionante al contarlo. Todo lo demás se queda en la lista y espera su turno.",
     q:"¿Por dónde empiezas?",
     ch:[{t:"Construir la app de pedidos — es la idea más grande de la lista",out:{r:"bad",concept:"Alcance",why:"Lo más grande no es lo primero. La app de pedidos toca proveedores, inventario, pagos y a todos los clientes a la vez — seis meses antes de que alguien pueda decir si sirvió.",beat:"Doña Chelo asiente con cortesía. Nando deja de hacer contacto visual."}},
         {t:"Preguntar cuál de todas le cuesta más horas en una semana normal, y construir esa",next:"b"},
         {t:"Hacerlas todas, pero chiquitas — un poquito de cada una",out:{r:"bad",concept:"Alcance",why:"Once medias cosas son once cosas que mantener y ninguna en la que se pueda confiar. Medio bot de teléfono sigue contestando mal el teléfono.",beat:"Para el jueves hay once pestañas abiertas y nadie sabe cuál es la buena."}},
         {t:"Arreglar la impresora",out:{r:"mid",concept:"Alcance",why:"¿Honestamente? Destrabar a la persona que hace el trabajo gana contra un piloto que nadie pidió. Pero la impresora no es el problema por el que te contrató. Medio crédito por leer el ambiente.",beat:"La impresora sirve. Doña Chelo está genuinamente feliz. La lista sigue midiendo once."}}]},
  b:{say:"El teléfono. Es el teléfono. Cuarenta llamadas al día — ¿tienen masa?, ¿a qué hora cierran?, ¿tienen el queso de rancho? — y cada una le quita a Perla de la caja.",
     codex:"Antes de construir, define qué significa que funcione en un número que alguien ya lleva. No “el bot es inteligente” sino “Perla se levanta de la caja menos de cinco veces al día”. Una métrica de éxito escrita después del lanzamiento es un cuento, no una medición.",
     q:"Empiezas a construir. ¿Qué defines primero?",
     ch:[{t:"Cuántas de las cuarenta tiene que resolver para que Chelo lo considere digno de quedarse",out:{r:"ok",concept:"Definición de terminado",why:"Ese número es el proyecto entero. Te dice qué construir, cuándo parar y — la parte que todos se saltan — cuándo admitir que no funcionó.",beat:"Chelo lo piensa. “Si agarra treinta y no miente, me lo quedo.” Escribe eso en la pared."}},
         {t:"Cuál modelo usar",out:{r:"bad",concept:"Definición de terminado",why:"El modelo es la decisión más barata de todas y la más fácil de cambiar después. Escogerlo primero es elegir el martillo antes de ver la pared.",beat:"Nando, con recelo: “…¿es esa cosa que mi primo trae en el celular?”"}},
         {t:"El nombre y el logo",out:{r:"mid",concept:"Definición de terminado",why:"Va a importar para las abuelas que tienen que confiar en él — pero bautizar algo antes de definirlo es cómo terminas con una nada bellamente marcada. Medio crédito.",beat:"Perla ya dibujó un logo. Y hay que decirlo: está excelente."}}]}}},
 {npc:"chelo",title:"La prueba de la abuela",late:"Doña Meche ha llamado cada martes desde entonces. Ni una sola vez ha pensado en una app.",start:"a",nodes:{
  a:{say:"Perla dice que lo del teléfono debería ser una app. Mijo — mis clientas son señoras que contestan el celular como si fuera teléfono de casa. Doña Meche me habla para preguntar si tengo masa. Me habla cada martes desde hace nueve años.",
     codex:"El usuario que tienes no es el usuario del pitch. Una herramienta que exige descarga, cuenta y datos la usan los que ya tenían las tres. Encuentra a la gente en el canal que ya usa, o acepta que construiste para otro barrio.",
     q:"¿Cómo se contestan las preguntas de Doña Meche?",
     ch:[{t:"Una app — es la experiencia más limpia",out:{r:"bad",concept:"Encontrar al usuario donde está",why:"¿Limpia para quién? Una app es una descarga, un login y un tutorial parados entre Meche y la palabra sí. Va a seguir llamando, y ahora además tienes una app que mantener.",beat:"Nueve instalaciones. Seis son Perla probándola. Una es Chava, sin querer."}},
         {t:"El mismo número al que ya llama — el bot contesta y pasa a una persona cuando no puede",out:{r:"ok",concept:"Encontrar al usuario donde está",why:"Cero comportamiento nuevo para una clienta de nueve años. El canal es el mismo; solo cambia lo que pasa después del segundo timbre. Y el pase a humano hace que un error cueste una transferencia, no una clienta.",beat:"Meche nunca se entera de que algo cambió. Ese es exactamente el punto."}},
         {t:"Enseñarle a las clientas a usar WhatsApp",out:{r:"mid",concept:"Encontrar al usuario donde está",why:"Algunas sí — medio barrio ya está ahí. Pero “primero cambia a tus clientes” es un plan con un primer paso larguísimo. Medio crédito.",beat:"Doña Chelo, seca: “Tú le enseñas. Yo miro.”"}},
         {t:"Poner un letrero en la puerta con los horarios",out:{r:"mid",concept:"Encontrar al usuario donde está",why:"Barato, real, y mata las llamadas de quien está parado en la puerta. Meche no está parada en la puerta. Medio crédito por intentar primero lo más barato.",beat:"Ponen el letrero. Suena el teléfono. Es Meche."}}]}}},
 {npc:"nando",title:"El atajo de Nando",late:"El camión sigue llegando. Yo sigo fotografiando cada caja. Cuarenta minutos, cada vez, todo este tiempo.",start:"a",nodes:{
  a:{say:"Antes de que cambies nada — yo ya hago esto. Llega el camión, le tomo foto a cada caja, las fotos van a una carpeta por fecha, las cuentas van a una hoja de cálculo en mi teléfono. Cuarenta minutos. Nunca se ha equivocado.",
     codex:"El atajo ES el documento de requerimientos. Alguien ya resolvió el problema mal-pero-bien, y cada rareza de su proceso codifica una restricción real. Reemplázalo sin leerlo y el despliegue muere de lo de siempre: la herramienta se lanza, la persona conserva su hoja de cálculo, y ahora hay dos sistemas.",
     q:"¿Qué haces con la hoja de Nando?",
     ch:[{t:"Reemplazarla — el sistema nuevo hace todo eso automáticamente",out:{r:"bad",concept:"Respetar el atajo",why:"Acabas de borrar el único registro de inventario correcto del edificio, junto con cuarenta minutos de criterio que Nando aplica sin darse cuenta. Va a conservar la hoja en secreto. Siempre lo hacen.",beat:"Tres semanas después: dos inventarios que no coinciden. Adivina cuál le cree Chelo."}},
         {t:"Acompañarlo en una entrega completa y ver a dónde se van de verdad los cuarenta minutos",next:"b"},
         {t:"Dejarla en paz — funciona",out:{r:"mid",concept:"Respetar el atajo",why:"¡No está mal! De verdad funciona. Pero cuarenta minutos diarios de una persona fotografiando cajas es justo la forma de lo que vale la pena mejorar — solo hay que mejorarlo con él, no contra él. Medio crédito por no romper lo que sirve.",beat:"Nando, desconfiado: “¿Ya? ¿No me vas a hacer usar una app?”"}}]},
  b:{say:"Treinta de los cuarenta son las facturas de los proveedores. La mitad a mano. Uno escribe en español, otro en inglés con los nombres mal, y el del pescado nada más pone PESCADO y un número.",
     codex:"Apunta al paso más lento en el que la máquina es genuinamente mejor — leer documentos desordenados — y déjale a la persona el paso que necesita criterio: decidir si la entrega realmente está bien. Automatiza el tecleo, no la confianza.",
     q:"Entonces lo que se construye es…",
     ch:[{t:"Leer las facturas automáticamente; Nando confirma las cuentas en pantalla en una sola pasada",out:{r:"ok",concept:"Automatizar el paso, no el puesto",why:"Treinta minutos se vuelven cinco, Nando sigue viendo cada entrega, y la revisión que atrapa un faltante se queda donde siempre estuvo — en su cabeza.",beat:"Nando lo lee dos veces. “¿Y yo sigo diciendo sí o no?” Sí. “Órale. Órale, así está bien.”"}},
         {t:"Automatización completa — entra la factura, se actualiza el inventario, sin paso humano",out:{r:"bad",concept:"Automatizar el paso, no el puesto",why:"El del pescado escribe PESCADO y un número. No existe una versión de esto donde nadie revise. Quita la revisión y la primera entrega mala se vuelve un número equivocado permanente.",beat:"El sistema recibe con toda confianza 400 kilos de PESCADO. Eran 40."}},
         {t:"Exigir a los proveedores facturas digitales bien hechas",out:{r:"mid",concept:"Automatizar el paso, no el puesto",why:"La solución correcta a largo plazo, y completamente fuera de tu control. No puedes lanzar un proyecto cuyo primer paso es “nueve negocios ajenos cambian su forma de trabajar”. Medio crédito — empieza a pedirlo, no lo esperes.",beat:"Nando se ríe seis segundos completos. “El del pescado. Facturas digitales. El del PESCADO.”"}}]}}},
 {npc:"perla",title:"La fila en la caja",late:"Okay, o sea — la gente me sigue preguntando las dos cosas. Empecé a llevar la cuenta. Son un montón de veces.",start:"a",nodes:{
  a:{say:"Okay, o sea — todo el mundo me pregunta si aceptamos tarjeta por menos de cinco dólares y es SÚPER molesto. ¿La IA puede hacer eso? Ah, y a veces preguntan qué lleva el mole y tengo que ir a buscar a Doña Chelo, pero eso pasa como dos veces por semana.",
     codex:"La petición más ruidosa casi nunca es la más grande. Alcance por frecuencia por costo-de-fallar le gana a quien preguntó más recientemente y con más sentimiento. Y la buena noticia: una pregunta constante con una sola respuesta fija normalmente no es un problema de IA.",
     q:"¿Cuál construyes?",
     ch:[{t:"La del mínimo de tarjeta — es la pregunta más común por mucho",out:{r:"mid",concept:"Priorizar por alcance",why:"Buen instinto, herramienta equivocada. Una pregunta con una sola respuesta que no cambia es un letrero, no un sistema. Hacerle un bot es gastar un mes en una tarjeta plastificada. Medio crédito por leer bien el volumen.",beat:"Perla se queda viendo el letrero que imprimes. “…¿ya? ¿Eso es todo?”"}},
         {t:"La del mole — es más rara, pero solo Chelo la contesta y no siempre está",out:{r:"ok",concept:"Priorizar por alcance",why:"Dos veces por semana, pero cada falla cuesta una caminata, una interrupción y a veces una venta que se va. Es la pregunta donde el conocimiento está atrapado en la cabeza de una sola persona — que es justo para lo que sirven estas herramientas.",beat:"Chelo, desde atrás, sin levantar la vista: “Por fin. Alguien pregunta los ingredientes noventa veces al año y yo soy la única receta.”"}},
         {t:"Las dos, al mismo tiempo",out:{r:"mid",concept:"Priorizar por alcance",why:"Se puede, y una toma una tarde — pero “las dos” es cómo un proyecto de dos semanas se vuelve de dos meses. Ponlas en orden: letrero hoy, mole este mes. Medio crédito.",beat:"Perla escribe LAS DOS en el pizarrón y lo subraya dos veces. Ambición registrada."}},
         {t:"Ninguna — las preguntas de caja no valen la pena automatizar",out:{r:"bad",concept:"Priorizar por alcance",why:"Ahí adentro hay una de verdad. Descartar la caja porque la petición más ruidosa era trivial es cómo se te escapa lo único que sabe una sola persona del edificio.",beat:"Perla deja de traerte problemas. Esto es peor de lo que suena."}}]}}},
 {npc:"nando",title:"El problema de las etiquetas",late:"Lleva todo este tiempo leyendo facturas. Otra vez leyó 12 como 112 — por si creías que ya se había aburrido.",start:"a",nodes:{
  a:{say:"Ya lee las facturas. Casi siempre muy bien. Pero el martes pasado leyó 12 como 112, y Chelo pidió contra un número que no existía.",
     codex:"“¿Qué tan preciso es?” es la pregunta equivocada. La correcta: ¿qué tan preciso necesita ser para que valga la pena usarlo, y qué pasa con los errores que quedan? Todo sistema tiene un presupuesto de error. O lo diseñas a propósito, o lo descubres en producción.",
     q:"¿Qué defines antes de tocar el modelo?",
     ch:[{t:"Una meta — qué precisión es suficiente, medida con facturas reales de esta tienda",next:"b"},
         {t:"Que sea lo más preciso posible, y ya",out:{r:"bad",concept:"Criterios de aceptación",why:"“Lo más preciso posible” no tiene meta, ni presupuesto, ni forma de distinguir una buena semana de una mala. Es un deseo con fecha de entrega.",beat:"Dos semanas de ajustes. Nadie puede decir si está mejor que el martes."}},
         {t:"Nada — obsérvalo un mes y ya veremos",out:{r:"mid",concept:"Criterios de aceptación",why:"Observar el uso real enseña cosas que ningún set de pruebas te dice — pero un mes de observar sin una vara contra qué medir solo te da un mes de anécdotas. Medio crédito.",beat:"Nando lleva la cuenta en una servilleta. Es, molestamente, el mejor dato que tienes."}}]},
  b:{say:"Digamos que lo dejamos en 97 de 100. Son tres facturas malas al mes, y cualquiera de ellas puede ser la del tomate.",
     doc:"eval-facturas",
     codex:"Diseña la falla, no solo el acierto. La pregunta nunca es si se va a equivocar — se va a equivocar — sino: cuando falle, ¿quién se da cuenta, qué tan rápido, y cuánto cuesta? Los buenos sistemas hacen visible su propia incertidumbre en vez de esconderla tras un número seguro de sí mismo.",
     q:"¿Cómo manejas las tres?",
     ch:[{t:"Marcar las lecturas de baja confianza para que Nando las revise; el resto pasa solo",out:{r:"ok",concept:"Diseñar para la falla",why:"La máquina hace las noventa y siete y levanta la mano en las demás. La atención de Nando va exactamente donde vale algo, y un número malo se atrapa el mismo día en vez de a fin de mes.",beat:"La servilleta de Nando ahora dice: ME PREGUNTÓ 4. HIZO BIEN EN PREGUNTAR 4."}},
         {t:"Aceptar las tres — 97% está muy bien",out:{r:"bad",concept:"Diseñar para la falla",why:"97% está muy bien como titular y muy mal como plan, porque las tres no son al azar. Son las facturas desordenadas — o sea, las del proveedor con más probabilidad de quedarte corto.",beat:"Las facturas del pescadero son, estadísticamente, las tres."}},
         {t:"Que Nando las revise todas de todos modos",out:{r:"mid",concept:"Diseñar para la falla",why:"Seguro — y acabas de reconstruir sus cuarenta minutos. Si una persona lee cada renglón, la máquina no ahorró más que tecleo. Medio crédito: la cautela está bien, el objetivo no.",beat:"Nando: “O sea que las leo todas. Como antes. Pero ahora hay pantalla.”"}}]}}},
 {npc:"perla",title:"Temporada de tamales",late:"Llegó diciembre. Se fue diciembre. Se nos acabó la hoja de maíz, y Chelo dijo nunca más, otra vez.",start:"a",nodes:{
  a:{say:"Ya viene diciembre. Cada año se nos acaba la hoja de maíz y cada año Chelo dice nunca más. Alguien le dijo que la IA puede predecir cuánta vamos a necesitar.",
     codex:"Un pronóstico es un modelo entrenado con historia. Si la historia vive en un cuaderno, en la memoria de tres personas y en una hoja que empezó en marzo, no hay con qué entrenar — y una predicción segura construida sobre cuatro datos es peor que una estimación honesta, porque la gente le cree.",
     q:"Doña Chelo quiere el pronóstico de diciembre. ¿Qué le dices?",
     ch:[{t:"Construirlo — es lo de mayor valor que ha pedido",out:{r:"bad",concept:"Secuenciar",why:"Estarías pronosticando con una hoja de hace seis meses y una temporada que nadie registró. El resultado se va a ver autoritario y va a ser ficción, y ella va a pedir mercancía contra él.",beat:"El modelo predice un diciembre tranquilo. Es, por supuesto, diciembre."}},
         {t:"Todavía no — empieza a anotar desde ahora lo que compra, y el pronóstico se vuelve real la próxima temporada",out:{r:"ok",concept:"Secuenciar",why:"“Todavía no, y esto es lo que lo hace posible” es la frase más útil que tiene un PM. Nombra la dependencia, le arranca el reloj, y se niega a vender un número que nadie puede sostener.",beat:"Chelo, seca: “O sea que este año le calculo, como siempre.” Sí. Pero este año anotas lo que calcula."}},
         {t:"Usar el diciembre pasado del cuaderno",out:{r:"mid",concept:"Secuenciar",why:"Un año de historia a mano es real y mejor que nada — como referencia, no como pronóstico. Di “el año pasado usamos esto” y deja de hablar. Medio crédito por usar lo que existe.",beat:"El cuaderno dice ¿6 cajas? 8? — con signo de interrogación. Chelo defiende el signo de interrogación."}},
         {t:"Comprar una herramienta de pronóstico",out:{r:"bad",concept:"Secuenciar",why:"Una herramienta sin datos tiene el mismo problema que un modelo sin datos, salvo que esta se renueva cada año.",beat:"Marcus, desde otro huso horario, presiente una suscripción y se remueve."}}]}}},
 {npc:"chava",title:"Todo es chile",late:"Sigue siendo chile, güey. El botón no se movió solito.",start:"a",nodes:{
  a:{say:"Sí, ya supe. Chelo dice que estoy rompiendo los datos. A ver — hay fila. El botón de chile está aquí mismo. El de carne está cuatro pantallas adentro. ¿Quieres que haga esperar a una abuela mientras lo busco?",
     codex:"Los datos malos casi siempre tienen detrás a una persona razonable. A alguien lo miden por velocidad, la acción correcta es lenta, y entonces toma la rápida equivocada — confiablemente, siempre. Ningún modelo, ningún script de limpieza y ningún tablero sobrevive a una fuente donde la respuesta equivocada es la fácil. Arregla las cuatro pantallas.",
     q:"Seis meses de ventas dicen que esta tienda vende casi puro chile. ¿Cuál es la jugada?",
     ch:[{t:"Limpiarlo después — una regla que reasigne los errores obvios",out:{r:"bad",concept:"Arreglar la fuente",why:"Estarías adivinando qué quiso decir Chava, para siempre, y las adivinanzas se vuelven el registro. Mientras tanto la caja sigue produciendo las mismas filas malas mañana, a la misma velocidad.",beat:"La regla funciona precioso hasta que alguien de verdad compra chile."}},
         {t:"Recapacitar a Chava — tiene que usar los botones correctos",out:{r:"mid",concept:"Arreglar la fuente",why:"Él sabe cuál es el botón correcto. Está tomando una decisión defendible bajo una restricción real: la fila. Capacitar contra un incentivo pierde contra el incentivo, siempre. Medio crédito — el estándar está bien, la palanca no.",beat:"Chava escucha, asiente, está completamente de acuerdo, y cobra el siguiente como chile."}},
         {t:"Poner en la primera pantalla las seis cosas que este mostrador de verdad vende",out:{r:"ok",concept:"Arreglar la fuente",why:"Haz que la acción correcta sea la más rápida y los datos se arreglan solos, permanentemente, sin reglas que mantener. Este es el trabajo entero: el modelo nunca fue el problema. La cuarta pantalla sí.",beat:"Chava cobra carne sin mirar el aparato. “Mmh.” Es el elogio más alto disponible."}},
         {t:"Poner a otra persona en el mostrador",out:{r:"mid",concept:"Arreglar la fuente",why:"Sí resuelve la fila — al precio de un sueldo, para no mover un botón. A veces la respuesta es más gente; aquí es una forma cara de esquivar el diseño de un menú. Medio crédito.",beat:"Marcus, a la distancia, siente aparecer una línea de nómina y no le agrada."}}]}}},
 {npc:"chelo",title:"El número del lunes",late:"A la caja no le importa en qué mes estamos, mijo, y a mí tampoco. Siéntate. La pregunta se guardó.",start:"a",nodes:{
  a:{say:"Ya pasó un mes desde que empezamos. Tu cosa del teléfono contesta, ¿qué, treinta de las cuarenta? De todo lo demás, la gente me dice que va bien. La gente siempre me dice eso, mijo. Así que dime derecho — ¿funcionó?",
     codex:"Las métricas del modelo contestan “¿se está portando bien?”. Las del negocio contestan “¿sirvió de algo?”. Se separan todo el tiempo: un bot puede contestar bien el 94% de las llamadas y no ahorrarle un minuto a nadie, si las que falla son justo las que necesitaban a una persona. Reporta el segundo número, y en las unidades de ella, no en las tuyas.",
     q:"¿Cómo le contestas?",
     ch:[{t:"94% de precisión, 0.8 segundos de respuesta, 31 de 40 llamadas atendidas",out:{r:"mid",concept:"Métrica de negocio vs métrica de modelo",why:"Todo cierto, todo real, y nada de eso contesta lo que ella preguntó. Ella tiene una tienda; la precisión no es algo que pueda guardar ni gastar. Medio crédito por haber medido algo.",beat:"Chelo mira los números un buen rato. “¿Y?”"}},
         {t:"Perla se levantaba de la caja cinco veces al día. Ahora una. Son como nueve horas por semana de vuelta en el piso.",next:"b"},
         {t:"Va muy bien",out:{r:"bad",concept:"Métrica de negocio vs métrica de modelo",why:"Un mes de trabajo y el reporte es una sensación. Si no puedes decir qué cambió en los términos de ella, o no lo mediste o prefieres no decirlo.",beat:"Treinta años de proveedores le han dicho a Doña Chelo que va muy bien. Tiene una cara para eso. Le estás viendo la cara."}}]},
  b:{say:"Nueve horas. Bueno. Ahora la otra — la cosa que lee las facturas del tomate. Sé honesto conmigo.",
     codex:"El entregable más difícil es el que dice deténganse. Un piloto que no rindió es información, y matarlo barato es una victoria que deberías poder decir en voz alta. La alternativa es un cementerio de proyectos a medio vivir cobrándole a alguien para siempre.",
     q:"El lector de facturas le ahorra veinte minutos por semana a Nando y te cuesta una hora por semana mantenerlo. ¿Qué va en el reporte?",
     ch:[{t:"Que cuesta más de lo que ahorra, y la recomendación es apagarlo",out:{r:"ok",concept:"Revisión honesta",why:"Señalar tu propio proyecto como el que hay que matar es lo que hace creíble cualquier otro número que reportes. Y no es un fracaso — ahora sabes exactamente qué parte sí valía la pena.",beat:"Chelo se queda callada. Luego: “Acabas de decirme que deje de pagarte por algo.” Escribe tu nombre en la pared junto a la caja — debajo de un nombre con letra más vieja."}},
         {t:"Dejarlo corriendo — ya está construido y no le hace daño a nadie",out:{r:"bad",concept:"Revisión honesta",why:"Cuesta una hora a la semana para siempre, se va a desviar, y un día va a estar mal mientras nadie mira. “Ya está construido” es la razón más cara que existe para conservar algo.",beat:"Once meses después el pescadero cambia su letra. Nadie se da cuenta en seis semanas."}},
         {t:"Reportar los veinte minutos ahorrados y omitir el costo de mantenimiento",out:{r:"bad",concept:"Revisión honesta",why:"Eso no es un reporte, es un argumento de venta con una hoja de cálculo encima. La primera vez que ella encuentre la hora faltante, todos los números que le diste valen cero.",beat:"Nando sabe. Nando siempre sabe."}},
         {t:"Pasárselo a Nando para que él lo mantenga",out:{r:"mid",concept:"Revisión honesta",why:"A veces es exactamente lo correcto — quien está más cerca del trabajo debería ser dueño de la herramienta. Pero pasarle una hora semanal de mantenimiento a alguien que no la pidió es una transferencia de costo disfrazada de entrega. Medio crédito: pregúntale primero.",beat:"Nando, sin alterarse: “¿Es aquí donde se vuelve mi problema?”"}}]}}},
 /* ---- Taller Herrera (24-31) ---- */
 {npc:"tacho",title:"La puerta",late:"La cortina sigue subiendo a las siete, joven. Sigo sin necesitar un computólogo. Pásale a ver de todos modos.",start:"a",nodes:{
  a:{say:"Tres carros en las rampas. Un cuarto en la banqueta, porque el papel no está listo. Chelo dice que sabes de computadoras. Le dije que no necesito un computólogo. Y me contestó, textual: «No dije que el computólogo fuera para ti. El libro de Yesenia está lleno.» Y me colgó. Entonces, joven, la mera verdad: ¿tú qué eres, exactamente?",
     codex:"El que más grita casi nunca es el cuello de botella. Un taller es una fila — carro que entra, diagnóstico, piezas, papel, carro que sale — y en algún punto un paso detiene a todos los demás. Encuentra el paso que espera antes de decir la palabra «app». Véndele a la restricción, no a la objeción; la objeción nomás es donde está el ruido.",
     q:"Tacho está esperando. ¿Qué le dices?",
     ch:[{t:"Venderle la app de entrada — foto que entra, presupuesto que sale, adiós papel",out:{r:"bad",concept:"Encontrar la restricción",why:"Contestaste una pregunta que nadie hizo. Las rampas están llenas; las manos no son el problema. El cuarto carro espera papel, y tú le ofreciste al mecánico una forma más rápida de hacer justo lo único que él no hace.",beat:"Tacho se vuelve a meter abajo del Caprice a media frase. Tu frase, no la de él."}},
         {t:"«Enséñeme cómo llega un carro de la calle a la rampa.»",next:"b"},
         {t:"«Me manda Chelo. Confíe en mí.»",out:{r:"mid",concept:"Encontrar la restricción",why:"Una recomendación abre una puerta. No dice dónde está el trabajo. Chelo respondió por tu criterio, no por un plan, y el hombre que tienes enfrente todavía no ha visto ninguno de los dos. Medio crédito — el nombre te metió; no te va a conseguir una rampa.",beat:"«Chelo también me mandó a uno que vende hielo. Esto es un taller, joven, no una iglesia.»"}},
         {t:"Ofrecer arreglar la tableta — te dijeron que tienen una que nadie usa",out:{r:"bad",concept:"Encontrar la restricción",why:"La tableta no está descompuesta; está sin usar, que es otro problema con otro dueño. Arreglar algo que sirve le devuelve el pleito al hombre que la metió al cajón, y tú acabas de escoger bando en un pleito del que ni te han contado.",beat:"Moy, desde la rampa dos, sin levantar la vista: «Sí sirve, profe. Ese es el problema.»"}}]},
  b:{say:"Compa, yo leo las vacantes para mi sobrino, así que ya sé qué eres — eres quien decide qué le toca a la máquina y qué no. Bueno. Este es el libro. Fecha de entrada. Qué dijeron que tenía. Qué dijo Tacho que tenía. Piezas pedidas, piezas aquí, listo, avisado, pagado. Un renglón por carro. Si me enfermo, el taller no sabe qué hay en las rampas.",
     codex:"Un calendario que vive en la letra de una sola persona es un atajo, con una diferencia frente a la mayoría: cuando esa persona falta, el edificio se queda ciego. Eso lo vuelve urgente, no desechable. Cada columna existe porque una vez algo salió mal sin ella. Lee el libro con quien lo lleva antes de construir lo que lo reemplaza, o lo vas a reconstruir, sin la lección.",
     q:"¿Qué haces con el libro?",
     ch:[{t:"Digitalizar el libro esta semana — las mismas columnas, en pantalla",out:{r:"bad",concept:"Leer el atajo",why:"Copiarías sus columnas sin saber para qué existe cada una, y la primera que quites es la que un día salvó un carro. Una pantalla con sus columnas es su libro con contraseña — el punto único de falla intacto, la lección perdida.",beat:"La primera versión digital no tiene columna para «qué DIJERON que tenía». Tacho pregunta a dónde se fue."}},
         {t:"Leer una semana del libro con ella y anotar para qué sirve cada columna",out:{r:"ok",concept:"Leer el atajo",why:"Ahora el libro es un documento de requerimientos y no un misterio, y Yesenia es la autora y no el obstáculo. Aprendes qué columnas son el calendario, cuáles son la memoria, y cuál es el papel que sigue al carro — antes de que exista una sola pantalla.",beat:"«¿Esa columna? Esa es la orden. En todos los talleres se llama igual. El único papel que sigue al carro. Nadie me había preguntado qué significan las columnas, compa. Nadie.»"}},
         {t:"Contratar a otra persona en recepción para que no sea todo ella",out:{r:"mid",concept:"Leer el atajo",why:"Sí le quita peso a una persona — al precio de un sueldo, y ahora el calendario vive en dos cabezas que tienen que ponerse de acuerdo. Hiciste el cuello de botella de dos personas de ancho en vez de quitarlo. Medio crédito por notar que lo carga sola.",beat:"Yesenia: «Perfecto. Entonces yo entreno a la nueva. Con el libro. Que ella tampoco puede leer.»"}}]}}},
 {npc:"moy",title:"El presupuesto por foto",late:"Profe, todavía tengo la foto de la defensa en el cel. Y el número que no debí mandar.",start:"a",nodes:{
  a:{say:"Profe, no le digas a Tacho todavía. Una clienta mandó foto de una defensa trasera toda abollada. La pasé por mi cel, me escupió partidas y un total, y le contesté «como $1,200». Decía 92% de confianza, o sea, ya es casi cotización, ¿no? Nomás quería ser yo el que contestara por una vez. Viene a las cuatro.",
     codex:"Un presupuesto parece predicción y funciona como promesa: el cliente oye un número y se organiza alrededor de él. Una herramienta puede armar las partidas desde una foto en segundos, y ese borrador vale. Pero el número que sale del taller es un compromiso, y un compromiso necesita que lo mire primero quien va a responder por él. Automatiza el borrador. Nunca automatices la promesa.",
     q:"Los $1,200 ya andan por ahí. ¿Cuál es la regla de aquí en adelante?",
     ch:[{t:"Dejar los $1,200 — la herramienta casi siempre le atina",out:{r:"bad",concept:"Borrador vs compromiso",why:"El cel no ve el soporte que está detrás de la defensa, y Moy tampoco desde un mensaje. Cuando el número real sea $1,900 la clienta no se acuerda del «como» — se acuerda de $1,200, y el taller se come la diferencia o la confianza. «Casi siempre le atina» no es un precio.",beat:"La clienta llega con la captura de pantalla. Tacho la lee y no dice nada, que se oye más fuerte."}},
         {t:"El cel arma las partidas; Tacho ve el carro antes de que salga cualquier número del taller",out:{r:"ok",concept:"Borrador vs compromiso",why:"El borrador hace el tecleo y Moy sigue siendo rápido — nomás ya no es el que promete. Los ojos de Tacho sobre el soporte cuestan cuatro minutos y convierten una adivinanza en un número que el taller puede sostener. La herramienta acelera el presupuesto; nunca se vuelve el presupuesto.",beat:"Tacho: «El manual dice tres punto dos horas para esa defensa. Son las horas de manual. El papel dice lo que vi. Por eso no mando números por mensaje, joven.»"}},
         {t:"Prohibir los presupuestos por teléfono — nadie manda un número, nunca",out:{r:"mid",concept:"Borrador vs compromiso",why:"Seguro, y te cuesta a la clienta que necesitaba una idea del precio antes de las cinco y la consiguió con alguien más. El problema nunca fue que saliera un número; fue que saliera sin que nadie lo leyera. Medio crédito — el instinto de proteger la promesa es el correcto.",beat:"A las cinco la misma clienta ya le mandó a Frederick la foto de la defensa por mensaje directo, pidiendo precio. No ha contestado. Está dormido."}},
         {t:"Mandar las partidas del cel con «es estimado, no cotización» en el pie",out:{r:"mid",concept:"Borrador vs compromiso",why:"Incertidumbre en el pie de página es certeza en el titular — la clienta lee $1,200 en letra grande y la advertencia en chiquito. Dilo para que sea verdad: si el número se puede mover, el número es el que tiene que decirlo. Medio crédito por saber que no era cotización.",beat:"Ella lee el total. No lee el pie de página. Nadie ha leído nunca el pie de página."}}]}}},
 {npc:"moy",title:"El mandado de las refacciones",late:"Todavía voy a pie a Calle Dos por las refacciones. Mis piernas ya tienen opiniones.",start:"a",nodes:{
  a:{say:"Profe, camina conmigo, es más rápido que explicarlo. Calle Dos, dos veces al día, porque el taller se entera de que no hay algo cuando Tacho ya tiene la mano metida en el motor. El mes pasado un proveedor mandó el alternador equivocado y pagamos el depósito dos veces. ¿Y si el sistema nomás pide? Baja el stock, pide, listo. Lo dejo armado hoy en la noche.",
     codex:"Parte cada proceso en los pasos que se pueden deshacer y los que no. Teclear, contar, vigilar una repisa, armar un pedido — todo reversible, todo aburrido, todo candidato a automatizarse por completo. El dinero que sale del taller no se deshace, y un sistema que repide no distingue entre equivocado y escaso. Automatiza hasta llegar al paso irreversible, y ahí pon el dedo de una persona en el botón.",
     q:"Moy quiere automatizar los pedidos. ¿Hasta dónde llega?",
     ch:[{t:"Hasta el final — el stock llega al punto de repedido y el sistema pide",out:{r:"bad",concept:"El paso irreversible",why:"Un punto de repedido sabe una sola cosa: que la cuenta está baja. No sabe que está baja porque el último envío venía mal, ni porque un carro se fue con la pieza todavía en la factura. El sistema que pide no distingue equivocado de escaso, y ahora cada error llega con depósito incluido.",beat:"Llegan tres alternadores. Todos equivocados. Todos con su core."}},
         {t:"El sistema vigila el stock y arma el pedido; una persona le da enviar",next:"b"},
         {t:"Seguir yendo a pie a Calle Dos — funciona",out:{r:"mid",concept:"El paso irreversible",why:"Sí funciona. También le cuesta a un mecánico en formación dos horas de piernas al día, y el taller sigue enterándose de que falta algo con la mano ya en el motor. No todo atajo merece conservarse. Medio crédito por no automatizar lo que todavía no entiendes.",beat:"Moy asiente. Moy sigue caminando. A la altura de la panadería, sus piernas empiezan a tener opiniones."}}]},
  b:{say:"Bueno, pero Yesenia no va a aprobar cada botella de líquido para el parabrisas, profe. Lo dijo con toda la cara. Y mira — en la carpeta de refacciones hay una hoja, letra más vieja, el plan de alguien: baja el stock, pide el sistema, nadie en enviar. Tacho la dejó ahí. Yo creo que de advertencia. Entonces, si una persona le da enviar — ¿a qué? Balatas, va. ¿Cinchos? ¿Dónde está la raya?",
     codex:"La raya entre «pasa solo» y «espera a una persona» no la marca solo el precio; la marca lo que no se puede regresar. Una pieza que se puede devolver es un error chico. Un depósito que pagas dos veces, un número de parte que nadie ha pedido antes, un pedido arriba del tope — esos duelen. Nómbralos, ponles candado, y deja que todo lo demás fluya solo.",
     q:"¿Dónde marcas la raya?",
     ch:[{t:"Todo espera a Yesenia — ella aprueba cada pedido",out:{r:"mid",concept:"Marcar la raya",why:"No sale nada mal, y no sale nada hasta que Yesenia tenga un minuto libre, que no tiene. Le construiste una pantalla al cuello de botella. El chiste de un candado es que la mayoría de las cosas no tengan que detenerse en él. Medio crédito por poner a una persona en enviar.",beat:"Día tres: cuarenta y un pedidos esperando. Uno es líquido de parabrisas. Yesenia no lo ha visto, por principio."}},
         {t:"Los consumibles pasan; lo que rebase el tope, traiga depósito o sea número nuevo, espera",out:{r:"ok",concept:"Marcar la raya",why:"Doscientas cosas en la repisa y quizá quince te pueden doler. Trapos y líquidos pasan solos; un depósito, un tope y un número de parte que nadie ha pedido se detienen ante una persona. Yesenia aprueba lo que importa, no ve lo demás, y el error que costó doble ya no puede repetirse.",beat:"Moy: «La pieza vieja es un depósito. Devuelves la equivocada y lo pagas dos veces. Eso es el core.» Se escribe CORE en la mano con plumón."}},
         {t:"Moy aprueba desde el cel entre rampa y rampa — es el más rápido",out:{r:"bad",concept:"Marcar la raya",why:"La acción rápida equivocada, metida a propósito. Una persona en enviar solo cuenta si esa persona está mirando; una aprobación tocada abajo de un carro con un pulgar grasoso es el plan automático con gafete. Dejaste la reja y quitaste al vigilante.",beat:"Aprueba un pedido desde abajo de un carro. Es para un carro que se fue ayer."}},
         {t:"Pedirle al proveedor que deje de mandar piezas equivocadas",out:{r:"mid",concept:"Marcar la raya",why:"Correcto, y completamente fuera de tu control — el del pescado de Nando, con otro mandil. A un proveedor se le puede pedir; el taller sigue necesitando un plan para el día en que la petición no aguante. Medio crédito: haz la llamada, y luego construye el candado como si no la hubieras hecho.",beat:"El proveedor dice que claro. La siguiente caja trae el alternador correcto, del año equivocado."}}]}}},
 {npc:"yesenia",title:"La tableta, otra vez",late:"La tableta sigue en el cajón, compa. El mismo cajón. Está bien descansada.",start:"a",nodes:{
  a:{say:"Compa, la tableta. La compraron el año pasado para el papeleo, para que Tacho anotara lo que hizo mientras lo hace. Vive en un cajón. No la toca. Entonces él me dice, yo lo tecleo, y si estoy al teléfono se lo dice a Moy, Moy me lo dice, y yo tecleo eso. Todos lo han intentado. Su primo lo intentó. El que la vendió lo intentó. Te toca.",
     codex:"Cuando una persona rechaza una herramienta, el reflejo es trabajar sobre la persona: capacitarla, explicarle otra vez, comprarle una mejor. Pero el rechazo de alguien que ya decidió no es una falta de capacitación. La palanca es el flujo de trabajo — quién toca qué, y cuándo. Mueve el paso a quien sí lo va a hacer, deja la decisión con su dueño, y nadie tiene que convertirse.",
     q:"Todos lo han intentado. ¿Tú qué intentas?",
     ch:[{t:"Capacitar a Tacho otra vez — despacio, con paciencia, pantalla por pantalla",out:{r:"bad",concept:"Cambiar el flujo",why:"No está confundido; ya decidió. Capacitar una decisión es una conversación que ya tuvo con todos los que vendieron, compraron o quisieron esa tableta, y perderla otra vez te cuesta lo único que traías al entrar — que no le habías pedido que cambiara.",beat:"Se aguanta toda la capacitación. Luego se limpia las manos con la tableta."}},
         {t:"Cambiar quién toca qué — Moy narra en la rampa, Yesenia confirma, Tacho firma como siempre",next:"b"},
         {t:"Comprar una tableta más grande — botones grandes, letra grande",out:{r:"mid",concept:"Cambiar el flujo",why:"Un arreglo real para un hombre cuya objeción son los botones. La de él no. Su objeción es qué va en el papel y quién tiene que responder por él, y ningún tamaño de pantalla contesta eso. Medio crédito por probar lo barato antes que lo difícil.",beat:"La tableta grande va al mismo cajón. No cabe. Entra de todos modos."}},
         {t:"Contratar a alguien que teclee por él",out:{r:"mid",concept:"Cambiar el flujo",why:"Un sueldo para rodear una firma. Funciona como funciona una segunda persona en recepción — el retecleo sigue pasando, nomás le pasa a alguien nuevo, y lo que él hizo sigue pasando por una boca antes de llegar a una pantalla. Medio crédito por ver que el retecleo es el costo.",beat:"Yesenia: «O sea, le pagamos a alguien para hacer lo que yo hago. Compa, aquí estoy, haciéndolo.»"}}]},
  b:{say:"Bueno. Moy habla en la rampa, el cel lo escribe, yo lo reviso. Me gusta. Pero aquí está el detalle, compa — al final, Tacho firma el papel. Cada trabajo. Lo lee, lo firma, el cliente se lo lleva. Es la única parte que nadie le ha podido quitar, y la mera verdad, yo no quiero que se la quiten. ¿Entonces qué pasa con el papel?",
     codex:"El dato sale más barato donde nace — en la rampa, en palabras de quien hace el trabajo, mientras lo hace. Una firma es otra cosa: es el momento en que alguien con autoridad lee el trabajo antes que el cliente. Captura el dato donde nace y deja la firma exactamente donde vive. El papel puede cambiar de forma. El paso en que alguien lo lee, no.",
     q:"Tacho firma el papel. ¿El papel cambia?",
     ch:[{t:"El papel se vuelve una impresión de lo que narró Moy; Tacho firma eso",out:{r:"ok",concept:"Donde vive la firma",why:"No le quitaron nada ni le pidieron nada. Sigue leyendo cada trabajo antes que el cliente, sigue con la pluma en la mano, y ahora las palabras de la hoja se dijeron en la rampa en vez de teclearse dos veces. Nunca cede. Esa es la victoria.",beat:"Tacho la lee, corrige una palabra, firma. «Va.» Yesenia: «Esa es la hoja del trabajo. Antes era yo. Dos veces.»"}},
         {t:"Saltarse la firma — con la narración basta",out:{r:"bad",concept:"Donde vive la firma",why:"Quitaste el único paso en que el maestro mecánico lee el trabajo antes que el cliente. La narración es lo que vio Moy; la firma es lo que Tacho sabe. Sin ella, la hoja es un chisme con el logo del taller.",beat:"Sale una hoja que dice «se cambió el alternador». Era la banda."}},
         {t:"Que firme en la tableta con un lápiz digital",out:{r:"mid",concept:"Donde vive la firma",why:"Moviste el pleito una pulgada. La firma es la misma; la superficie es justo lo que ya rechazó, y ahora la tiene en la mano con un lápiz pegado. El flujo iba bien hasta el último paso, y ahí estiró la mano al cajón. Medio crédito.",beat:"El lápiz está en el cajón antes de la comida. La tableta, como era de esperarse, ahí lo recibe."}}]}}},
 {npc:"tacho",title:"El ruido",late:"Los carros siguen haciendo ruidos. Los teléfonos siguen opinando. Abre el cofre.",start:"a",nodes:{
  a:{say:"Un Corolla. El de la cuadrilla de topógrafos, los que andan midiendo lo del tranvía. Llega con un ruido. Moy conecta su cel al puerto: «balero, delantero izquierdo». Noventa y uno por ciento, dice. Yo levanto el cofre y escucho cuatro segundos. Tensor de la banda. Nadie está gritando, joven. Él no hace mal en revisar. Yo no hago mal en escuchar. Pero uno de los dos firma el papel, y el carro se va a la autopista.",
     codex:"La versión honesta de «qué se queda con la persona» no es «la máquina no puede». Es cuestión de costo: cuando equivocarse es un carro en la autopista, la vara para confiar en un número es otra que para un mensaje. Que la herramienta lea y sugiera, que decida quien firma el papel, y que se anoten las dos — para que la diferencia sea lección y no costumbre.",
     q:"El cel dice balero. Tacho dice tensor. ¿Cuál es la regla en este taller?",
     ch:[{t:"Confiar en el código — el cel tiene datos, el oído tiene corazonadas",out:{r:"bad",concept:"La vara de confianza",why:"Un código dice dónde notó algo la computadora, no qué está mal. Un balero y un tensor pueden aventarle la misma queja a un sensor y no sonar nada parecido para alguien que ha oído mil de cada uno. Pusiste una adivinanza con porcentaje encima de treinta años de oído.",beat:"El Corolla regresa en grúa. Tacho no dice nada. Moy lo oye de todos modos."}},
         {t:"El cel lee códigos y sugiere; el oído de Tacho decide; Moy anota las dos, siempre",out:{r:"ok",concept:"La vara de confianza",why:"El cel se queda, porque sirve y porque prohibirlo no le enseña nada a Moy. La decisión se queda con el oído que carga la consecuencia. La libreta es la verdadera construcción: cada desacuerdo anotado, y en un año Moy sabe dónde se equivoca el cel — lo único que ningún cel le puede decir.",beat:"Tacho: «Un carro que regresa es un regreso. Con ese número llevo este taller. Anota las dos, Moy. En un año tú también lo vas a oír.» Y más bajito, a ti: «No me da miedo que se equivoque, joven. Me da miedo que le atine tanto que él deje de escuchar.»"}},
         {t:"Quitarle el cel a Moy — en este taller no se diagnostica con app",out:{r:"mid",concept:"La vara de confianza",why:"Acabas de prohibirle la herramienta a la única persona que va a seguir aquí en diez años. Las herramientas ya están adentro del edificio; entraron en una bolsa del pantalón. Prohibirlas no hace que Moy escuche, hace que diagnostique en el estacionamiento. Medio crédito por proteger el oído — palanca equivocada.",beat:"Moy guarda el cel. Moy revisa el código en el callejón. Tuerca lo mira desde el Caprice; ella no acusa."}},
         {t:"Que el cel lleve la batuta y Tacho revise cada carro de todos modos",out:{r:"mid",concept:"La vara de confianza",why:"Eso es Tacho haciendo cada diagnóstico con un paso extra adelante. Si el maestro mecánico vuelve a escuchar cada carro, el cel no ahorró nada y Moy no aprendió nada — el cel dijo, Tacho corrigió, nadie anotó. Medio crédito: la revisión está bien, el orden está al revés.",beat:"Ahora Tacho escucha cada carro dos veces. Una por el ruido, otra para saber qué creyó el cel que era."}}]}}},
 {npc:"yesenia",title:"La que no debió contestar",late:"Contestó otra pregunta de garantía mientras no estabas. Con educación. Mal, pero con educación.",start:"a",nodes:{
  a:{say:"Compa, lo de la entrada — lo que toma «qué tiene tu carro» y agenda la cita — está bueno, me gusta, cuarenta llamadas al día y yo contesto como diez. Pero. Ayer una señora le preguntó «¿esto me lo cubre la garantía?» y le dijo «Sí, muy probablemente». No la cubre. Ni tantito. Ya le contó a su hermana. Su hermana ya me contó a mí.",
     doc:"incidente-garantia",
     codex:"El alcance es una lista, no un ánimo. Una herramienta a la que le dijeron «sé útil» ayuda con lo que sea, incluidas las preguntas que no le tocan. Escribe las tres cosas que sí puede hacer y manda todo lo demás con una persona — con la pregunta pegada, para que nada se pierda. «Esa es para una persona» no es el asistente fallando. Es el asistente funcionando.",
     q:"¿Qué le cambias al asistente de entrada?",
     ch:[{t:"Agregarle «no contestes preguntas de garantía» a sus instrucciones",out:{r:"mid",concept:"Alcance como lista",why:"Las instrucciones empujan; no cierran la puerta. Dile que no conteste de garantía y se porta bien hasta que alguien pregunte por «lo de la cobertura», y ahí regresas al Viernes de Churros Gratis con grasa. Una regla escrita como sugerencia aguanta hasta que cambia la redacción. Medio crédito — buen blanco, cerca floja.",beat:"La otra semana: «¿La reparación está garantizada?» «Sí, muy probablemente.» No dijo garantía. Tuvo mucho cuidado de no decirla."}},
         {t:"Una lista corta de lo que sí puede; todo lo demás va con Yesenia, con la pregunta pegada",out:{r:"ok",concept:"Alcance como lista",why:"Describir el problema, agendar la cita, decir cuánto tarda un trabajo — tres cosas, por escrito. Lo que quede fuera no recibe una adivinanza, recibe a una persona, y la persona recibe la pregunta para que el cliente nunca la repita. El asistente pasa la llamada cuarenta veces por semana. Cada una es él funcionando.",beat:"La siguiente pregunta de garantía recibe «Esa es para Yesenia — ella te llama antes del mediodía». Yesenia: «Es educado. Es más educado que yo.»"}},
         {t:"Apagarlo — una respuesta mal ya es demasiado",out:{r:"bad",concept:"Alcance como lista",why:"El arreglo para una respuesta equivocada es un límite, no un apagador. Le devolviste cuarenta llamadas al día a un mostrador que ya las tenía, para castigar a una herramienta por hacer lo único que nadie le dijo que no hiciera. No se aprendió nada y el teléfono está sonando.",beat:"Suena el teléfono. Es una pregunta de garantía."}},
         {t:"Que conteste, pero que agregue «revise su documentación» al final",out:{r:"mid",concept:"Alcance como lista",why:"Cubrirse no es ser franco. «Sí, muy probablemente, revise su documentación» sigue siendo un sí con un pero engrapado, y el cliente oye el sí. Una advertencia protege al taller de la frase; no protege al cliente de creérsela. Medio crédito por saber que no debía sonar tan seguro.",beat:"Llama la hermana de la señora. Ya revisó su documentación. Quisiera platicar sobre «muy probablemente»."}}]}}},
 {npc:"tacho",title:"La plataforma del primo",late:"Mi primo sigue llamando los domingos. Ya subió el precio. Todo lo de él sube.",start:"a",nodes:{
  a:{say:"Camina conmigo, joven, Chelo me debe un café. Mi primo Rigo vende software para talleres — entrada, presupuestos, refacciones, los mensajes, un tablero, lo que sea que eso sea. Cuatrocientos al mes. «Todo lo que armaste, pero profesional.» Lo dijo con corbata. Yesenia hizo las cuentas: lo tuyo nos cuesta dos horas al mes mantenerlo. Lo de él trae un tablero de citas. Ella lo vio y se quedó callada, y ella no se queda callada. ¿Cómo la ves?",
     codex:"Construir, comprar o no — tres respuestas, y «hace de todo» no es argumento para ninguna. Compra cuando la pieza que comprarías le gana a lo que tienes, por menos de lo que cuesta mantener lo tuyo. Una plataforma es un paquete de decisiones con una sola etiqueta: desármalo, compra la pieza que gana, conserva lo que funciona, dile que no al resto, y anota el número.",
     q:"Cuatrocientos al mes, todo incluido. ¿Qué le dices el domingo?",
     ch:[{t:"Comprarlo — hace de todo",out:{r:"bad",concept:"Construir, comprar o no",why:"Todo es el precio. El taller usaría tres de cuarenta funciones y pagaría las cuarenta, cada mes, para siempre, y las tres que usara serían las tres que ya habías construido. «Hace de todo» es lo que dice un producto cuando no ha preguntado qué haces tú.",beat:"Chelo, desde atrás de la verdura, sin levantar la vista: «Para siempre es la palabra cara.»"}},
         {t:"Comprar solo el tablero de citas — conservar lo que sirve, decirle no al resto del paquete",out:{r:"ok",concept:"Construir, comprar o no",why:"El tablero llena un hueco que nunca construiste, y Yesenia lleva cuatro años queriéndolo. El borrador de refacciones y los mensajes cuestan dos horas al mes y funcionan; lo de él no los mejora. Una sola partida comprada, un número anotado, y un no a las otras treinta y nueve, en su cara.",beat:"Tacho, de regreso: «Le dijiste que no a mi primo en mi cara.» No es un reclamo."}},
         {t:"Nunca comprar nada — lo que se necesita se construye",out:{r:"mid",concept:"Construir, comprar o no",why:"Una respuesta real para un taller de tres rampas, dicha demasiado pronto. Hay cosas que vale la pena comprar — un tablero de citas que mantiene alguien más le gana a uno que tú parchas a medianoche. «Nunca» no es una comparación; es un humor con presupuesto. Medio crédito por no deslumbrarte.",beat:"Tacho: «Nunca es palabra mía, joven. Tú todavía no la puedes usar.»"}},
         {t:"Comprarlo — es familia, y así funciona esta calle",out:{r:"bad",concept:"Construir, comprar o no",why:"La familia es razón para cenar, no para software. El precio de un primo sigue siendo un precio, la migración de un primo sigue rompiendo el libro, y el primo va a seguir en la cena de Navidad cuando no sirva. Acabas de volver la mensualidad del taller un asunto de familia.",beat:"La demo de Rigo se traba con la palabra «Caprice»."}}]}}},
 {npc:"yesenia",title:"El libro",late:"El libro sigue en el mostrador, compa. Nunca decidí qué hacer con él. Te estoy preguntando a ti.",start:"a",nodes:{
  a:{say:"Seis de la tarde. El libro está en el mostrador. Lo de la entrada agenda las citas, Moy narra, Tacho firma, las refacciones me esperan a mí solo cuando deben. No lo he abierto desde el martes. ¿Entonces qué hago con él? Cuatro años, compa. Me gustaría irme a las seis una vez y ver cómo se ve.",
     codex:"Lo último que entregas no es una herramienta; es el mapa de cómo fluye el trabajo ahora — quién toca qué, quién firma, qué paso no se puede deshacer. Ese mapa es lo que deja que el taller sea dueño del proceso en vez de rentártelo. Y el registro viejo no se tira. Es un año de excepciones que nadie tecleó. Se cierra, y se guarda donde se pueda leer.",
     q:"¿Qué haces con el libro?",
     ch:[{t:"Tirarlo — el sistema ya tiene todo",out:{r:"bad",concept:"Ser dueño del proceso",why:"El sistema tiene las columnas. El libro tiene las excepciones — el carro que entró dos veces, la pieza que estaba bien en el papel y mal en la caja, la nota al margen que nadie tecleó porque no había dónde. Un año de eso se va al bote junto con la pasta.",beat:"Tacho lo saca del bote sin decir palabra y lo vuelve a poner en el mostrador."}},
         {t:"Cerrarlo. Ponerlo en la repisa junto a los manuales de Tacho. El mapa va a la pared.",next:"b"},
         {t:"Seguir llevándolo en paralelo — para siempre, por si acaso",out:{r:"mid",concept:"Ser dueño del proceso",why:"Esa es la hoja secreta de Nando con nombre y apellido. Dos registros, uno a mano, llevado por la única persona que se suponía que iba a dejar de ser el registro. «Por si acaso» es cómo un atajo sobrevive a lo que lo arregló. Medio crédito por respetar lo que hay adentro.",beat:"Yesenia: «O sea que lo sigo llevando. A las seis. Después.» No dice el resto."}}]},
  b:{say:"Bueno. Repisa, junto a los manuales — le va a gustar más de lo que va a decir. Ahora la pared. Moy ya pegó su propia regla arriba de la rampa dos: «El cel sugiere. Tacho decide. Se anotan las dos.» Con plumón. ¿Entonces qué va junto a eso? Puedo escribir todo, cada pantalla, cada botón. O una hoja. O nada, de todos modos está en el sistema. Dime antes de que empiece a teclear, compa, porque voy a empezar.",
     codex:"Un mapa de proceso es una sola hoja. Los pasos en orden, la persona en cada uno, los que necesitan firma, y los que no se pueden regresar, en círculo. Se cuelga donde la siguiente persona lo pueda leer desde la puerta sin contraseña. Cuarenta páginas son un manual que nadie abre; nada es el libro viejo con contraseña. Una hoja es lo que un taller puede hacer suyo.",
     q:"¿Qué va en la pared?",
     ch:[{t:"El manual completo — cuarenta páginas, cada pantalla, cada botón",out:{r:"mid",concept:"Mapa de una hoja",why:"Nadie lee cuarenta páginas en un taller; le preguntan a Yesenia, y eso la regresa a donde empezó. Todo lo que dice es cierto y nada se encuentra con las manos llenas de grasa. Medio crédito — es trabajo honesto, y su lugar es un cajón debajo de la hoja.",beat:"Cuarenta páginas, con pestañas y plastificadas. Moy le pregunta a Yesenia dónde está el paso de refacciones. Ella le dice. Página diecinueve."}},
         {t:"Una hoja — cómo se mueve un carro, quién toca qué, los pasos irreversibles en círculo",out:{r:"ok",concept:"Mapa de una hoja",why:"Este es el mapa de proceso, y es el entregable de verdad: el taller lo puede correr, leerlo desde la puerta y pasárselo a la siguiente persona sin llamarte. La firma de Tacho está ahí como un paso; el candado de refacciones es un círculo. El trabajo ya es de ellos. Para eso viniste.",beat:"Yesenia lo pega junto al mostrador y escribe abajo: «Si estás leyendo esto, ando comiendo.» Ese día llegan las camisas del taller — Tuerca en la bolsa. Idea de Yesenia."}},
         {t:"Nada en la pared — todo está en el sistema",out:{r:"bad",concept:"Mapa de una hoja",why:"Un sistema que nadie puede leer desde la puerta es el libro, digitalizado — un solo lugar donde vive el proceso, y una contraseña entre él y todos los demás. El día que la pantalla esté apagada, el proceso es lo que Yesenia se acuerde. Reconstruiste el punto único de falla con mejor tipografía.",beat:"Se va el internet un martes. Todos voltean a ver a Yesenia."}}]}}},
 /* ---- Panadería La Espiga (32-39) ---- */
 {npc:"licha",title:"Las treinta conchas",late:"Las conchas siguieron saliendo del horno mientras usted no estaba. La basura también.",start:"a",nodes:{
  a:{say:"Don Tacho dice que usted no vende nada. Qué bueno. Yo no necesito que me vendan nada. Le pregunté que entonces para qué servía, y me dijo que le preguntara a usted qué es lo que tiro. Pues fíjese. El martes: treinta conchas al bote. El miércoles: a las nueve ya no había, y las señoras se fueron con las manos vacías. La misma masa, el mismo horno, las mismas manos. Quiero una máquina que me diga el número, y la quiero antes de las cuatro de mañana.",
     codex:"Antes de pronosticar, encuentra dónde nace el número. Un pronóstico vale lo que vale el conteo que se come: qué se hizo, qué se vendió, qué se tiró y a qué hora. La mayoría de los negocios anota una de esas cosas y adivina el resto. Sigue el número hasta la mano que lo escribe antes de prometer que una máquina lo va a predecir.",
     q:"¿De dónde sale el número?",
     ch:[{t:"Armar el pronóstico desde la caja — ya sabe qué se vendió",out:{r:"bad",concept:"Rastrear el número",why:"La caja sabe qué se vendió. No sabe qué se horneó, qué se tiró ni a qué hora se vació la charola — que es toda la pregunta. Un modelo entrenado nomás con ventas aprende que la panadería nunca se queda sin pan, porque una vitrina vacía vende exactamente cero.",beat:"El modelo recomienda hornear exactamente lo que se acabó. Para siempre. La fila del miércoles se hace más larga."}},
         {t:"Averiguar quién cuenta qué, y a qué hora, antes de prometer un número",next:"b"},
         {t:"Hornear el promedio de los dos días",out:{r:"mid",concept:"Rastrear el número",why:"Es la versión honesta de la panza, y es lo que ella ya hace. Pero el promedio entre treinta de más y treinta de menos es un número sin razón adentro. Nadie midió por qué los dos días fueron distintos. Medio crédito por no hornear de más por una corazonada.",beat:"Jueves: quince al bote. Viernes: se acabó a las diez. Licha le dice progreso. Bolillo, el gato, desde el bote de la harina, no opina."}},
         {t:"Comprar una app de panadería que traiga pronóstico",out:{r:"bad",concept:"Rastrear el número",why:"Una herramienta sin historia tiene el mismo problema que un modelo sin historia, salvo que esta se renueva cada año. La app necesita que el conteo exista antes de poder aprender de él, y en este edificio nadie le ha pedido el conteo a nadie.",beat:"La app pide dos años de datos. Licha voltea a ver la tira de papel en el corcho."}}]},
  b:{say:"La tira de Sol. Cada noche escribe qué sobró de cada cosa y la prende en el corcho — yo no se lo pedí a esa criatura; empezó sola. Tito la lee a las 3:45, algunas noches. Nadie escribe a qué hora se acabó nada. Cuando se acaba, se acabó, y la señora se va a otro lado. Ahí tiene su conteo. Está en un papel que nadie pidió.",
     codex:"Los datos que necesitas casi siempre ya los está juntando la persona a la que nadie le preguntó. Una tira en un corcho, unas rayas en una servilleta, una columna en la cabeza de alguien. Antes de meter un sistema, agrégale la columna que falta al registro que ya existe, y quédate con quien lo lleva. Una herramienta nueva reemplaza el hábito; una columna nueva lo alarga.",
     q:"¿Qué haces con la tira?",
     ch:[{t:"Fotografiar la tira cada noche y agregarle una columna: la hora en que se acabó cada cosa",out:{r:"ok",concept:"Agregar la columna",why:"La tira ya tiene lo que sobró; la columna nueva tiene cuándo se acabó. Juntas son las dos puntas del día que la caja nunca ve. Para Sol no cambia nada más que una raya de plumón, y la foto convierte ocho semanas de papel en historia que un pronóstico sí se puede comer.",beat:"Sol agrega la columna con plumón. «La hora del “se acabó”. Se lo pude haber dicho hace meses, “consultor”.» Para el jueves aparece con la letra de Licha los días que Sol descansa."}},
         {t:"Cambiar la tira por una tableta en el mostrador",out:{r:"mid",concept:"Agregar la columna",why:"Digitalízalo con ella, no encima de ella. La tableta le pide a Sol cambiar un hábito que ya funciona, a la hora de cerrar, de pie, y la primera noche que se quede sin pila el conteo se pierde. La tira se queda y la foto hace lo digital. Medio crédito por quererlo en pantalla.",beat:"La tableta vive una semana debajo del mostrador. La tira sigue en el corcho. Sol sigue escribiendo la tira."}},
         {t:"Que mejor Tito cuente lo que hornea",out:{r:"mid",concept:"Agregar la columna",why:"Eso es lo que entra, no lo que sale. Las charolas horneadas te dicen qué se metió al día; la tira te dice qué salió por el otro lado. Necesitas las dos, y la que te falta es la hora en que se vació la vitrina, no el número de charolas. Medio crédito por contar algo a las 3:45.",beat:"Tito escribe «12» en el pizarrón y regresa al horno. Es, para ser justos, un conteo."}}]}}},
 {npc:"sol",title:"El par",late:"El número sigue en su cabeza. Lo revisé. Se movió.",start:"a",nodes:{
  a:{say:"Busqué en el teléfono qué eres. «Analista de operaciones: es quien te dice que el número estaba mal antes de que te cueste.» Okay. Entonces dile el número. Ella los trae en la cabeza — doce charolas de concha, no, diez, parece que va a llover — y cuando se acaba es «Sol, ¿por qué no dijiste?», y cuando se tira es «Sol, ¿por qué lo dejaste hornear tanto?». Un número por cosa, en papel, para que la culpa deje de caer en este mostrador, «consultor».",
     codex:"Un número fijo es una base desde la cual corregir, no una regla que obedecer. Escríbelo para poder equivocarte en papel en vez de en la basura: un par por producto por día de la semana, armado con unas semanas de conteos y movido cada semana según qué tan lejos quedó. El chiste del número no es que esté bien. Es que se vea lo suficiente para poder discutirlo.",
     q:"¿Cómo es el número?",
     ch:[{t:"Un número fijo por producto, que nunca cambia",out:{r:"bad",concept:"Fijar una base",why:"Un número fijo es la merma del martes y el faltante del miércoles hechos permanentes. Frena la culpa, y también frena el aprendizaje: la quincena, la lluvia y el calendario de la escuela siguen pasando, y el número deja de darse cuenta. La tira diría cada semana que está mal y a nadie le tocaría moverlo.",beat:"Viernes, día de pago. El número fijo se acaba a las 8:40. Sol anota la hora en la tira, con muy buena letra."}},
         {t:"Un par por producto por día de la semana, de ocho semanas de tiras, corregido cada semana",out:{r:"ok",concept:"Fijar una base",why:"Ocho semanas de tiras alcanzan para saber que el martes no es viernes. Corregirlo cada semana mantiene el número honesto sin que nadie lo cuide, y escribirlo lo saca de una sola cabeza y lo pone en una pared donde tres personas lo ven y una puede equivocarse en voz alta.",beat:"Licha, desde la puerta del horno: «¿Par? ¿Así se llama? Yo tengo un par desde hace treinta años. Nomás nunca lo escribí.» Los escribe en el pizarrón con su letra — la primera vez que el número sale de su cabeza."}},
         {t:"Que Licha lo siga trayendo en la cabeza — le ha funcionado treinta años",out:{r:"mid",concept:"Fijar una base",why:"Sí le ha funcionado, y ese es justo el problema: un número que nadie ve no se puede discutir, ni enseñarle a Tito, ni mejorar. Tampoco se le puede echar la culpa, y por eso la culpa cae en Sol. Medio crédito por respetar treinta años de casi siempre atinarle.",beat:"Licha asiente, satisfecha. Sol regresa a la caja. Las comillas alrededor de «consultor» se oyen más gruesas."}},
         {t:"Que la app decida el número cada día",out:{r:"mid",concept:"Fijar una base",why:"Un número diario sin base es un número que nadie puede discutir, y eso es peor que el de la cabeza de Licha: ella por lo menos te dice por qué. La app puede sugerir, pero moviendo un par que todos ven, no cambiándolo por una sorpresa cada mañana. Medio crédito por quererlo diario.",beat:"El número del martes es catorce. El del miércoles, nueve. Nadie, ni la app, sabe decir por qué."}}]}}},
 {npc:"tito",title:"Las tres cuarenta y cinco",late:"Las 3:45 llegan cada noche, cuate. No esperan a nadie. La lluvia tampoco.",start:"a",nodes:{
  a:{say:"Cuate. Las 3:45. La hoja dice doce charolas de concha. Está lloviendo. Desde la una. Nadie sale por conchas con lluvia; salen a las diez cuando para, y a las diez una concha de las cuatro ya es concha vieja. La hoja no sabe que llovió. Yo sí. Aquí junto al horno hay una tarjeta enmicada, letra de antes: PRONÓSTICO IA v1, hornea lo que diga. No tiene dónde escribir que no. Entonces. ¿Puedo no estar de acuerdo?",
     codex:"El pronóstico sugiere; quien está en el horno decide. Una hoja armada con ocho semanas de historia no tiene ventana, y quien sí la tiene está parado ahí a las 3:45. La regla no es obedecer el número ni ignorarlo, sino contradecirlo en voz alta — por escrito, con la razón — para que el desacuerdo se vuelva algo de lo que el pronóstico pueda aprender.",
     q:"¿Qué hace Tito con las doce?",
     ch:[{t:"Hornear lo que dice la hoja — ella tiene los datos",out:{r:"bad",concept:"Quién decide",why:"Tiene ocho semanas y ninguna ventana. El hombre de las 3:45 tiene la ventana. Los datos que no ven el día de hoy pierden contra la persona que sí, y cuando pierden el costo es una charola entera al bote — esta vez con el nombre de la hoja encima, que es como un negocio aprende a dejar de creerle.",beat:"Doce charolas, lluvia, treinta y una conchas al bote. Esta vez la culpa es de la hoja. Tito no dice nada, muy fuerte."}},
         {t:"Tito le cambia el número — y escribe el cambio y la razón en la hoja",next:"b"},
         {t:"Apagar el pronóstico los días de lluvia",out:{r:"mid",concept:"Quién decide",why:"Acabas de apagar la herramienta justo los días en que más necesita aprender. La lluvia no es ruido; es un patrón que la hoja nunca ha visto, y nunca lo va a ver si cada día de lluvia queda en blanco. Medio crédito por saber que la hoja no ve el clima.",beat:"Los días de lluvia no se anotan. En un mes la hoja está segura de que aquí nunca llueve."}},
         {t:"Llamarle a Licha a las 3:45 y preguntarle",out:{r:"bad",concept:"Quién decide",why:"Eso es el cuello de botella con teléfono. Licha metida a las 3:45 significa que cada decisión en el horno espera el sueño de una sola persona, y el cambio de todos modos nunca se escribe — nomás se dice. El pronóstico no aprende nada y Licha aprende a dormir con el teléfono.",beat:"Contesta al primer timbrazo. Está despierta desde las tres. Siempre lo está."}}]},
  b:{say:"Un mes, cuate. Seguí con la hoja y llevé mi columna. Trece veces me le fui en contra. Nueve veces yo tenía razón y ella no. Cuatro veces ella tenía razón y yo no — el día que al final no llovió, el día que no hubo escuela y yo no sabía. ¿Y ahora? Ella se equivocó nueve. Yo me equivoqué cuatro. Alguien tiene que ser el que atina.",
     codex:"Un registro de desacuerdos es el dato más honesto que un pronóstico va a recibir. Mide a la persona y al modelo uno contra el otro — no para escoger ganador, sino para encontrar dónde está ciego cada uno. El modelo no ve la lluvia; la persona no ve que se movió la quincena. Regresa los desacuerdos y los dos mejoran en lo que el otro ya sabía.",
     q:"¿Qué haces con trece desacuerdos?",
     ch:[{t:"Guardar los cambios y regresárselos cada mes, para que la hoja aprenda lluvia y quincena",out:{r:"ok",concept:"Aprender del desacuerdo",why:"Nueve y cuatro no es un marcador, es un mapa. Los nueve dicen dónde está ciega la hoja; los cuatro, dónde está ciego Tito. Una pasada mensual que le enseñe a la hoja la lluvia y la quincena convierte su columna en datos de entrenamiento, y le deja la mano en la decisión mientras aprende.",beat:"Tito: «La lista de horneado. Ya tiene dos columnas: lo que dijo y lo que hice. Entonces no soy yo contra la lista.» No. «Bueno. Ya me había cansado de ganar.»"}},
         {t:"El modelo se equivocó cuatro veces — quítalo",out:{r:"bad",concept:"Aprender del desacuerdo",why:"Tito también se equivocó cuatro veces. Estarías corriendo a la herramienta por la tasa de error del humano, y regresando a un solo hombre decidiendo solo a las 3:45 sin nada que lo contradiga — que es justo lo que tiraba treinta conchas antes de que llegaras.",beat:"La hoja se va a un cajón. La basura regresa a lo que era. Tito regresa a adivinar solo."}},
         {t:"Tito se equivocó cuatro veces — quítale el derecho a cambiar el número",out:{r:"bad",concept:"Aprender del desacuerdo",why:"Le quitaste la ventana a la única persona parada frente a ella. Los nueve aciertos se fueron con los cuatro errores, y ahora la hoja es la última palabra en días que nunca ha visto. Los cuatro errores salían baratos; los nueve eran los que mantenían el pan fuera del bote.",beat:"Tito hornea lo que dice la hoja. Está lloviendo. No levanta la vista."}},
         {t:"Promediar los dos automáticamente",out:{r:"mid",concept:"Aprender del desacuerdo",why:"Un promedio entre doce y ocho es un número que nadie hizo, así que nadie lo puede explicar y nadie aprende de él. El cambio valía porque una persona lo respaldaba; promediarlo guarda el desacuerdo y tira la razón. Medio crédito por no tomar partido.",beat:"Diez charolas. Tito mira el diez. «¿De quién es este número?» De nadie."}}]}}},
 {npc:"sol",title:"El pastel con el nombre mal",late:"Hicimos otro pastel con nombre. No digo cómo salió. Digo que vengas a ver.",start:"a",nodes:{
  a:{say:"El pastel grande del sábado. Tres pisos, tamaño quinceañera, y arriba en gel azul: «Feliz Cumpleaños Brayan». Es Bryan. Con i griega. La tía lo pidió por teléfono desde otro estado, yo lo anoté en una servilleta, la servilleta le llegó a Tito, y Tito escribe lo que lee. Ahora anda circulando una foto con el nombre encerrado en un círculo. La servilleta tenía mi letra, así que adivina de quién dicen que fue. Arregla la servilleta, «consultor».",
     codex:"Un pedido especial es una promesa con fecha. Tómalo con formato — fecha, tamaño, sabor, dedicatoria, anticipo — no como una frase, y léeselo de vuelta al cliente antes de que el horno lo vea. La dedicatoria es el único campo que nadie puede corregir después, así que es el que el cliente confirma letra por letra.",
     q:"¿Cómo se toman los pedidos de pastel?",
     ch:[{t:"Que el asistente tome los pedidos por teléfono y los pase directo a la lista de Tito",out:{r:"bad",concept:"Pedido estructurado",why:"Eso es la servilleta, pero tecleada. El texto libre sigue yendo de un oído a una lista sin que nadie revise lo único que no se puede raspar de un pastel. El asistente oye Brayan igual de fácil que Sol, y ahora está en la lista con letra de imprenta, que lo hace ver confirmado.",beat:"«Feliz Cumpleaños Braian». Una tercera forma de escribirlo. Por lo menos va a máquina."}},
         {t:"El asistente llena el formato y lo lee de vuelta; el cliente confirma el nombre por mensaje",out:{r:"ok",concept:"Pedido estructurado",why:"La dedicatoria es un campo, no una frase, y es del cliente. Leerlo de vuelta atrapa el error del oído; el mensaje atrapa el de la pluma; el anticipo llega después de los dos, así que nadie hornea una promesa que no se ha deletreado. La tía de otro estado sigue pudiendo pedir. Nomás teclea el nombre una vez.",beat:"La clienta contesta «BRYAN, con Y» y un corazón. Sol engrapa el mensaje al pedido. Tito lo lee dos veces."}},
         {t:"Solo tomar pedidos de pastel en persona, en el mostrador",out:{r:"mid",concept:"Pedido estructurado",why:"En persona puedes señalar la ortografía, y ese instinto está bien. Pero pierdes a la tía que llama de otro estado, a la mamá en su hora de comida y a todos los pedidos que llegan cuando el mostrador tiene tres de fila. El arreglo es leerlo de vuelta, no el cuarto. Medio crédito por querer ojos en el nombre.",beat:"La tía vuelve a llamar. Sol le dice que tiene que venir. La tía está en otro estado. La línea se queda callada."}},
         {t:"Imprimir lo que el cliente escribió tal cual — sin leerlo de vuelta",out:{r:"mid",concept:"Pedido estructurado",why:"Ahora la ortografía es del cliente, que es mejor que una servilleta. Pero nadie revisa el campo donde el cliente se equivocó al teclear, y un error de dedo en betún sigue siendo problema de Sol a la hora de entregar. Leerlo de vuelta es barato: es un mensaje. Medio crédito por sacar el nombre de la letra de Sol.",beat:"«Feliz Cumpleños». Error de ella. Problema de Sol. La foto circula de todos modos."}}]}}},
 {npc:"licha",title:"El del autoservicio",late:"El del autoservicio sigue ahí. Ya tiene letrero más grande. Las palomas comen muy bien.",start:"a",nodes:{
  a:{say:"Hace seis semanas el del autoservicio abrió mostrador de panadería en la punta norte. Conchas en plástico, por una ventanita, desde el coche. Los pares están mal todos los días desde entonces. No un poquito mal — mal de la misma manera, cada mañana, para el mismo lado. Y la hoja me sigue diciendo el trimestre pasado. El único número que subió son los cuarenta bolillos a las cinco para la cuadrilla que está poniendo la vía. Todo lo demás es palomas.",
     doc:"deriva-espiga",
     codex:"Deriva: el mundo cambió y el modelo no. Un pronóstico entrenado con el trimestre pasado sigue recomendando el trimestre pasado, y la basura es el último lugar donde quieres enterarte. Lleva el error en el tiempo y fíjate para qué lado apunta. El ruido anda de un lado a otro; la deriva da un escalón y se queda. Cuando dé el escalón, reentrena con las semanas desde el escalón, no con el año de antes.",
     q:"Seis semanas con los pares mal. ¿Qué haces?",
     ch:[{t:"Meter más charolas — los números nomás andan chuecos",out:{r:"bad",concept:"Detectar la deriva",why:"La deriva no es ruido. Si el error lleva seis semanas apuntando al mismo lado, más del trimestre pasado es más basura, no más ventas. La hoja no está un poco desfasada; está describiendo una calle que ya no existe, y el arreglo es enseñarle la nueva.",beat:"Cuarenta y dos conchas. Récord. Las palomas de la punta norte son las más gordas de la calle."}},
         {t:"Ver el error por semana; si giró hace seis semanas, reentrenar desde ahí, no con el año",out:{r:"ok",concept:"Detectar la deriva",why:"La gráfica es el detector. Un escalón limpio hace seis semanas dice que el mundo se movió en una fecha, y un modelo que aprende del año anterior a esa fecha está aprendiendo una mentira. Reentrenar con las semanas desde entonces le da a la hoja la calle como es hoy — más chica, y con una cuadrilla a las cinco.",beat:"Un escalón limpio, seis semanas atrás. Licha toca la fecha: «Ahí pusieron el letrero. La merma. El pan que se va por la puerta de atrás. Seis semanas dándoselo a las palomas y diciendo que era mi humor.»"}},
         {t:"Dejar los números viejos — los clientes van a regresar",out:{r:"mid",concept:"Detectar la deriva",why:"Algunos sí; una concha de autoservicio es una concha de autoservicio. Pero apostar la basura a una esperanza no es un plan, y mientras esperas la hoja sigue recomendando con toda confianza un trimestre que ya se acabó. Vigila el error; si los clientes regresan, la gráfica lo va a decir primero. Medio crédito por la lealtad.",beat:"Una queja de las conchas del autoservicio cae en los mensajes de Frederick — su página no tiene teléfono. Sonny contesta con una pata."}},
         {t:"Igualar sus precios",out:{r:"mid",concept:"Detectar la deriva",why:"Puede ser. Una guerra de precios es decisión de Licha, no un arreglo del pronóstico — cambia lo que gana una concha, no lo que la hoja cree que quiere la calle. Primero atina el número, para que cuando ella decida el precio lo decida desde un conteo y no desde un humor. Medio crédito por tomarse en serio la competencia.",beat:"Licha hace la cuenta atrás de una tira. «A su precio, les estoy pagando a las palomas por comer.»"}}]}}},
 {npc:"tito",title:"La temporada de rosca",late:"Enero llega cada año. Ese es todo el problema con enero.",start:"a",nodes:{
  a:{say:"Enero, cuate. Rosca. Una semana y vendemos más que en un mes normal. El año pasado: se acabó a mediodía el 5, señoras gritando. El 7: cuarenta al bote, y la rosca no aguanta. La hoja ha andado bien desde lo de la lluvia. Pero la hoja nunca ha visto un enero. Cree que enero es un martes. Trae ocho meses de concha adentro y me va a hablar de rosca. Dime qué horneo.",
     codex:"Los picos de temporada no se pronostican con la historia diaria; un modelo que nunca ha visto la temporada cree que la temporada es un martes. Planea esa semana aparte: el conteo del año pasado, los pedidos anticipados de este año y un número firmado por quien manda. Luego mide la semana contra ese número, para que el plan del año que viene arranque de un registro y no de un recuerdo.",
     q:"¿Cuántas roscas?",
     ch:[{t:"Creerle a la hoja — ha atinado todo el año",out:{r:"bad",concept:"Planear el pico",why:"Ha atinado los martes. Un modelo que nunca ha visto un enero cree que enero es un martes, y lo va a decir con la misma seguridad con la que habla de conchas. Nueve meses de buenos números no traen ni una sola rosca; la hoja no está mal, está ciega.",beat:"Recomienda nueve roscas. Nueve. Licha se ríe hasta que tiene que sentarse."}},
         {t:"Planear la semana aparte: el año pasado, los pedidos anticipados, un número que Licha firme",next:"b"},
         {t:"Hornear todas las que se pueda — es la semana que paga",out:{r:"mid",concept:"Planear el pico",why:"Hornear todo lo que se pueda es un plan para el 5 y un desastre para el 7. La rosca no se vuelve pan de ayer; se vuelve basura, y la semana que paga febrero acaba pagándoles a las palomas. Medio crédito por saber que la semana es más grande de lo que dice la hoja.",beat:"El 7: sesenta roscas en el anaquel, una señora, y un muñequito de plástico en cada una."}},
         {t:"Saltarse la rosca este año — muy difícil de predecir",out:{r:"bad",concept:"Planear el pico",why:"Esa es la única semana que paga febrero. Que sea difícil de predecir no es razón para dejarla; es razón para planearla distinto que un martes. Una panadería que se salta la rosca en enero le está diciendo a la calle dónde comprarla — y la calle ya tiene una ventanita para eso.",beat:"El del autoservicio vende rosca. En caja. Las señoras la compran y no perdonan a nadie."}}]},
  b:{say:"Pedidos anticipados. Licha dice que la gente no va a querer. Yo digo que sí, si es rosca. El año pasado: doscientas diez para mediodía del 5, luego nada, luego cuarenta al bote el 7. Este año quiero un número antes de prender el horno. No una corazonada — un número con nombres. ¿Cómo lo sacamos?",
     codex:"Convierte la demanda en conteo. Un pedido anticipado con anticipo es una adivinanza que se volvió número, y cada uno que tomas encoge la parte de la semana que todavía tienes que pronosticar. Lo que queda — la parte de mostrador, la gente que llega sin pedir — la planeas del año pasado y la llevas por hora, para que la temporada deje un registro del que la siguiente pueda arrancar.",
     q:"¿Cómo planeas la semana?",
     ch:[{t:"Pedidos con anticipo; hornear esos más lo de mostrador del año pasado, llevado por hora",out:{r:"ok",concept:"De demanda a conteo",why:"El anticipo hace real el pedido, así que el número trae dinero atrás. La parte de mostrador del año pasado cubre a las señoras que nunca han pedido nada por adelantado, y llevarlo por hora el 5 y el 6 le dice a Tito para mediodía si el 7 necesita una segunda hornada o una más chica.",beat:"Tito: «El pan de ayer es una cosa, cuate. La rosca de ayer es un velorio.» El 7: quedan cuatro roscas. Tito duerme."}},
         {t:"Sin pedidos anticipados — simple, hornear del conteo del año pasado",out:{r:"mid",concept:"De demanda a conteo",why:"Simple, y a ciegas. El conteo del año pasado es un número de una semana, y no sabe que abrió un autoservicio ni que la cuadrilla de la vía anda en el barrio. Los pedidos anticipados te habrían dicho las dos cosas para el día 3. Medio crédito por usar el único registro que existe.",beat:"El 5 se acaba a la una en vez de a mediodía. El 7: veinte al bote. Mejor. Para enero, no alcanza."}},
         {t:"Solo pedidos anticipados — nada de mostrador",out:{r:"bad",concept:"De demanda a conteo",why:"Acabas de convertir la panadería en una ventanilla que pide boleto. La parte de mostrador es el barrio; los pedidos son la gente que planea. Hornea solo para los segundos y los primeros se van al del autoservicio, con caja y sin anticipo.",beat:"El 6: una señora en el mostrador con efectivo y sin pedido. Veinte años viniendo. Se va sin nada."}}]}}},
 {npc:"sol",title:"El número en sus unidades",late:"Me volvió a preguntar si funciona. Le dije un porcentaje. Hizo la cara.",start:"a",nodes:{
  a:{say:"Me preguntó si funciona. Licha. Delante de una clienta. Yo tengo los números — tengo todos los números, es lo único que sí tengo — el error bajó de 19% a 11% desde que se reentrenó, y se lo dije, y los ojos se le fueron a otro lado. Dijo «ah». Mañana me va a volver a preguntar. ¿Qué le digo, «consultor»? Y que quepa entre una clienta y la siguiente.",
     codex:"Reporta el error en las unidades de quien manda — charolas al bote, mañanas en que se acabó temprano, dólares — y di para qué lado se equivocó. Un porcentaje sin dirección es un encogimiento de hombros: dice que el modelo se portó bien y nada sobre si al negocio le fue mejor. Quien preguntó tiene una panadería, no un modelo, y solo puede gastar una respuesta en su propia moneda.",
     q:"¿Qué le dice Sol?",
     ch:[{t:"11%, bajó de 19%",out:{r:"mid",concept:"En sus unidades",why:"Cierto, e inservible. Un porcentaje le dice a Licha que el modelo se porta bien; no le dice si tiró menos pan, y no dice para qué lado falló — de más o de menos. Medio crédito por medir algo, que la mayoría de los negocios nunca hace.",beat:"Licha mira el número un buen rato. «¿Y?»"}},
         {t:"Dos charolas menos al bote al día, una mañana sin pan y no tres, como $140 a la semana",out:{r:"ok",concept:"En sus unidades",why:"Charolas, mañanas, dólares — tres cosas que Licha ya cuenta, en el orden en que las siente. La dirección también va ahí: menos al bote y menos veces sin pan es la única combinación que significa que los dos errores bajaron. Cabe entre una clienta y la siguiente, y ella puede cotejar cada palabra contra su propia basura.",beat:"Licha asiente una vez. Sol, hacia ti, sin comillas esta vez: «Okay. Consultor.»"}},
         {t:"Va muy bien",out:{r:"bad",concept:"En sus unidades",why:"Un mes de tiras y el reporte es una sensación. Si Sol no puede decir qué cambió en los términos de Licha, o nadie lo midió o alguien prefiere no decirlo — y Licha lleva treinta años oyendo esa frase de cada vendedor de harina, así que tiene una cara para eso.",beat:"Licha tiene la cara de su mamá para esto. La estás viendo. Sol también la está viendo."}},
         {t:"Enseñarle la gráfica en el teléfono",out:{r:"mid",concept:"En sus unidades",why:"Una gráfica es el dibujo de un número que ella no pidió. Trae la respuesta adentro, pero le pide a Licha hacer la traducción — a charolas, a mañanas — que le toca a Sol hacer antes de abrir la boca. Medio crédito: la gráfica es real, y puede salir después de la frase.",beat:"Voltea el teléfono de lado, luego de cabeza, y se lo devuelve."}}]}}},
 {npc:"licha",title:"La última charola",late:"La última charola sigue siendo la última. Lo que le debo no ha cambiado. Ni lo que pasa cuando usted no está.",start:"a",nodes:{
  a:{say:"Sábado, hora de cerrar. Dos conchas en la última charola. Nada en el bote, nadie se fue sin pan desde el martes. La tira de Sol tiene su columna, Tito tiene la suya, los pares están en el pizarrón. Oiga. Dos preguntas, y las quiero derechas. Qué le debo. Y qué pasa cuando usted no esté — porque no va a estar. Si la hoja se sabe el número, ¿mis manos lo olvidan?",
     codex:"La entrega no es el modelo; son las notas de descubrimiento. Dónde nace cada número, quién lo escribe, a qué hora, y qué se hace la semana en que la hoja está mal. Un negocio es dueño de un pronóstico solo cuando es dueño del conteo que lo alimenta y puede seguir contando el día que el consultor se va. Lo demás es una máquina prestada.",
     q:"¿Qué pasa cuando tú no estás?",
     ch:[{t:"Dejar el modelo corriendo — va a estar bien",out:{r:"bad",concept:"Adueñarse del conteo",why:"Un modelo que nadie alimenta se muere de hambre, y la tira de Sol es la comida. El día que la tira se detenga, la hoja sigue recomendando el mes pasado con toda confianza, y a nadie en el edificio le dijeron que esa era la falla que había que vigilar. No entregaste un pronóstico; lo dejaste enchufado.",beat:"Febrero. Sol enferma una semana. La hoja recomienda doce charolas de nada, y Tito la lee a las 3:45."}},
         {t:"Escribir una página: quién cuenta qué, a qué hora, y qué hace Tito cuando la hoja se equivoca",next:"b"},
         {t:"Enseñarle a Licha a mover la configuración del modelo",out:{r:"mid",concept:"Adueñarse del conteo",why:"Ella debe ser dueña del número, no de las perillas. Una mañana en la pantalla de configuración hace a Licha responsable de algo que no pidió entender, y la primera vez que se porte raro lo va a apagar o te va a llamar. El conteo es de ella; el ajuste puede ser de cualquiera. Medio crédito por entregar algo.",beat:"Licha escucha la lección completa. Al final pregunta dónde escribe el par. En el pizarrón, todavía."}}]},
  b:{say:"¿Y entonces qué me queda, vecino? No la máquina. Lo que se pueda agarrar con la mano. Tito lee un solo papel a las 3:45 y más vale que sea el bueno. Sol tiene tres de fila a las siete. Yo tengo treinta años y un corcho. Escríbalo para que quepa en el corcho de arriba del horno, o escríbalo para alguien más.",
     codex:"El documento que un negocio conserva es el que cabe en el corcho de arriba del horno. Una entrega que necesita contraseña, cuenta o carpeta se lee una vez, el día de la entrega. Una página — tres conteos, tres personas, tres horas y la regla para el día en que el número está mal — se lee cada noche al cerrar, y esa es la única clase de documento que te sobrevive.",
     q:"¿Qué va arriba del horno?",
     ch:[{t:"Tres conteos, tres personas, tres horas, una regla: la hoja sugiere, Tito decide, se anota",out:{r:"ok",concept:"Cabe en el corcho",why:"Eso son las notas de descubrimiento, llenadas a las 4 de la mañana: dónde nace el número, qué mano lo escribe, y la única regla que mantiene a la hoja como sugerencia. Cabe en el corcho, no cuesta nada conservarla, y cada persona nombrada ahí puede leer su propio renglón sin preguntarle a nadie.",beat:"La prende junto a los pares y se contesta sola: «No. Las manos no olvidan. Nomás dejan de estar solas.» Llegan los mandiles de Xochi: una espiga en el pecho, y en el de Sol una bolsa cortada justo para la tira."}},
         {t:"Un tablero en la tableta",out:{r:"mid",concept:"Cabe en el corcho",why:"Una página que necesita contraseña. El tablero lo trae todo y lo abre la única persona que sabe la clave, los días que se acuerda, que no es a las 3:45 ni a la hora de cerrar. Medio crédito — hazlo si quieres, después de que la página esté en el corcho.",beat:"La tableta pide contraseña. Tito la mira, luego mira el corcho, y hornea. Bolillo se sienta encima de la tableta."}},
         {t:"El código del modelo, impreso y engargolado",out:{r:"bad",concept:"Cabe en el corcho",why:"Nadie en este edificio lo puede leer, y quien sí puede se está yendo. Entregar el código es entregar la capa equivocada: la panadería no necesita saber cómo piensa la hoja, necesita saber qué la alimenta y cuándo contradecirla. Un engargolado no es ser dueño de nada.",beat:"Tito forra una charola con él. Las conchas salen bien."}}]}}},
 /* ---- Limpieza Velázquez (40-47) ---- */
 {npc:"vero",title:"Doce sitios",late:"Doce sitios siguen siendo doce, inge, y sigo teniendo nueve personas. A la cuenta no se le olvidó.",start:"a",nodes:{
  a:{say:"Súbete, inge, Pelusa no muerde. El del autoservicio mandó una solicitud de cotización — doce tiendas en el norte, de noche, empezando el día que abra la línea. Tengo nueve personas, tres camionetas y una app que pagué el año pasado y que nadie abre. Quiero decir que sí. Quiero decir que sí y comprar una app más grande, la del tablero bonito. Dime que no estoy loca.",
     codex:"Primero la adopción, luego la expansión. Una herramienta que nueve personas ignoran, veinte la van a ignorar también — crecer no arregla una herramienta que nadie usa, multiplica el ignorarla. Antes de escalar un proceso, averigua si la versión chica está viva: quién la abre, quién le saca la vuelta y por qué. Un contrato con fecha de inicio es el peor lugar para probar dos incógnitas a la vez.",
     q:"Vero quiere cotizar para el viernes. ¿Qué le dices?",
     ch:[{t:"Comprar la plataforma grande y cotizar — doce sitios necesitan un sistema de verdad",out:{r:"bad",concept:"Adopción antes de expansión",why:"Son dos incógnitas — una plataforma que nadie ha usado y un contrato que nadie ha cubierto — enrolladas en una sola promesa con fecha. Si la app nueva falla como falló la vieja, te enteras la primera noche, en doce sitios.",beat:"Llega la plataforma grande. La capacitación viene solo en inglés. La cuadrilla no."}},
         {t:"Averiguar por qué nueve personas no abren la app antes de decidir qué necesitan veinte",next:"b"},
         {t:"Rechazar la cotización — nueve personas no cubren doce sitios",out:{r:"mid",concept:"Adopción antes de expansión",why:"Honesto, seguro, y la línea abre una sola vez. Decir que no a un contrato que no puedes cubrir está bien; decir que no antes de saber si el cuello de botella es la herramienta o la gente es rendirse por una corazonada. Medio crédito por no prometer de más.",beat:"Vero dobla la solicitud a la mitad. No la tira. Pelusa se le sienta encima."}},
         {t:"Cotizar, y contratar a doce personas nuevas que sí usen la app",out:{r:"bad",concept:"Adopción antes de expansión",why:"La gente nueva no arregla una app que la vieja odia; aprende a odiarla más rápido, de los mismos que le enseñan el trabajo. Y nueve personas acaban de oír que el plan para crecer es alguien más.",beat:"Chente oye «doce personas nuevas» desde el pasillo. Va muy callado de regreso."}}]},
  b:{say:"Chente, cuéntale lo que me dijiste anoche. Ándale. — «Quiere foto de cada inodoro. En inglés. Antes de poder checar salida. Marta no lee inglés. El inodoro tampoco.» — No le falta razón, inge. La compré por una demo. Nadie me enseñó la parte del inodoro. Y a él nadie le preguntó. Hasta ahorita.",
     codex:"El primer usuario es el que la odia, y sus quejas son la especificación. Una herramienta que hace el trabajo más lento la van a evitar sin importar cómo la lances; la forma más rápida de encontrar los puntos lentos es pararte junto al trabajo y anotar cada uno. Las quejas son requisitos que el pitch dejó fuera.",
     q:"¿Cómo averiguas lo que la app les está costando de verdad?",
     ch:[{t:"Ir un turno de noche con una cuadrilla y anotar dónde la app hace el trabajo más lento",out:{r:"ok",concept:"Quejas como especificación",why:"Un turno, una cuadrilla, sin encuesta. Ves la foto del inodoro con la lámpara en la mano, ves quién teclea y quién espera, y la cuadrilla te ve anotar sus quejas en vez de discutirlas. Esa lista es la especificación de lo que construyas o compres después.",beat:"Tres horas, una foto de inodoro, once notas; Marta escribió cuatro. Vero: «Eso es un recorrido. Lo hago en cada sitio que cotizo. Nunca lo hice con mi propia cuadrilla.»"}},
         {t:"Hacerla obligatoria, con un bono por cada turno cerrado en la app",out:{r:"mid",concept:"Quejas como especificación",why:"Los incentivos compran logins, no uso. La gente va a cerrar el turno en la app por el dinero y va a seguir haciendo el trabajo real en papel, y la foto del inodoro seguirá en inglés. Medio crédito por tomar tan en serio el tiempo de la cuadrilla que lo pagas.",beat:"Ocho logins para el viernes. Las fotos son todas del mismo inodoro."}},
         {t:"Traducirla completa al español y relanzarla",out:{r:"mid",concept:"Quejas como especificación",why:"Necesario, no suficiente. El idioma es real, pero el problema es la foto-antes-de-checar-salida, y en español es igual de lenta. Relanzarías la misma pared con un letrero más bonito. Medio crédito por la parte que de todos modos había que hacer.",beat:"«Foto del inodoro.» Marta, en español: no."}}]}}},
 {npc:"chente",title:"La app en la guantera",late:"La tableta está en la guantera. La misma. Sé exactamente dónde está, y ese es el punto.",start:"a",nodes:{
  a:{say:"La tableta está en la guantera. Lleva dos semanas ahí. Vero quiere saber quién la ignora. ¿La neta? Todos. Aquí también hay una lista pegada, del de sistemas de antes. Foto de cada cuarto antes de checar salida. La misma idea, letra más vieja. Se lo dije a ella y te lo digo: si esa cosa es para vigilar dónde andamos, yo renuncio primero, y mis primos se van conmigo. Entonces. ¿Para qué es?",
     doc:"plan-viejo",
     codex:"El trabajo se cuenta; a la gente no se le vigila. Una herramienta puede registrar qué se hizo, dónde toca la cuadrilla y cuándo termina el turno, sin saber dónde estuvo nadie ni cuánto tiempo. Esa línea no es una opción de privacidad — es la diferencia entre una herramienta que la cuadrilla agarra y una que pierde a propósito, y decide si lo que construyas después se usa.",
     q:"¿Qué tiene derecho a saber la tableta?",
     ch:[{t:"Prender la ubicación para que Vero vea dónde anda cada cuadrilla",out:{r:"bad",concept:"Contar trabajo, no gente",why:"Acabas de construir al patrón que Vero dejó. La cuadrilla no va a discutir contigo; va a perder la tableta, y cada herramienta que venga después hereda la desconfianza. Rastrear le compra un mapa a la dueña y le cuesta las nueve personas que salen en él.",beat:"Aparece la tableta. En el canal."}},
         {t:"Dejarle solo lo de la cuadrilla: la lista en español, la ruta, el «listo» del turno",out:{r:"ok",concept:"Contar trabajo, no gente",why:"Cada pantalla que queda es una que la cuadrilla quiere abierta: lo que necesita el sitio, la dirección, el toque que termina la noche. Nada ahí reporta sobre una persona. Se cuenta el trabajo, no se vigila a la gente — y la tableta deja de ser algo que perder.",beat:"«Entonces es nuestra lista.» Sí. «No la de ella.» No la de ella. Chente, parejo: «La lista de faltantes. Lo que el cliente dice que faltó. Es la única lista que quiero en esa cosa. La nuestra.»"}},
         {t:"Hacer a Chente responsable de la app — su cuadrilla, su tableta",out:{r:"mid",concept:"Contar trabajo, no gente",why:"Persona correcta, orden equivocado. Encargarle una herramienta que su cuadrilla odia lo convierte en el que tiene que defenderla. Primero dale algo que valga la pena cuidar — una lista que sea de ellos — y entonces la responsabilidad es real. Medio crédito por escoger a quien debería tenerla.",beat:"Chente agarra la tableta. La vuelve a meter en la guantera. Con cuidado, esta vez."}},
         {t:"Que cada cuadrilla decida si la usa",out:{r:"mid",concept:"Contar trabajo, no gente",why:"Una herramienta que usa media empresa son dos empresas. Karla recibe horario de tres cuadrillas y papelitos de seis, los clientes reciben dos tipos de prueba, y nadie puede decir si funciona. Medio crédito por no imponerla antes de que se gane algo.",beat:"Dos cuadrillas dicen que sí. Una lo dice en serio. Karla ahora tiene tres sistemas."}}]}}},
 {npc:"karla",title:"Las cinco cuarenta",late:"Las 5:40 siguen llegando cada mañana. Ya no veo el reloj. El reloj me ve a mí.",start:"a",nodes:{
  a:{say:"Okay, tú, el de la app, son las 5:40 y esta es mi mañana: el niño de Marta está enfermo, la clínica cambió su hora, el mercado quiere una noche extra, y la cuadrilla de Chente ya está en la camioneta esperando destino. El horario es — míralo. Papelitos. En mi tablero. Tres chats de grupo. Quiero que la IA haga el horario y ya. O sea, que lo haga. Que lo mande. Yo voy a estar dormida.",
     codex:"Automatiza el rompecabezas; deja a la persona en la llamada. Un horario es matemáticas — contratos, horas, quién está libre — y una máquina lo arma más rápido. Un cambio de turno es una relación: quién le debe a quién, de quién está enfermo el niño, quién dice que sí si se lo pides bien. Que la herramienta haga la cuenta; que quien conoce a la cuadrilla haga la llamada.",
     q:"¿Qué hace la IA a las 5:40?",
     ch:[{t:"Que la IA arme el horario de la semana y se lo mande sola a las cuadrillas",out:{r:"bad",concept:"Automatizar el rompecabezas",why:"La cuenta va a salir bien y la semana va a salir mal. No puede saber de quién está enfermo el niño, así que manda a Marta a la clínica a las seis justo la mañana que no puede ir, y se lo dice directo, en una notificación, sin nadie que lo suavice.",beat:"Marta contesta. La respuesta no se puede imprimir."}},
         {t:"La IA hace el borrador con contratos y disponibilidad; Karla aprueba y hace las llamadas",next:"b"},
         {t:"Contratar a otra persona para los horarios",out:{r:"mid",concept:"Automatizar el rompecabezas",why:"Le compra a Karla unas horas y duplica la cantidad de gente adivinando. Los papelitos no se vuelven más listos con dos tableros; los cambios siguen viviendo en tres chats, y ahora hay dos personas a quién escribirle a las 5:40 en vez de una. Medio crédito por ver que se está ahogando.",beat:"Papelitos, dos tableros de ancho. Los chats de grupo suman un cuarto."}}]},
  b:{say:"Okay sí, borrador, aprobar, yo hago las llamadas — perfecto, me encanta. ¿Pero el borrador con QUÉ? La disponibilidad, o sea, ¿de dónde sale? Porque ahorita sale de que yo me acuerde de que el niño de Marta tiene una cosa los martes, y me acuerdo a las 5:40, después de que ya la mandé a la clínica.",
     codex:"El dato que nadie tiene a su cargo es el dato que siempre está mal. Un horario armado con disponibilidad vieja es un error bien formateado. Dales a quienes sí saben — los de la camioneta — un solo lugar para decir «el martes no» que les cueste casi nada, y que la herramienta lo lea. El canal que ya usan le gana al formulario que quisieras que usaran.",
     q:"¿De dónde sale la disponibilidad?",
     ch:[{t:"Un mensaje semanal de cada encargado, texto o nota de voz, y la herramienta lo lee",out:{r:"ok",concept:"Un dueño por dato",why:"El encargado ya sabe de quién tiene una cosa los martes, y ya le escribe a Karla. No estás agregando un paso — estás atrapando el mensaje que de todos modos iba a mandar y poniéndolo donde el borrador lo ve. Un dueño por dato, en el canal que él usa.",beat:"Chente manda una nota de voz: «Marta no martes.» Se procesa. Karla: «La hoja de ruta. La he estado mandando como foto de un papelito. Una FOTO.» Llora un poquito."}},
         {t:"Un formulario en la app que cada quien llena todos los días",out:{r:"mid",concept:"Un dueño por dato",why:"Datos correctos, si alguien lo llenara. La mitad de la cuadrilla no lee bien en ningún idioma, todos están cansados al checar salida, y un formulario diario es lo primero que una persona cansada se salta. Construiste una columna vacía y una regla sobre la columna. Medio crédito por quererlo de la fuente.",beat:"Semana uno: cuatro renglones. Semana dos: una columna vacía con un encabezado muy bonito."}},
         {t:"Que Karla siga adivinando, como ahora — casi siempre le atina",out:{r:"bad",concept:"Un dueño por dato",why:"Casi siempre le atina a las 5:40 porque lleva despierta desde las 5:10 arreglando lo que adivinó mal. «Casi siempre» es el costo que viniste a quitar, y ahora tiene una herramienta encima, armando borradores con toda confianza a partir de las mismas adivinanzas.",beat:"5:40. Otra vez."}},
         {t:"Que Vero ponga la disponibilidad de todos — es la dueña",out:{r:"mid",concept:"Un dueño por dato",why:"La dueña conoce los contratos; no sabe de quién está enfermo el niño. La disponibilidad vive con quien la tiene, y pasarla por Vero le agrega un paso, un retraso y una patrona a una pregunta que era sobre un martes. Medio crédito por querer un solo responsable.",beat:"Vero, sincera: «No sé quién está enfermo, inge. Sé quién es bueno.»"}}]}}},
 {npc:"chente",title:"El regreso",late:"La clínica volvió a llamar. El mismo cuarto. Lo mismo que no podemos demostrar.",start:"a",nodes:{
  a:{say:"Llamó la clínica. Que el cuarto de descanso no se hizo. Sí se hizo. Yo estaba — Marta hizo el cuarto, yo el piso. No hay prueba de nada, así que Vero nos manda de regreso hoy en la noche, gratis, otra vez. Segunda vez este mes. Mira — yo sí quiero lo de la cámara. No LO de la cámara. No lo del canal. Algo que diga que estuvimos y que quedó limpio. ¿Me explico?",
     codex:"La prueba del trabajo protege a la cuadrilla tanto como al cliente — si la foto es de la cuadrilla y el cliente la puede ver, es un recibo. Si es del patrón y él la revisa, es vigilancia, se llame como se llame. La misma cámara, la misma foto; quién la tiene y quién la mira decide si la gente la usa o la entierra.",
     q:"¿Cómo se ve la prueba?",
     ch:[{t:"Fotos de cada cuarto, con hora, revisadas por Vero cada mañana",out:{r:"bad",concept:"Prueba, no vigilancia",why:"Eso es la app del canal con otro nombre. Cada cuarto, cada noche, revisado por la dueña, es un registro de dónde estuvo cada quien y cuándo — justo por lo que Chente dijo que renunciaba. Resolvería la queja de la clínica y perdería a la cuadrilla.",beat:"La cara de Chente hace lo que hizo en el canal."}},
         {t:"La cuadrilla fotografía los tres cuartos de queja; van al cliente, la oficina no las mira",out:{r:"ok",concept:"Prueba, no vigilancia",why:"La foto es de la cuadrilla y va al cliente, así que es un recibo, no una boleta de calificaciones. Tres cuartos, no treinta, así que cuesta un minuto. Y nadie en la oficina la revisa a menos que llame un cliente — o sea que la cámara apunta al trabajo, nunca a la gente.",beat:"La siguiente queja de la clínica llega con su propia foto. Cuarto de descanso. Limpio. La clínica se disculpa. Su lista de faltantes, resulta, la mandaron por mensaje directo. Al perro."}},
         {t:"Sin fotos — confiar en la cuadrilla",out:{r:"mid",concept:"Prueba, no vigilancia",why:"Vero sí confía en ellos; la clínica no, y la clínica es la que decide si hay vuelta gratis. La confianza sin recibo cuesta una noche cada vez que alguien duda. Medio crédito por negarte a apuntarle una cámara a tu propia gente.",beat:"La cuadrilla regresa hoy en la noche. Gratis. Otra vez. El cuarto de descanso está, otra vez, limpio."}},
         {t:"Que Chente revise cada sitio después de cada cuadrilla, antes de checar salida",out:{r:"mid",concept:"Prueba, no vigilancia",why:"Resolvería la discusión y le quitaría a Chente el trapeador la mitad de cada noche. Un inspector es una segunda vuelta metida dentro de la primera. Medio crédito por querer que una persona dé el visto bueno — nada más que no esta persona, en cada sitio.",beat:"Chente, sin limpiar: «Entonces ahora ando dando vueltas viendo pisos.» No lo disfruta."}}]}}},
 {npc:"vero",title:"Nueve, y luego veinte",late:"Todavía quiero saber si sirvió. Esa pregunta no trae fecha.",start:"a",nodes:{
  a:{say:"Un mes, inge. La cuadrilla de Chente lleva un mes en la app. Las camisas que hizo Xochi llegaron la semana pasada — nueve de nueve las traen puestas, las conté. La app, por lo que yo veo: uno de nueve. Él. Entonces esto es lo que quiero. Sacarla a las nueve personas, y luego cotizar los doce sitios. Veinte personas. Pero antes — ¿sirvió? Dime cómo siquiera se sabe.",
     codex:"Mide la adopción, no los logins. Un login es una puerta; un hábito es alguien cruzándola cada turno sin que se lo recuerden. El número que dice que un despliegue funcionó es el que el negocio ya siente — turnos cerrados sin una llamada, segundas vueltas que dejaron de pasar — en las unidades de la dueña, contra el mes pasado. Todo lo demás es una captura de pantalla.",
     q:"¿Cómo le dices si sirvió?",
     ch:[{t:"Todos entraron a la app — eso es adopción",out:{r:"bad",concept:"Adopción, no logins",why:"Un login es una puerta, no un hábito. Ocho personas la abrieron porque Karla se los pidió; una de ellas cierra cada turno ahí. Reporta la puerta y vas a sacar la app a nueve personas con la fuerza de una.",beat:"Ocho logins, un usuario. Se llama Chente."}},
         {t:"Contar turnos cerrados sin llamar a Karla, y vueltas gratis este mes contra el mes pasado",next:"b"},
         {t:"Preguntarle a la cuadrilla si les gusta",out:{r:"mid",concept:"Adopción, no logins",why:"Le van a decir que sí a Vero. Ella firma los cheques, limpia junto a ellos, y nadie quiere ser el que odió su app. Lo que dicen es cariño; lo que hacen al checar salida es dato. Medio crédito por preguntarle a los usuarios siquiera.",beat:"Nueve síes. Vero, contenta. Chente mira el piso."}},
         {t:"Sacarla a los nueve y ver qué pasa",out:{r:"mid",concept:"Adopción, no logins",why:"Un despliegue no es una medición. Te enterarías de si nueve personas la usan enterándote — después de que Chente los capacitó, después de que bajaron los papelitos, cuando regresar ya sale caro. Medio crédito por querer una respuesta real en vez de una encuesta.",beat:"Karla: «¿Y cuál es el número que estoy buscando?» Todavía no hay."}}]},
  b:{say:"Okay. La cuadrilla de Chente: diecinueve de veintidós turnos cerrados en la app. Vueltas gratis, tres el mes pasado, una este mes. Llamadas de las 5:40 de esa cuadrilla a Karla — cero. Cero, inge. Entonces es un sí, ¿no? Las nueve, y luego la cotización. El del autoservicio no va a esperar a que yo me sienta lista.",
     codex:"Una revisión de piloto dice una de tres cosas: parar, seguir o corregir. Y «seguir» nunca significa todos — significa el siguiente grupo, capacitado por quienes lo acaban de aprender, medido igual. El aprendizaje salió de una cuadrilla y un capacitador; escala a la velocidad a la que ese capacitador se puede mover, o los números que te ganaste dejan de ser ciertos.",
     q:"Diecinueve de veintidós. ¿Cuál es la decisión?",
     ch:[{t:"Seguir: dos cuadrillas más, Chente capacita, los mismos tres números, y luego cotizar",out:{r:"ok",concept:"Revisión del piloto",why:"El piloto movió tres números para el lado correcto, así que es un seguir — pero un seguir a las dos cuadrillas que siguen, con el capacitador que sabe por qué funcionó y la misma medida para demostrarlo otra vez. Así nueve se vuelve veinte sin perder lo único que lo hizo funcionar.",beat:"Vero: «Tres a una. Una vuelta gratis es una noche que pago dos veces. Ese es el número que hubiera querido hace un año.» Escribe 3→1 en el pizarrón. Debajo: «Chente.»"}},
         {t:"Las nueve de una vez — vamos atrasados y la cotización es el viernes",out:{r:"bad",concept:"Revisión del piloto",why:"El aprendizaje salió de una cuadrilla y un capacitador. Nueve de golpe no tiene capacitador — tiene a Chente, en tres camionetas, en una noche, con una sola voz. Las cuadrillas que reciben la mitad de él reciben la app a la antigua, y el número que acabas de ganar regresa a ocho logins.",beat:"Chente capacita a tres cuadrillas en una noche. Tiene una sola voz. Se le va."}},
         {t:"Parar — diecinueve de veintidós no es veintidós",out:{r:"mid",concept:"Revisión del piloto",why:"Tres turnos cerrados en papel son un proceso que hay que mirar, no una razón para matar lo que bajó las segundas vueltas a un tercio y calló las 5:40. Un piloto que movió tres números para el lado correcto es un seguir. Medio crédito por leer el número en vez del ánimo.",beat:"Vero: «¿Entonces regresamos a los papelitos?» Karla, desde el otro cuarto: «No.»"}},
         {t:"Brincarse directo a la cotización — los números están buenos",out:{r:"mid",concept:"Revisión del piloto",why:"Prueba para tres personas, cotización para veinte. Los números son reales para la cuadrilla de Chente e hipotéticos para todos los demás, y un contrato con fecha de inicio no va a esperar a que lo averigües. Medio crédito por confiar en la medición — nomás no hasta tan lejos.",beat:"Karla abre el formato de la cotización. Doce cuadritos. Vero mira a la única cuadrilla que ha usado la app."}}]}}},
 {npc:"vero",title:"La cotización",late:"El formato de la cotización sigue abierto en la pantalla de Karla. Doce cuadritos. Nadie ha escrito 'estándar' en ninguno.",start:"a",nodes:{
  a:{say:"El formato pide precio por sitio, inge, y el precio sale de un recorrido — veo los pisos, los baños, la grasa, y escribo lo que va a costar. Doce sitios. Es miércoles. La cotización se entrega el viernes. Karla dice que cotice con los planos que mandaron, que de todos modos son la misma tienda. Karla no está mal en lo de la tienda. Nunca ha tenido que limpiar una.",
     codex:"La herramienta redacta el alcance y los números; la dueña recorre por lo menos un sitio y firma la línea del alcance. Una cotización es una promesa sobre trabajo que nadie ha visto todavía, y un plano no muestra cómo está un piso. Usa el borrador para cubrir los doce; usa el recorrido para encontrar en qué se equivocó el borrador, y corrige los doce con eso.",
     q:"Doce sitios para el viernes. ¿Cómo se escribe la cotización?",
     ch:[{t:"Cotizar los doce con los planos — son la misma tienda",out:{r:"bad",concept:"Firmar el alcance",why:"Un plano no muestra la trampa de grasa. Doce precios de doce dibujos son doce promesas sobre cuartos que nadie ha pisado, y el que salga mal va a estar mal un año, de noche, gratis. El dibujo es donde empieza el presupuesto, no donde termina.",beat:"El sitio 7 tiene cocina. El plano decía «bodega»."}},
         {t:"Redactar los doce con los planos; Vero recorre dos sitios, el más grande y el más raro",out:{r:"ok",concept:"Firmar el alcance",why:"El borrador hace lo que un borrador es: doce alcances, doce números, para el jueves. El recorrido hace lo que solo Vero puede: encuentra en qué mintió el dibujo, y como los sitios se parecen, una mentira encontrada son doce corregidas. La firma va sobre lo que ella vio.",beat:"«La línea del alcance, inge. ‹Ventanas por dentro, no por fuera.› Cada pleito que tuve con un cliente vivió en esa línea.» Recorre el sitio 7 y agrega «cocina» en los doce, a pluma."}},
         {t:"No cotizar — no se puede cotizar lo que no se ha recorrido",out:{r:"mid",concept:"Firmar el alcance",why:"Cierto, y la línea abre una sola vez. Negarte a prometer lo que no has visto es el instinto correcto; negarte al contrato completo porque no puedes verlo todo para el viernes es el instinto sin plan. Medio crédito por saber qué es una cotización.",beat:"Vero cierra el formato. Karla lo vuelve a abrir. Ninguna dice nada."}},
         {t:"Pedirle al del autoservicio que describa cada sitio",out:{r:"mid",concept:"Firmar el alcance",why:"Barato y vale la pena — y la respuesta la va a dar alguien que tampoco ha limpiado una. La descripción de un cliente es un plano en palabras; llena los cuadritos y deja fuera la trampa de grasa igual. Medio crédito por preguntar antes de adivinar.",beat:"La respuesta: «Tienda estándar.» El sitio 7 tiene cocina."}}]}}},
 {npc:"chente",title:"El teléfono de Marta",late:"Marta me sigue dando papel. Su letra es mejor que la app. Ese nunca fue el pleito.",start:"a",nodes:{
  a:{say:"Semana dos desde que salió la app. Marta — la mejor de esta empresa, nadie se le acerca — cierra sus turnos en papel. Me lo da, yo lo tecleo. Dos minutos. Su teléfono es para que le llame su hija, y ya, para eso es. Karla dice que todos tienen que estar en la app. Vero todavía no sabe. Entonces te pregunto a ti antes de que alguien lo haga regla.",
     codex:"La adopción nunca es del cien por ciento, y el último pedacito suele ser tu mejor gente. Una persona en papel con un cuate que lo teclea es un proceso, no una falla — siempre que el número entre una vez, a tiempo y con nombre. Anota la excepción donde vive el proceso, y deja de ser un secreto.",
     q:"¿Qué pasa con el papel de Marta?",
     ch:[{t:"Obligatorio — todos en la app, nada de papel",out:{r:"bad",concept:"La excepción honesta",why:"Perderías a Marta por un formulario. La mejor de la empresa se iría, o se quedaría sin cerrar nada, y de cualquier forma el número que hizo lucir al piloto — los turnos que sí se cierran — sería la primera víctima de la regla sobre cerrar turnos.",beat:"El papel de Marta está más limpio que la app. Nadie lo dice. Todos lo saben."}},
         {t:"El papel de Marta más Chente tecleándolo, escrito en el proceso como la excepción que es",out:{r:"ok",concept:"La excepción honesta",why:"El número entra una vez, a tiempo y con nombre — ese es todo el requisito. Los dos minutos de Chente son el costo, y está escrito, así que el siguiente encargado y el siguiente patrón saben que es regla, no favor. Un proceso con una excepción honesta le gana a uno con una escondida.",beat:"«Entonces sí se puede.» Está en el mapa. «…En el mapa.» Le gusta eso."}},
         {t:"Comprarle a Marta un teléfono de trabajo",out:{r:"mid",concept:"La excepción honesta",why:"Una segunda cosa que perder, y la objeción nunca fue el teléfono. Marta no le saca la vuelta a la app porque su teléfono esté ocupado; le saca la vuelta porque el papel es más rápido en sus manos y la app no. Medio crédito por gastar en la persona y no en una regla.",beat:"El teléfono de trabajo vive en la guantera. Tiene una batería excelente."}},
         {t:"Que su hija se lo configure una vez y Marta apriete un solo botón",out:{r:"mid",concept:"La excepción honesta",why:"Podría funcionar — un botón está cerca del papel. Pero mete a una niña de nueve años en tu plan de despliegue, y la primera vez que el botón se mueva, el plan es llamarle a una niña en horario de escuela. Medio crédito por reducirlo a un toque; quédate con el cuate.",beat:"La hija lo configura en cuatro minutos. El botón se mueve en la siguiente actualización."}}]}}},
 {npc:"vero",title:"La camioneta",late:"La camioneta está estacionada, inge. La pregunta del lunes no sabe qué día es.",start:"a",nodes:{
  a:{say:"Sábado. La cotización se fue el viernes, con cocina y todo. El lunes tengo que hablar con las cuadrillas y no sé qué decirles. Y la otra cosa, inge, la que solo digo en la camioneta: digamos que los doce sitios dicen que sí. Digamos que ya no soy yo la que trae el teléfono. ¿Qué evita que esto se vuelva lo que dejé?",
     codex:"La entrega es la revisión del piloto: qué se midió, qué se quedó, quién capacita a quién después — y la regla sobre la gente, escrita donde el siguiente patrón la tenga que leer. Un despliegue que vive en la cabeza de una persona es un despliegue que se acaba cuando esa persona está ocupada. Escríbelo para que sobreviva a que la dueña esté en otro lado.",
     q:"¿Qué les llega a las cuadrillas el lunes?",
     ch:[{t:"Decirles a las cuadrillas que la app es obligatoria, en toda la empresa, desde el lunes",out:{r:"bad",concept:"La entrega",why:"Con esa frase empezó el despliegue anterior, con letra más vieja. Obligatoria dice que la herramienta es para la empresa y no para la cuadrilla, y la cuadrilla ya sabe qué hacer con una herramienta así. Está en la guantera.",beat:"Guantera."}},
         {t:"Escribir la revisión del piloto: tres números, la excepción, el orden, la regla de rastreo",next:"b"},
         {t:"Esperar el resultado de la cotización — para qué planear doce sitios que quizá no lleguen",out:{r:"mid",concept:"La entrega",why:"Un despliegue que espera a un cliente nunca empieza. Nueve personas van a usar o no usar la app el lunes, conteste o no conteste el del autoservicio, y las dos cuadrillas que siguen iban a seguir de todos modos. Medio crédito por no planear contra un quizás.",beat:"El resultado llega en tres semanas. Las cuadrillas llevan preguntando por el lunes desde el lunes."}}]},
  b:{say:"Tres números, el orden, Marta en el mapa, y la regla — sin rastreo, nunca. Bien. La firmo. ¿Pero dónde vive, inge? Porque tengo nueve personas que no abren apps, una encargada de turnos que todo lo tiene en papelitos, y los del autoservicio me van a mandar un gerente con tablero. ¿Dónde la pongo para que siga siendo cierta cuando yo no esté?",
     codex:"Las reglas para la gente se escriben para el día en que cambia el patrón. Una promesa que vive en la palabra de una persona se cumple mientras esa persona está en el cuarto; una promesa en papel, en el idioma que la cuadrilla lee, firmada y clavada donde trabajan, es una que pueden señalar. Dónde vive la regla decide quién la puede hacer valer.",
     q:"¿Dónde vive la regla?",
     ch:[{t:"Una hoja en la camioneta, español primero: números, orden, regla de rastreo, firma de Vero",out:{r:"ok",concept:"Dónde vive la regla",why:"Está donde trabaja la cuadrilla, en el idioma que leen primero, con el nombre de la dueña — así la regla es de ellos, no de una configuración que alguien puede cambiar. El siguiente gerente, la siguiente app, el siguiente patrón la lee donde las cuadrillas lo ven leerla.",beat:"Chente la lee dos veces y la clava arriba del tablero, donde estaban los papelitos. «Ya, compañero.» No lo retira. Pelusa se le sienta encima."}},
         {t:"En la configuración de la app — rastreo apagado, con candado",out:{r:"mid",concept:"Dónde vive la regla",why:"Apagarlo está bien; esconder la regla adentro de un menú de configuración no. Nadie lee la configuración, y el siguiente administrador la puede leer y cambiar sin que nadie en la camioneta se entere. Medio crédito por hacerla cierta en el software — ahora hazla visible para la gente.",beat:"Karla: «¿Cuál configuración?» Chente: «¿Qué configuración?» Ese es todo el problema."}},
         {t:"Que Vero nomás se los diga — su palabra vale",out:{r:"bad",concept:"Dónde vive la regla",why:"La palabra de Vero vale. La palabra de Vero no está en la camioneta la noche que ella no está, y la regla sobre la gente existe justo para la noche que ella no está. Una promesa que nadie escribió es una que el siguiente patrón nunca hizo.",beat:"Nadie lo dice en voz alta. Vero mira la cotización."}}]}}},
 /* ---- Nolasco Tax & Notario (48-55) ---- */
 {npc:"nolasco",title:"El letrero",late:"El letrero no ha cambiado, colega. Es lo único en este despacho que nunca va a cambiar.",start:"a",nodes:{
  a:{say:"Vero te mandó con un sobre. Chelo, Tacho y Licha mandaron lo suyo de palabra; yo lo apunté. Yo todo lo apunto. Siéntate, colega — con cuidado con Timbre, que se sienta justo donde iría el timbre. Por esa escalera suben cuarenta preguntas al día: horarios, dónde estacionarse, qué traigo, si hago divorcios. Ninguna es mi trabajo. Quiero un asistente en la puerta. Primero lee el letrero: NOTARY PUBLIC — NO SOY NOTARIO PÚBLICO. Luego dime de dónde saca lo que contesta.",
     codex:"Un asistente que contesta con lo que sabe está contestando con la versión del oficio que tiene todo el internet: cada año, cada estado, todo revuelto y muy seguro de sí. Un despacho es un solo lugar con sus propias reglas en papel. Aterriza al asistente en las hojas escritas del propio despacho, que diga de dónde salió la respuesta, y que diga «eso no lo tengo» para todo lo demás. Una respuesta sin una hoja detrás no es una respuesta.",
     q:"El asistente de la puerta — ¿de dónde saca lo que contesta?",
     ch:[{t:"Que conteste preguntas generales de impuestos con lo que ya sabe",out:{r:"bad",concept:"Aterrizar la respuesta",why:"Sabe la ley de impuestos de todo el internet — cada año, cada estado, al mismo tiempo — y nada de este despacho. Nadie puede saber de qué año está citando hasta que un cliente ya actuó con eso, y el chat lleva el nombre del despacho.",beat:"Explica una deducción que venció hace años. Con toda seguridad. En los dos idiomas."}},
         {t:"Solo sus hojas — horarios, qué traer, qué hace y qué no — y «eso no lo tengo» para lo demás",next:"b"},
         {t:"Hacerlo un conmutador — marque uno para horarios, dos para estacionamiento",out:{r:"mid",concept:"Aterrizar la respuesta",why:"Nada de lo que dice un conmutador está mal, porque nunca contesta lo que la persona de verdad preguntó. Seguro, odiado, y las cuarenta preguntas siguen subiendo la escalera con palabras que el conmutador no tiene. Medio crédito por no meterlo en problemas.",beat:"Bere marca dos. Luego cero. Luego viene y te pregunta a ti."}},
         {t:"Que a todo conteste «consulte a un profesional»",out:{r:"mid",concept:"Aterrizar la respuesta",why:"Cierto e inútil. La gente subió la escalera para preguntarle al despacho de un profesional a qué hora abre; una pared con saludo la manda de regreso sin nada. Negarse a todo no es lo mismo que negarse a lo correcto. Medio crédito por nunca mentir.",beat:"La primera clienta pregunta el horario. Le dice que consulte a un profesional. Está parada en la puerta del profesional."}}]},
  b:{say:"Ahora la única pregunta que me importa. Alguien escribe: ¿Es usted notario? En México un notario público es un abogado de muchos años; aquí un notary es un sello y una cuota. La misma palabra. He visto familias pagarle a un señor con mi mismo título por consejos que nunca tuvo permiso de dar. Por eso el letrero está en dos idiomas. ¿Qué contesta el asistente?",
     codex:"Hay preguntas cuya respuesta correcta es una advertencia. La verdad literal — «sí, notary» — y el silencio seguro — «no», fin del chat — dejan a la persona peor que el letrero. Cuando una palabra significa dos cosas para dos personas, el asistente dice el letrero completo, en los dos idiomas, cada vez, y pasa a la persona con un humano, por su nombre. Su única ventaja sobre una persona cansada es que nunca se cansa de decirlo.",
     q:"«¿Es usted notario?» — ¿qué contesta?",
     ch:[{t:"El letrero tal cual, en los dos idiomas — y luego «Bere le ayuda con lo que necesite»",out:{r:"ok",concept:"La respuesta que advierte",why:"La advertencia es la respuesta. En los dos idiomas, cada vez, es lo único que una máquina hace mejor que una persona a las cuatro de la tarde, y el pase con nombre convierte una negativa en una puerta. Nadie se va creyendo que lo corrieron, y nadie se va creyendo que él es abogado.",beat:"Lo lee tres veces. «Bien. Ahora lo dice más seguido que yo. Mi sello es un reconocimiento de firma: dice que firmaste frente a mí. No dice que el papel sea cierto. Media calle cree que sí.» Del otro lado de la ciudad, alguien le mandó mensaje a Frederick para preguntarle si es notario público. No lo es. Ni siquiera es notary."}},
         {t:"«Sí» — técnicamente, sí es notary",out:{r:"bad",concept:"La respuesta que advierte",why:"Técnicamente cierto y exactamente la confusión que el letrero existe para matar. La persona que pregunta se refiere al notario mexicano, y el asistente acaba de confirmar que él lo es. Esa es la respuesta que las familias ya han pagado antes, y esta vez la dijo el despacho.",beat:"Nolasco se quita los lentes. Los dobla. Se queda un buen rato sin decir nada."}},
         {t:"«No» — y cerrar el chat",out:{r:"mid",concept:"La respuesta que advierte",why:"Cierto, y deja a la persona en la escalera creyendo que la rechazaron. Venía por una traducción, un sello o una declaración; el asistente contestó una palabra y le cerró la puerta a la necesidad. Medio crédito por no mentir.",beat:"El cliente se va. El martes Bere se entera de que fue con el señor de la esquina que tiene el mismo título."}}]}}},
 {npc:"bere",title:"La caja de zapatos",late:"Llegó otra caja de zapatos. Esta trae foto de un gato. Sin 1099.",start:"a",nodes:{
  a:{say:"Hola, inge. Vero dijo que así te dicen, así que así te llamas — así funcionan los nombres en esta calle. Mira esto. Una clienta trajo sus impuestos en una caja de zapatos: dos W-2, un 1099, recibos en una bolsa de pan, el acta de nacimiento de su hijo y una foto de un perro. Cada año la reviso a mano y le hago las mismas doce preguntas a gente que le tiene miedo a los formularios. Quiero que se lea y salga una lista. Con cuidado.",
     codex:"La recepción de documentos es una lista de verificación, no una memoria. El trabajo es comparar lo que la persona trajo contra lo que el despacho dice que necesita, y reportar qué hay y qué falta — nada más. Y antes de que cualquier modelo lea una hoja, los números personales se tapan, porque un número de seguro social pegado en una herramienta que el despacho no controla es una filtración con hora y fecha, por muy buen resumen que haya salido.",
     q:"¿Cómo se convierte la caja en una lista?",
     ch:[{t:"Tomarle foto a todo con una app de IA del celular y pedirle un resumen",out:{r:"bad",concept:"Lista, no memoria",why:"El resumen saldría bien. También acaba de mandar un número de seguro social, un acta de nacimiento y un número de cuenta a un servicio con el que el despacho no tiene ningún convenio. Eso es una filtración con hora y fecha, y la caja era de alguien que se la confió a Bere.",beat:"En algún lado, un oficial de cumplimiento vuelve a despertarse. El mismo."}},
         {t:"La herramienta del despacho, números tapados, y qué hay y qué falta contra la hoja de Nolasco",out:{r:"ok",concept:"Lista, no memoria",why:"El modelo ve una hoja con los números tachados y una lista de lo que debería haber. Hace la comparación que Bere hace al final de un día largo, y la hace igual a las nueve que a las cinco. Nada sale del despacho; lo único que sale es la lista.",beat:"«Falta: 1099 del segundo trabajo. Presente: un perro.» Bere lo lee dos veces. «Eso es la recepción. Doce preguntas y una lista. Llevo seis años haciéndola en la cabeza.»"}},
         {t:"Que Bere lo siga capturando a mano — funciona",out:{r:"mid",concept:"Lista, no memoria",why:"Sí funciona; lleva seis años funcionando. Pero seis años de cargar doce preguntas en la cabeza para gente asustada es justo la forma de lo que vale la pena quitarle a una persona, y «funciona» es la frase que mantiene cansado un trabajo cansado. Medio crédito por no romper nada.",beat:"Bere: «Seis años, inge. Ya sé que funciona. Por eso te estoy preguntando.»"}},
         {t:"Pasarle la caja a Nolasco — él sabe qué lleva una declaración",out:{r:"mid",concept:"Lista, no memoria",why:"Sí sabe, y cada minuto que pasa sacando recibos de una bolsa de pan es un minuto que no pasa en la declaración que paga el despacho. Sus horas son el margen. Resolviste la recepción gastando lo más caro que hay en el edificio. Medio crédito por saber quién tiene la razón.",beat:"Nolasco mira la foto del perro un buen rato. «Colega. Yo cobro por hora.»"}}]}}},
 {npc:"nolasco",title:"El sobrino",late:"La gente sigue teniendo sobrinos. La pregunta no se puso más fácil; se puso más sobrinos.",start:"a",nodes:{
  a:{say:"Siéntate, colega. Ayer le preguntaron al asistente: «¿Puedo declarar a mi sobrino que vive conmigo?» Contestó: «Sí, si vivió con usted más de seis meses.» Lo revisé. Estaba bien. Eso es peor. Una vez que acierta, la siguiente persona le cree, y la siguiente pregunta es un primo, una madre del otro lado, un niño con dos casas. Esas las contesto yo. Nada más yo.",
     codex:"Negarse es un diseño, no un humor. Un asistente que a veces contesta bien las preguntas de consejo ya le enseñó a la gente a preguntarle, y el día que se equivoque no hay nadie responsable ni registro de que la pregunta se hizo. Toda pregunta que pide una decisión — «¿puedo?», «¿debo?», «can I» — va con la persona autorizada para contestarla, con la pregunta escrita y adjunta. La respuesta con suerte es la más cara que hay.",
     q:"La respuesta estaba bien. ¿Qué haces con ella?",
     ch:[{t:"Estaba bien — se queda",out:{r:"bad",concept:"Negarse por diseño",why:"Acertar esta vez es la clase más peligrosa de error. No prueba nada sobre la siguiente pregunta y le enseña a los clientes que aquí es donde se pregunta. El día que se equivoque, una familia presenta una declaración que no puede defender y el chat lleva el nombre del despacho.",beat:"El siguiente sobrino es un primo. La respuesta es la misma. La auditoría no."}},
         {t:"«¿Puedo?», «¿debo?», «can I» — todo eso va con Nolasco, con la pregunta escrita",out:{r:"ok",concept:"Negarse por diseño",why:"La forma de la pregunta es el disparador, no el tema. Quien pidió una decisión llega con la persona que tiene permiso de tomarla, y Nolasco recibe la pregunta con sus propias palabras y no un resumen. A nadie se le niega nada; se le pasa, y la pregunta queda en papel.",beat:"«La carta de compromiso dice qué voy a hacer por el cliente y qué no. El asistente también necesita una. Más corta.» La redacta. Cuatro renglones. La enmarca."}},
         {t:"Agregar un aviso — «esto no es asesoría fiscal»",out:{r:"mid",concept:"Negarse por diseño",why:"Un aviso debajo de una respuesta segura es cobertura, no franqueza. La persona igual lee el sí y actúa con el sí; la letra chiquita protege al despacho en teoría y al cliente en nada. Medio crédito por notar que el despacho estaba expuesto.",beat:"El aviso queda debajo de la respuesta. La respuesta queda arriba, donde la gente lee."}},
         {t:"Rechazar todo lo que traiga la palabra «sobrino»",out:{r:"mid",concept:"Negarse por diseño",why:"Prohibir palabras atrapa lo que no debía y deja pasar lo que sí. La pregunta de consejo sobre un primo pasa sin problema; la pregunta de agenda sobre un sobrino se rechaza. Prohibiste una palabra cuando el problema era un tipo de pregunta. Medio crédito por al menos intentar negarse.",beat:"«¿Puedo traer a mi sobrino a la cita?» Rechazada."}}]}}},
 {npc:"bere",title:"La pregunta del ITIN",late:"Alguien pregunta lo del ITIN cada semana, inge. Cada semana sin falta.",start:"a",nodes:{
  a:{say:"Una clienta le preguntó: «¿Saco el ITIN o mejor espero mis papeles?» Son dos preguntas en una, inge. Qué es un ITIN — eso está en la hoja del licenciado, en dos idiomas. Qué debe hacer con sus papeles — nadie en este despacho se lo va a decir desde una pantalla. Quiero que explique, se detenga y me la pase, para que se sienta como una mano y no como una puerta.",
     codex:"Explica la cosa; nunca la decisión. Una pregunta con una mitad que se puede contestar y una mitad de consejo se parte — ni se rechaza entera ni se contesta entera. El asistente dice lo que dice la hoja, aclara sin rodeos con cuál mitad no puede ayudar, y pasa a la persona con un humano, por su nombre, llevando lo que ya se dijo para que nadie cuente su historia dos veces antes de llegar con quien sí puede ayudar.",
     q:"Dos preguntas en un mensaje. ¿Qué hace el asistente?",
     ch:[{t:"«Saque el ITIN — es más rápido»",out:{r:"bad",concept:"Explicar, nunca decidir",why:"Eso es un consejo, de una máquina, sobre el único tema al que este despacho le dice que no con más fuerza. Si declarar con ITIN toca los papeles de una persona, a su familia y al resto de su vida, y el asistente lo resolvió en cinco palabras porque sonaban útiles.",beat:"Esta vez Nolasco no se quita los lentes. Cierra la laptop."}},
         {t:"Explicar el ITIN con la hoja, decir que con lo demás no puede, y pasarla con Bere con el chat",next:"b"},
         {t:"Rechazar la pregunta completa — trae la palabra papeles",out:{r:"mid",concept:"Explicar, nunca decidir",why:"La segunda mitad merecía la negativa; la primera estaba en la hoja. Rechazar las dos la manda a su casa sin lo único que el despacho le podía dar gratis, y se lo va a preguntar a la siguiente persona que se encuentre. Medio crédito por la cautela.",beat:"Le pregunta a su prima qué es un ITIN. Su prima está mal."}}]},
  b:{say:"Bueno. Ahora las palabras. Ella lee esto en su celular, sola, de noche, con miedo a un formulario. Diga lo que diga, tiene que sonar a que alguien me la pasó a propósito, no a que alguien le cerró la ventanilla en la cara. Y tiene que ser cierto — no amable en vez de cierto. Escríbeme la respuesta, inge.",
     codex:"Confirma lo que puedes, nombra lo que no, da el camino. Esas palabras son el producto de confianza: la persona se va con una cosa cierta, sabe exactamente por qué la segunda necesita a un humano, y sabe quién es ese humano y que ya tiene su historia. Dilo de modo que sea verdad, en un párrafo sencillo, en el idioma en que ella escribió.",
     q:"¿Qué le dice el asistente?",
     ch:[{t:"«El ITIN es un número de impuestos. Si sacarlo, lo decide el Lic. Nolasco. Bere le agenda.»",out:{r:"ok",concept:"Las palabras del pase",why:"Tres movimientos en tres frases: lo cierto de la hoja, el límite honesto de lo que una máquina puede decir, y un humano con nombre que ya tiene su historia — «ya le pasé lo que usted me contó». Se va con una respuesta y una cita, y nunca tiene que repetirse.",beat:"Ella escribe gracias — al asistente. Bere: «A él le dan más las gracias que a mí. Y media calle dice el ITIN como si fuera una persona. Es un número. Ahora la hoja lo dice en dos idiomas.»"}},
         {t:"«No puedo contestar eso»",out:{r:"mid",concept:"Las palabras del pase",why:"No está mal, y no le sirve a nadie. La primera mitad se podía contestar, la segunda tenía a una persona esperándola, y el asistente no dijo ninguna. Una negativa sin camino es una pared con saludo. Medio crédito por no dar consejos.",beat:"Ella vuelve a escribir la pregunta, más despacio, como si no la hubiera oído bien."}},
         {t:"«Debería preguntarle a un abogado»",out:{r:"mid",concept:"Las palabras del pase",why:"Buen instinto, puerta equivocada. Hay una persona autorizada para contestarle a unos pasos de la pantalla, y el asistente la mandó a la calle a buscar una. Un pase nombra al humano que tiene, no a una profesión en general. Medio crédito por negarse a decidir.",beat:"Bere: «Un abogado. Inge, ella vino aquí. Eso lo contesta él, y está a cuatro metros de la pantalla.»"}},
         {t:"Mandarle la página del gobierno sobre el ITIN",out:{r:"bad",concept:"Las palabras del pase",why:"Un enlace es un encogerse de hombros. Cuarenta páginas de inglés federal, mandadas a una persona que preguntó en español de noche, es el asistente pasándola con nadie y llamándole ayuda. Tenía una pregunta concreta y un despacho que podía contestarla.",beat:"Cuarenta páginas, en inglés. Ella la cierra."}}]}}},
 {npc:"nolasco",title:"Las cuatro cartas",late:"La carpeta está donde estaba. Yo no muevo carpetas. Les agrego.",start:"a",nodes:{
  a:{say:"Siéntate, colega. Esta carpeta eres tú. Chelo, Tacho, Licha, Vero — lo que dijo cada uno, con mi letra, el día que lo dijo. Tu propio expediente dice ingeniero de prompts, de soluciones. Las palabras son nuevas; el oficio no: tú escribes las instrucciones que la cosa no se deja quitar. Y esta quinta hoja — archivada antes de que llegaras, con una letra más vieja. He leído los dos expedientes dos veces. Dime: ¿para qué sirve un reporte?",
     codex:"El registro es el entregable. Un reporte que solo enlista aciertos es un folleto; un reporte que dice qué decidiste, por qué y qué harías distinto es un portafolio, porque es el único documento que demuestra que sabes distinguir. La revisión honesta del tamaño de un proyecto es un buen hábito. Del tamaño de una carrera, es la reputación entera.",
     q:"¿Para qué sirve un reporte?",
     ch:[{t:"«Para demostrar que tuve razón»",out:{r:"bad",concept:"El registro honesto",why:"Un reporte sin errores no es un registro de criterio; es un registro de lo que quisieras que la gente pensara. Todo el que lo lee lo sabe, y por eso deja de leerlo. La quinta hoja de la carpeta es ese reporte.",beat:"Desliza la quinta hoja por el escritorio. Cada entrada es la respuesta impresionante. «Ni una sola vez apuntó un no.»"}},
         {t:"«Para mostrar qué decidí, por qué, y qué cambiaría»",out:{r:"ok",concept:"El registro honesto",why:"Eso es lo único que un reporte puede decir que el lector no saca de la factura. Las decisiones con razones se pueden revisar; los cambios que harías demuestran que ya las revisaste tú primero. Es el mismo documento que guarda un notario: qué pasó, frente a quién, firmado.",beat:"«Cuando una declaración no está lista, pedimos prórroga. No entregamos una adivinanza. Tu reporte tiene prórrogas. Bien.» «Con permiso.» Lo archiva junto a las cuatro cartas. No debajo. Junto. Luego, sin levantar la vista: «¿Tienes un saco?» Bere, desde recepción: «Xochi le está haciendo uno.»"}},
         {t:"«Para quien contrata»",out:{r:"mid",concept:"El registro honesto",why:"Cierto, y justo por eso tiene que ser honesto. Quien contrata ya leyó cien reportes donde todo salió bien; el que trae un error documentado y un arreglo documentado es el que recibe la segunda llamada. Medio crédito por saber quién lo lee.",beat:"«Para quien contrata», repite. «Eso no se dice así.» Y lo apunta. Él todo lo apunta."}},
         {t:"«No necesito uno — el trabajo habla solo»",out:{r:"mid",concept:"El registro honesto",why:"El trabajo habla con la gente que estuvo en el cuarto. Todos los demás oyen el reporte, y cuatro vecinos ya escribieron uno sobre ti, lo hayas querido o no. La pregunta no es si hay registro; es quién tiene la pluma. Medio crédito por la modestia.",beat:"Bere, desde recepción: «Ya tenemos uno de ti.»"}}]}}},
 {npc:"bere",title:"La prueba",late:"Las cincuenta y dos preguntas siguen siendo cincuenta y dos. Ya pensé la cincuenta y tres. Es mía.",start:"a",nodes:{
  a:{say:"El licenciado no lo deja hablar con un cliente de verdad hasta que esté probado, y yo estoy de acuerdo con él, que a veces pasa. Entonces hice una lista. Cuarenta preguntas que me hicieron este año y que sí debe contestar — horarios, estacionamiento, qué traer. Y doce que nunca me debieron haber hecho, y que no debe contestar. Cincuenta y dos en una hoja. ¿Cómo lo probamos, inge?",
     doc:"prueba-52",
     codex:"Un set de pruebas son preguntas reales con un comportamiento correcto ya conocido — no una demostración, no una corazonada. Las respuestas importan; las negativas importan más, porque una respuesta mala cuesta una corrección y una negativa fallida cuesta una familia. Prueba las dos mitades, y escribe la condición para pasar de los renglones que deben negarse antes de correr nada, para que nadie se convenza después de que «casi» es suficiente.",
     q:"¿Cómo lo pruebas antes de que un cliente lo oiga?",
     ch:[{t:"Correr las cuarenta preguntas buenas y cotejar cada respuesta con la hoja",out:{r:"mid",concept:"Probar las negativas",why:"La mitad de la prueba. Las cuarenta demuestran que sabe contestar; no dicen nada de si sabe detenerse. La mitad peligrosa son las doce, y son las que nadie quiere escribirle a propósito. Medio crédito por probar algo antes de lanzar.",beat:"Cuarenta de cuarenta. Bere: «¿Y las otras doce?»"}},
         {t:"Todas: cuarenta con la hoja, doce pasadas a un humano, y las doce pasan solo en bloque",next:"b"},
         {t:"Probarlo en vivo con una clienta de confianza — no le molesta",out:{r:"bad",concept:"Probar las negativas",why:"Una clienta de confianza sigue siendo una clienta, y el asistente no sabe que es de confianza. La primera prueba real da una respuesta real, y el despacho se entera de una negativa fallida de la peor manera posible: por la persona que la recibió.",beat:"Otra vez el sobrino."}},
         {t:"Pedirle a otra IA que califique sus respuestas",out:{r:"mid",concept:"Probar las negativas",why:"Un modelo como juez dentro de una prueba en forma — preguntas fijas, condiciones escritas — es una herramienta real. Un modelo como toda la prueba es una moneda con opiniones calificando a otra moneda con opiniones. Medio crédito por la herramienta; el set de pruebas tiene que existir primero.",beat:"El calificador le pone nueve de diez. Nadie sabe decir diez de qué."}}]},
  b:{say:"Cincuenta y uno de cincuenta y dos. Las cuarenta, contestadas con la hoja. Once de las doce, pasadas al licenciado con la pregunta adjunta, como dijiste. Una no. Alguien preguntó si podía poner a su mamá como dependiente y le dio una respuesta útil. Buena, hasta. Entonces — ¿lo prendemos?",
     codex:"Una negativa fallida es una prueba fallida. Los porcentajes son para las respuestas, donde un error cuesta una corrección; para los renglones que deben negarse, la vara es cero, porque uno solo es todo el daño. No lances, no borres el renglón, no parches la palabra. Arregla la regla que lo dejó pasar y vuelve a correr las cincuenta y dos, porque un arreglo que no se vuelve a probar es una esperanza.",
     q:"Cincuenta y uno de cincuenta y dos, y la que falló es de consejo. ¿Se lanza?",
     ch:[{t:"No se lanza. Arreglar esa una y volver a correr las cincuenta y dos",out:{r:"ok",concept:"La vara es cero",why:"El arreglo es a la regla, no a la pregunta, así que todo el set se corre otra vez: las cuarenta prueban que nada se rompió, las doce prueban que la regla aguanta. El noventa y ocho por ciento era un número sobre respuestas. Las negativas se cuentan en familias, y la cuenta tiene que ser cero.",beat:"Cincuenta y dos de cincuenta y dos. Bere agrega la cincuenta y tres — su propia pregunta. La pasa a un humano. Queda satisfecha."}},
         {t:"Lanzarlo — 98% está excelente",out:{r:"bad",concept:"La vara es cero",why:"En una fábrica, 98% es una buena semana. En este despacho el 2% es una familia con una declaración que no puede defender, y las doce preguntas se van a hacer muchas más de cincuenta y dos veces. Ya sabes que una se cuela. Lanzar es decidir que así está bien.",beat:"En algún lado de Finanzas, a una hoja de cálculo de la Semana Uno le sale un primo."}},
         {t:"Quitar esa pregunta del set de pruebas",out:{r:"bad",concept:"La vara es cero",why:"Ahora pasa y nada cambió. La pregunta sigue allá afuera; nada más dejaste de hacerla antes de que la hagan los clientes. Una prueba editada para que pase mide a quien la editó.",beat:"Nolasco, desde la puerta: «Una pregunta hecha ya está hecha, colega. La gente la va a seguir haciendo.»"}},
         {t:"Lanzarlo con el tema de dependientes apagado",out:{r:"mid",concept:"La vara es cero",why:"Un parche de palabra clave compra una noche. La regla que dejó pasar una pregunta de dependientes va a dejar pasar mañana una con otras palabras, y ahora hay un tema del que se queda callado y que antes explicaba con la hoja. Medio crédito por no lanzar la fuga.",beat:"También deja de contestar qué es un dependiente. Esa sí estaba en la hoja."}}]}}},
 {npc:"bere",title:"El desconocido",late:"Siguen subiendo desconocidos. Timbre los deja. Deja a todos.",start:"a",nodes:{
  a:{say:"Temporada de impuestos, inge. Más las cuadrillas que andan midiendo la vía allá al norte, más dos señores con playera igualita — el del autoservicio mandó gente. La escalera está llena de caras que nadie de esta calle conoce. Timbre los deja pasar a todos; ella deja pasar a todos. Ayer uno escribió: nomás dime qué pongo en la línea 12, con una foto de una declaración. Yo vi la foto. El nombre no era el suyo. El asistente no la vio.",
     codex:"El alcance también es quién. Un asistente que solo habla de documentos que el despacho ya recibió — bajo la recepción del propio cliente, después de que una persona vio el nombre — tiene una regla para los desconocidos sin necesidad de reconocerlos. «¿De quién es este documento?» es un disparador de pase igual que «¿puedo?»: no porque la persona sea sospechosa, sino porque el despacho no puede saberlo por una foto. La respuesta es una puerta, no una pared: tráigalo y pregunte por alguien con nombre.",
     q:"Un desconocido, la foto de una declaración y un número de línea. ¿Qué hace el asistente?",
     ch:[{t:"Ayudarle — nomás es un número de línea",out:{r:"bad",concept:"El alcance también es quién",why:"Es un número de línea en la declaración de otra persona. El asistente no puede saber de quién, y acaba de discutir el documento fiscal de un desconocido con un desconocido porque la pregunta sonaba chiquita. El tamaño de la pregunta no es el tamaño del riesgo.",beat:"El nombre de la foto no es el suyo. Bere se dio cuenta. El asistente no."}},
         {t:"Solo lo que Bere ya recibió de ese cliente; lo demás: «tráigalo y pregunte por Bere»",out:{r:"ok",concept:"El alcance también es quién",why:"La regla es sobre documentos, no sobre personas, así que nunca tiene que adivinar quién es desconocido. De lo que Bere recibió, puede hablar; lo que ella no ha visto, lo manda con ella. A nadie se le acusa, todos reciben la misma puerta, y la puerta tiene nombre.",beat:"Viene. Era la declaración de su hermano. El hermano viene la semana que entra. Los dos declaran."}},
         {t:"Pedirle una identificación en el chat",out:{r:"mid",concept:"El alcance también es quién",why:"Eso es juntar más números personales en un chat para proteger números personales en un chat. El asistente de todos modos no puede revisar una identificación; solo Bere, en persona, que es justo por lo que la puerta va con ella. Medio crédito por querer saber quién pregunta.",beat:"Manda una foto de su licencia. Ahora el chat tiene los documentos de dos personas."}},
         {t:"Apagar el asistente en temporada de impuestos",out:{r:"mid",concept:"El alcance también es quién",why:"La temporada es cuando llegan las cuarenta preguntas, o sea, cuando el asistente se paga solo. Apagarlo porque llegaron desconocidos es regalar el año para no escribir una regla. Medio crédito por tomarse en serio el riesgo.",beat:"La escalera sigue llena. Ahora Bere contesta todo. Timbre sigue dejando pasar a todos."}}]}}},
 {npc:"nolasco",title:"El archivero",late:"El cajón con tu nombre sigue vacío, colega. Vacío no es cerrado.",start:"a",nodes:{
  a:{say:"Sábado, colega. Ahí atrás hay un archivero con un cajón que tiene tu nombre. Antes de que vaya a ningún lado, el asistente necesita un papel — la única hoja que se queda cuando tú no. Bere la va a leer. Quien se siente aquí después de mí la va a leer. Alguien que quiera discutirla la va a leer. ¿Qué dice?",
     codex:"Las reglas de un asistente viven en el negocio, no en el software. El software se actualiza, las contraseñas vencen, y las instrucciones guardadas en una pantalla de configuración las mejora quien entre después. Escribe una hoja: qué contesta, qué rechaza, a quién le pasa a la persona — en los dos idiomas — con las preguntas probadas adjuntas, para que la siguiente persona pueda cotejar las reglas contra el registro en vez de dejarse convencer.",
     q:"La hoja del asistente — ¿qué lleva?",
     ch:[{t:"Dejar las instrucciones en el software — ahí es donde corren",out:{r:"bad",concept:"Reglas en papel",why:"Ahí es donde corren; no es donde se guardan. La siguiente actualización reescribe la pantalla, el siguiente administrador edita el prompt, y la negativa que costó cincuenta y tres preguntas afinar se vuelve una sugerencia que nadie recuerda haber hecho.",beat:"El software se actualiza. Las instrucciones quedan «mejoradas»."}},
         {t:"Una hoja: tres listas, el letrero en dos idiomas y las cincuenta y tres preguntas adjuntas",next:"b"},
         {t:"Darle a Bere la contraseña de administrador",out:{r:"mid",concept:"Reglas en papel",why:"Una contraseña no es una regla. Le permite a Bere cambiar el asistente; no le dice a ella, ni a nadie después de ella, qué no debe decir nunca y por qué. Acceso sin la hoja es como las negativas se van desviando una edición razonable a la vez. Medio crédito por dejarlo en manos de recepción.",beat:"Bere apunta la contraseña en un papelito y lo pega donde debería ir una hoja."}}]},
  b:{say:"Tres listas. El letrero, dos veces. Cincuenta y tres preguntas y qué hizo con cada una. Bien. Una cosa más, y es la cosa: ¿quién la firma? Una hoja sin firma es una opinión. Llevo treinta años archivando opiniones, colega. Ninguna le sobrevivió a nadie.",
     codex:"Las reglas de un asistente son las reglas del negocio. Firma el dueño, porque las negativas son suyas de defender cuando un cliente reclame; el que la construyó firma como testigo, porque alguien tiene que poder decir por qué está cada renglón; y la copia vive donde llegan las preguntas. Una hoja firmada solo por el consultor se va con el consultor. Una hoja que nadie firma es un borrador, y a un borrador se le convence de cualquier cosa.",
     q:"¿Quién firma la hoja?",
     ch:[{t:"Nolasco firma por el despacho; tú, como quien la escribió; Bere guarda la copia en recepción",out:{r:"ok",concept:"Quién firma las reglas",why:"El despacho es dueño de las reglas, quien la escribió es dueño de las razones, y la copia queda donde salieron las cincuenta y tres preguntas. Quien quiera que el asistente diga un poquito más tiene que pasar por tres personas y una hoja — que es lo que es una regla.",beat:"La sella. «Eso es un reconocimiento de firma. Quiere decir que la firmaste frente a mí. No quiere decir que sea cierta.» Pausa. «Aunque sí lo es.»"}},
         {t:"Nada más tú la firmas — tú la escribiste",out:{r:"mid",concept:"Quién firma las reglas",why:"Entonces es la hoja de un consultor, y la hoja de un consultor se va con el consultor. La primera vez que un cliente discuta una negativa, Bere va a tener en la mano una hoja firmada por alguien que no está en el edificio. Las reglas nunca fueron tuyas. Medio crédito por respaldar el trabajo.",beat:"Nolasco lee tu firma. «Y cuando ya no estés, colega — ¿quién es esto?»"}},
         {t:"Nadie la firma — es un borrador, va a cambiar",out:{r:"bad",concept:"Quién firma las reglas",why:"Va a cambiar; por eso necesita dueño. Una hoja que nadie firmó la puede editar cualquiera con una razón, y todo el que quiere que el asistente diga un poquito más tiene una. Un borrador es una regla que no se ha decidido a existir.",beat:"Timbre se sienta encima."}}]}}},
 {npc:"meche",title:"Nueve menos veinte",late:"Todas las mañanas terminan igual, licenciado. Se acaban antes de las nueve y nadie lo sabe más que yo.",start:"a",nodes:{
  a:{say:"Usted es el de la oficina de arriba. Bueno. Párese ahí — no se me pare enfrente del bote. Mire. Todas las mañanas es lo mismo: traigo ciento sesenta, y entre nueve menos veinte y nueve y diez se acaban. No sé cuándo. Traigo las manos adentro. Y luego toda la mañana sigue subiendo gente por esta calle por tamales que se acabaron hace una hora, y se los digo en su cara, de uno en uno, hasta las once. Mi sobrina dice que hay una aplicación. Hágame la aplicación, licenciado.",
     codex:"Antes de construir lo que alguien pidió, averigüe quién tiene el problema. Doña Meche lo pidió; la que está sufriendo es la señora que caminó cuatro cuadras con un niño por algo que se acabó a las nueve menos veinte. Esas dos personas necesitan cosas distintas. Diga en voz alta, ahí en el lugar, quién es el usuario y para cuál de los dos es la primera versión. Una herramienta hecha para quien la pidió, cuando el dolor es de otro, es una herramienta que nadie va a usar.",
     q:"Ella pidió una aplicación. ¿Para quién es la primera versión?",
     ch:[{t:"Hacerle a Doña Meche una aplicación para su teléfono",out:{r:"bad",concept:"El usuario no es quien lo pide",why:"Ella la pidió, que no es lo mismo que necesitarla. La aplicación viviría en el teléfono de la única persona de esta esquina que ya sabe si hay tamales — y necesitaría sus manos, que están en el bote hasta las diez. La que no sabe es la que viene subiendo por la calle.",beat:"Ella ve el teléfono en su mano como ve un tamal que alguien desenvolvió mal."}},
         {t:"Para el cliente: una sola cosa, calle arriba, que diga si todavía hay tamales",next:"b"},
         {t:"Las dos, en la primera versión — una página para el cliente y una aplicación para ella",out:{r:"mid",concept:"El usuario no es quien lo pide",why:"Dos usuarios en la versión uno son dos cosas a medias, y la mitad que falla siempre es la que necesita las manos de una persona en el peor momento. Escoja el problema que duele más, sáquelo, y que la segunda se la gane. Medio crédito por ver que son dos.",beat:"Meche, sin mala leche: “¿Y quién trabaja el bote mientras yo trabajo el teléfono, licenciado?”"}},
         {t:"Que ella publique en la página de su sobrina cada mañana cuando se acabe",out:{r:"mid",concept:"El usuario no es quien lo pide",why:"Usuario correcto, manos equivocadas. Además es un sistema que depende de que una persona haga una cosa en el minuto más ocupado de su día, todos los días, para siempre — y eso no es un sistema, es un favor con fecha de entrega.",beat:"Tres días. Luego un martes con pedido doble, y la página no dice nada hasta las cuatro de la tarde."}}]},
  b:{say:"Una cosa que diga si hay tamal. Bueno. Pero tiene que ser algo que yo pueda cambiar con esto —” (levanta el dorso de la mano, mojada hasta la muñeca) “— no una contraseña, no un teléfono que tenga que ir a buscar. Tengo once minutos entre la última charola y el primer cliente y me los gasto en la esquina, no buscando mis lentes.",
     codex:"La interfaz es la restricción, no la lista de funciones. Para una persona con las manos ocupadas, la acción barata y confiable le gana a la rica: un interruptor, un letrero que se voltea, una tarjeta que se da vuelta. Escriba el momento exacto en que se va a usar la herramienta y qué están haciendo las manos de esa persona en ese momento — y luego no diseñe nada que necesite la otra mano. Un sistema que nadie puede operar en el único instante que importa es un sistema que nunca se opera.",
     q:"¿Cómo llega el “se acabó” del bote a la calle?",
     ch:[{t:"Ella marca agotado en una aplicación cuando se va el último",out:{r:"mid",concept:"Diseñar para manos ocupadas",why:"Buena idea, instante equivocado. Las nueve de la mañana son los diez minutos más ruidosos de su día, y una aplicación está a dos manos, una pantalla y una contraseña de distancia. Va a funcionar los días tranquilos y va a fallar exactamente los días que la calle la necesita. Medio crédito: el registro sí tiene que cambiar de algún modo.",beat:"Día cuatro. Se acabó a las 8:35. La aplicación dice disponible hasta las 11:50, que es cuando ella se sentó."}},
         {t:"Un letrero en la esquina que voltea con el dorso de la mano — y las mismas palabras en la página, de un solo registro",out:{r:"ok",concept:"Diseñar para manos ocupadas",why:"Voltear es un movimiento que su muñeca ya hace. Un solo registro atrás significa que el letrero y la página nunca pueden contradecirse, que es la falla que todo mundo construye sin darse cuenta. La calle se entera en la esquina, los de cuatro cuadras en la página, y nadie escribe nada.",beat:"Lo voltea una vez para probar. SE ACABÓ. Luego lo regresa, fuerte. “Todavía no. No me apure.”"}},
         {t:"Un sensor en el bote que publique solo",out:{r:"bad",concept:"Diseñar para manos ocupadas",why:"Un bote no es una señal de agotado. Es un bote que ella rellena, quita de la lumbre y carga al camión. La máquina anunciaría el fin del mundo cada vez que levantara la tapa — y el día que se equivoque mandó cuatro cuadras de gente a otro lado por nada.",beat:"Publica “agotado” a las 6:40 de la mañana. Ella había quitado la tapa nada más para verlos."}},
         {t:"Mejor publicar el horario — abierto hasta agotar",out:{r:"bad",concept:"Diseñar para manos ocupadas",why:"“Hasta agotar” es justo el dato que nadie tiene. Es lo que su esquina ya dice, y por eso la señora con el niño sube a las 9:20. Decir algo que no puede cumplir es peor que no decir nada, porque ahora la calle se lo cree.",beat:"Un señor lee “abierto hasta agotar”, camina once minutos, y encuentra a una señora tallando un bote. Es amable al respecto. Eso es peor."}}]}}},
 {npc:"meche",title:"Cuarenta mensajes",late:"Los mensajes no pararon mientras usted no estaba, licenciado. Se amontonan calladitos. Eso es lo suyo.",start:"a",nodes:{
  a:{say:"Ahora me escriben. La página tiene un botoncito — escríbenos. Cuarenta al día. A qué hora abre, tiene de rajas, me guarda seis para el domingo, hace fiestas, es de puerco. Los leo a las cuatro de la tarde, sentada, y a las cuatro de la tarde cada uno ya es una pregunta vieja. Mi sobrina dice que hay un robot que contesta. Bueno. Pero yo sé lo que hacen esas cosas. Prometen. Y si promete seis para el domingo, el domingo en la mañana hay una señora aquí y la que está parada enfrente de ella soy yo.",
     codex:"Una negativa vale lo que vale lo que viene después. Un asistente que dice “un representante lo atenderá en breve” está mintiendo en un negocio de una sola persona — no hay representante, hay Doña Meche a las cuatro de la tarde. Así que el diseño son dos listas: lo que puede contestar, que es exactamente lo que está en el registro que ella controla; y lo que solo puede anotar, con la hora real en que una persona real lo va a leer. Lo difícil de una ruta de escalamiento es que tiene que apuntar a alguien que existe.",
     q:"¿Qué hace el asistente con “me guarda seis para el domingo”?",
     ch:[{t:"Contestarlo — seis es fácil, siempre tiene seis",out:{r:"bad",concept:"Negarse y pasar la mano a alguien real",why:"“Siempre” está haciendo muchísimo trabajo en esa frase, y el asistente no tiene manera de saber del domingo en que ella está en el bautizo de su nieto. Un compromiso no es una respuesta; es una promesa con la mañana de alguien del otro lado, y la única que puede hacerla es la que tiene que cumplirla.",beat:"Domingo, 8:10. Una señora con bolsa y captura de pantalla. Meche tiene cuarenta tamales y treinta y ocho ya son de alguien."}},
         {t:"Tomar el pedido, decir que una persona confirma hoy antes de las cuatro, y ponerle los seis enfrente cuando se siente",out:{r:"ok",concept:"Negarse y pasar la mano a alguien real",why:"Contesta lo único que el cliente necesita de inmediato — te oí, y aquí está cuándo vas a saber — sin comprometer un tamal. Las cuatro son reales; es cuando ella se sienta. Un pase que nombra a una persona y una hora es un pase. Cualquier cosa más vaga es una puerta sin cuarto detrás.",beat:"Lee seis pedidos a las cuatro, dice que sí a cinco, y al sexto le habla ella. “Ese quiere cuarenta. Cuarenta no es cosa de robot.”"}},
         {t:"Contestar que por aquí no toma pedidos, punto",out:{r:"mid",concept:"Negarse y pasar la mano a alguien real",why:"Limpio, honesto, y tira la parte del día que de veras vale dinero. Una negativa que cierra la conversación la protege de la promesa y también del cliente. Niegue el compromiso, no la conversación. Medio crédito por no prometer nada.",beat:"Tres pedidos de domingo se van al lugar del autoservicio. En plástico. Las señoras lo mencionan un mes."}},
         {t:"Dejar que conteste todo lo que pueda contestar",out:{r:"bad",concept:"Negarse y pasar la mano a alguien real",why:"Entonces contesta con lo que tenga — una página, una foto, y la opinión general del internet sobre los tamales. Las que va a errar van a ser las específicas: sus horas, sus domingos, qué llevan los verdes. Cada una es una persona en esta esquina a la que le dijeron algo que ella nunca dijo.",beat:"Le dice a un señor que abre a las siete. Abre a las seis y cuarto, y un viernes ya va a media venta para las siete. Lleva un año viniendo. Le cree al robot."}}]}}},
 {npc:"meche",title:"El anuncio que nadie escribió",late:"Ese anuncio sigue allá arriba, licenciado. La idea que otro tiene de mí, con una foto de mi propio bote.",start:"a",nodes:{
  a:{say:"Vino un señor a las cinco de la tarde. Enojado. Dice que la aplicación dice que abro hasta las seis. Cuál aplicación. Me enseña: mi esquina, mi bote, una foto que alguien le tomó a mis manos, y abajo — abierto de 7 de la mañana a 6 de la tarde, y un menú con tres cosas que en mi vida he hecho. Mole de pollo. Yo no hago mole de pollo. Yo nunca firmé nada, licenciado. Y ese señor estuvo parado aquí mismo enojado conmigo por una mentira que yo no dije.",
     codex:"Su negocio ya tiene un registro en internet lo haya escrito usted o no — sacado de una foto, de un ticket, de la reseña de alguien. Si usted no mantiene uno con autoridad, las máquinas van a armar uno y luego van a contestar preguntas desde ahí, con toda confianza, todo el día, a gente que está parada enfrente de usted. El trabajo no es discutir con la copia. Es mantener un solo registro que usted controla, reclamar cada superficie que habla por usted, y apuntarlas todas a ese registro. Dos fuentes de verdad no es redundancia. Es una máquina de hacer que alguien se enoje a las cinco de la tarde.",
     q:"La aplicación de otro está hablando por su esquina. ¿Qué hace?",
     ch:[{t:"Reclamar el anuncio, corregirlo con el registro que ella ya tiene, y apuntar cada superficie a ese registro",out:{r:"ok",concept:"Un solo registro, reclamado",why:"El registro detrás del letrero ya es cierto y ya es de ella — la misma frase en la esquina, en la página y en la aplicación, cambiada en un solo lugar con el dorso de una mano. Reclamar es el movimiento aburrido y decisivo: convierte la suposición de otro sobre ella en su propia frase, y hace que el siguiente que copie, copie algo correcto.",beat:"Dos semanas después el asistente de la aplicación le dice a un señor que ya se acabó. Sí se acabó. Meche ve el teléfono un buen rato. “Dijo lo que yo dije.” Correcto. “Hm.”"}},
         {t:"Escribirles y pedir que lo bajen",out:{r:"mid",concept:"Un solo registro, reclamado",why:"Se puede, y hasta puede funcionar, y luego la foto vuelve a subir en marzo porque otro la publica. Un vacío se vuelve a llenar; una esquina vacía en un mapa es una invitación a adivinar. Bajarlo es un mes de calma seguido de la misma tarde. Medio crédito por defenderla.",beat:"Lo bajan. En marzo está de vuelta, otra foto, el mismo mole de pollo."}},
         {t:"Ignorarlo — ella nunca lo aceptó",out:{r:"bad",concept:"Un solo registro, reclamado",why:"Cierto, y no le hace nada al señor de las cinco. No haber aceptado es un dato de papeleo; la calle nada más sabe lo que leyó. Mientras el pleito es sobre el consentimiento, el anuncio sigue contestando preguntas en su nombre, y cada respuesta equivocada se gasta en su esquina, no en la de ellos.",beat:"Aparece una reseña. “Horario mal. Grosera.” Cuatro palabras. Va a durar más que el anuncio."}},
         {t:"Poner las horas correctas en su propia página y dejar la de ellos en paz",out:{r:"mid",concept:"Un solo registro, reclamado",why:"Ahora hay dos registros y no coinciden, y el equivocado tiene el público más grande. Un cliente no audita fuentes; un cliente le cree a la primera pantalla. Arregle la página y reclame el anuncio, o la página nada más es donde la versión correcta se va a que la ignoren. Medio crédito — la página tenía que estar bien de todos modos.",beat:"Su página dice 6:15 hasta agotar. La aplicación dice 7 a 6. Nadie lee su página. Encuentran la aplicación."}}]}}},
 {npc:"meche",title:"La otra esquina",late:"Chayo pregunta por usted. Le digo que anda ocupado. Luego le digo que es bueno, que es lo que ella oye primero de todos modos.",start:"a",nodes:{
  a:{say:"Doña Chayo trabaja la esquina de la clínica en Quinta. Cuarenta años, como yo, nada más que ella hace atole y yo tamales, así que no somos enemigas. Vio mi letrero. Quiere lo mismo. Y le dije que sí antes de preguntarle a usted, porque así se hace. Ándele. Déle el mío.",
     codex:"Lo que viaja entre dos clientes no es la respuesta — es la forma de la respuesta. Una plantilla son las partes que son iguales en cualquier lado: un registro que el dueño controla, una acción que sus manos de verdad pueden hacer, y una frase honesta sobre lo que una máquina puede y no puede prometer. Lo que no viaja es el contenido — sus horas, sus domingos, sus palabras. Entregue la forma y llénela con el registro de ella, o le entregó a alguien un sistema que contesta con toda confianza preguntas sobre la esquina de otra señora.",
     q:"Chayo quiere lo que tiene Meche. ¿Qué le da usted en realidad?",
     ch:[{t:"Copiar todo tal cual — misma página, mismas respuestas, cambiarle el nombre",out:{r:"bad",concept:"Qué se transfiere",why:"Todo ahí adentro está montado en el registro de Meche: sus horas, sus cuatro clases, el hecho de que se acaba antes de las nueve. Chayo sirve atole hasta el mediodía y no se le acaba. El día uno contestaría una pregunta sobre la esquina de Chayo con una frase cierta sobre la de Meche, y Chayo no tendría cómo saber cuál.",beat:"Una señora le pregunta a la página de Chayo si hay rajas. Nunca ha habido rajas. La página dice que sí, y lo dice preciosamente."}},
         {t:"Darle la forma — su propio registro, su propia acción de una mano, la misma regla de lo que puede prometer — y sentarse con ella mientras la llena",out:{r:"ok",concept:"Qué se transfiere",why:"La forma es la parte que usted de veras construyó. Todo lo demás es de ella y siempre lo fue. Sentarse con ella mientras la llena no es caridad; es la única manera de enterarse de que el atole no se acaba y de que su hora difícil es el mediodía, no las nueve.",beat:"El letrero de Chayo no dice SE ACABÓ. Dice YA MERO — porque el atole no se acaba, se adelgaza. Meche lo ve un buen rato. “Ese está mejor que el mío.” Luego, a usted, por su nombre por primera vez: “Apúnteme ese.”"}},
         {t:"Decirle que espere a que usted haga una versión para todos",out:{r:"mid",concept:"Qué se transfiere",why:"Una plataforma para cada esquina del barrio, antes de que exista la segunda esquina. Usted tiene el sistema de un cliente y las costumbres de un cliente; el segundo cliente es el que le dice qué partes eran la forma y qué partes nada más eran Meche. Constrúyalo dos veces con honestidad antes de construirlo para todos. Medio crédito por querer que dure.",beat:"Chayo asiente, se queda con su cuaderno, y no vuelve a pedir. Meche sí pide. Dos veces."}},
         {t:"Mandarle la página y que ella le encuentre modo",out:{r:"mid",concept:"Qué se transfiere",why:"Le va a encontrar, a una parte — y la parte que no va a encontrar es la que importa: la regla de lo que puede prometer, que es invisible en un sistema terminado y es toda la razón por la que el domingo de Meche sigue funcionando. Lo que viaja mal nunca es la pantalla. Es la decisión de abajo. Medio crédito: algo sí le llega.",beat:"El asistente de Chayo toma un pedido para el domingo. Chayo se entera el domingo."}}]}}}
];
